window.QB_PAPERS=window.QB_PAPERS||{};window.QB_PAPERS["p4999a05dc1"]={"id":"p4999a05dc1","name":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）","year":2024,"region":"江苏","count":129,"types":{"时事政治":3,"新思想":1,"人文常识":9,"科技常识":2,"片段阅读":17,"语句表达":3,"逻辑填空":10,"数学运算":19,"类比推理":13,"图形推理":15,"逻辑判断":7,"定义判断":10,"综合":8,"增长":10,"比重":2},"modules":["政治理论","常识判断","言语理解与表达","数量关系","判断推理","资料分析"],"moduleCounts":{"政治理论":4,"常识判断":11,"言语理解与表达":30,"数量关系":19,"判断推理":45,"资料分析":20},"coverage":{"basis":"网友回忆版","sourceCount":129,"expectedCount":null,"missingCount":null},"questions":[{"qid":"13628288","no":1,"type":"时事政治","module":"政治理论","stem":"<p>党的二十大报告指出，中国式现代化既有各国现代化的共同特征，更有基于自己国情的中国特色。关于中国式现代化的内涵和意义，下列表述正确的是：<br>①有与世界各国现代化相同的任务<br>②是人类历史上难度最大的现代化<br>③是独立自主、和平发展的现代化<br>④创造了一种全新的人类文明形态</p>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"D","multi":false,"explanation":"<p>本题考查政治常识。<br>①错误，②正确，习近平总书记在《中国式现代化是强国建设、民族复兴的康庄大道》的文章中指出：“第一，人口规模巨大的现代化。这是中国式现代化的显著特征。人口规模不同，现代化的任务就不同，其艰巨性、复杂性就不同，发展途径和推进方式也必然具有自己的特点。现在，全球进入现代化的国家也就20多个，总人口10亿左右。中国14亿多人口整体迈入现代化，规模超过现有发达国家人口的总和，将极大地改变现代化的世界版图。这是人类历史上规模最大的现代化，也是难度最大的现代化。”<br>③正确，习近平总书记在《中国式现代化是强国建设、民族复兴的康庄大道》的文章中指出：“第五，走和平发展道路的现代化。坚持和平发展，在坚定维护世界和平与发展中谋求自身发展，又以自身发展更好维护世界和平与发展，推动构建人类命运共同体，是中国式现代化的突出特征······中国式现代化坚持独立自主、自力更生，依靠全体人民的辛勤劳动和创新创造发展壮大自己，通过激发内生动力与和平利用外部资源相结合的方式来实现国家发展，不以任何形式压迫其他民族、掠夺他国资源财富，而是为广大发展中国家提供力所能及的支持和帮助。”<br>④正确，党的二十大报告中“三、新时代新征程中国共产党的使命任务”指出：“中国式现代化的本质要求是：坚持中国共产党领导，坚持中国特色社会主义，实现高质量发展，发展全过程人民民主，丰富人民精神世界，实现全体人民共同富裕，促进人与自然和谐共生，推动构建人类命运共同体，创造人类文明新形态。”<br>故②③④表述正确。<br>故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"政治理论"},"idx":0,"pid":"p4999a05dc1"},{"qid":"17900780","no":2,"type":"新思想","module":"政治理论","stem":"<p>2023年7月，习近平总书记在全国生态环境保护大会上指出，新时代生态文明建设的成就举世瞩目，成为新时代党和国家事业取得历史性成就、发生历史性变革的显著标志。关于新时代生态文明建设的成就，下列表述正确的是：<br>①形成了新时代中国特色社会主义生态文明思想<br>②实现了山水林田湖草沙的一体化保护和系统治理<br>③根本缓解了生态环境保护的结构性、根源性、趋势性压力<br>④增强了全党全国推进生态文明建设的自觉性主动性</p>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"B","multi":false,"explanation":"<p>本题考查政治常识。<br>①正确：习近平总书记在全国生态环境保护大会上的讲话中强调，不断深化对生态文明建设规律的认识，形成新时代中国特色社会主义生态文明思想，实现由实践探索到科学理论指导的重大转变。经过顽强努力，我国天更蓝、地更绿、水更清，万里河山更加多姿多彩。<br>②正确：习近平总书记在全国生态环境保护大会上的讲话中指出，要坚持山水林田湖草沙一体化保护和系统治理，构建从山顶到海洋的保护治理大格局，综合运用自然恢复和人工修复两种手段，因地因时制宜、分区分类施策，努力找到生态保护修复的最佳解决方案。<br>③错误：习近平总书记在全国生态环境保护大会上的讲话中强调，我国生态环境保护结构性、根源性、趋势性压力尚未根本缓解。我国经济社会发展已进入加快绿色化、低碳化的高质量发展阶段，生态文明建设仍处于压力叠加、负重前行的关键期。必须以更高站位、更宽视野、更大力度来谋划和推进新征程生态环境保护工作，谱写新时代生态文明建设新篇章。<br>④正确：习近平总书记在全国生态环境保护大会上的讲话中强调，坚持转变观念、压实责任，不断增强全党全国推进生态文明建设的自觉性主动性，实现由被动应对到主动作为的重大转变。<br>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"政治理论"},"idx":1,"pid":"p4999a05dc1"},{"qid":"17900950","no":3,"type":"时事政治","module":"政治理论","stem":"<p>2023年10月18日，习近平主席在第三届“一带一路”国际合作高峰论坛上宣布，中国将采取行动支持高质量共建“一带一路”。关于中国将采取的行动，下列表述正确的有：<br>①支持建设开放型世界经济<br>②完善“一带一路”国际合作机制<br>③构建“一带一路”立体互联互通网络<br>④启动“一带一路”科技创新行动计划</p>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"②③④"},{"k":"D","t":"①③④"}],"answer":"A","multi":false,"explanation":"<p>本题考查政治常识。<br>①②③正确：2023年10月18日，习近平主席在第三届“一带一路”国际合作高峰论坛开幕式上发表了题为《建设开放包容、互联互通、共同发展的世界》的主旨演讲，宣布了中国支持高质量共建“一带一路”的八项行动，包括：构建“一带一路”立体互联互通网络、支持建设开放型世界经济、开展务实合作、促进绿色发展、推动科技创新、支持民间交往、建设廉洁之路、完善“一带一路”国际合作机制。<br>④错误：习近平主席在讲话中指出，中方将继续实施“一带一路”科技创新行动计划，举办首届“一带一路”科技交流大会，未来5年把同各方共建的联合实验室扩大到100家，支持各国青年科学家来华短期工作。故“启动‘一带一路’科技创新行动计划”说法错误。<br>故正确答案为A。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"政治理论"},"idx":2,"pid":"p4999a05dc1"},{"qid":"17900784","no":4,"type":"时事政治","module":"政治理论","stem":"<p>2023年10月召开的中央金融工作会议就打造现代金融机构和市场体系提出了三大重点方向。下列属于“三大重点方向”的是：<br>①推动股票发行注册制走深走实<br>②建设种类齐全的金融产品体系<br>③更好发挥资本市场的枢纽功能<br>④培育一流投资银行和投资机构</p>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"C","multi":false,"explanation":"<p>本题考查政治常识。<br>①③④正确，②错误：2023年10月30日至31日，我国金融领域最高规格的重要会议——中央金融工作会议在北京举行。会议指出，要着力打造现代金融机构和市场体系，疏通资金进入实体经济的渠道。优化融资结构，更好发挥资本市场枢纽功能，推动股票发行注册制走深走实，发展多元化股权融资，大力提高上市公司质量，培育一流投资银行和投资机构。<br>故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"政治理论"},"idx":3,"pid":"p4999a05dc1"},{"qid":"17900786","no":1,"type":"人文常识","module":"常识判断","stem":"<p>“千村示范、万村整治”工程(简称“千万工程”)实施20年来，推动千万乡村惊艳蝶变，为中国式现代化建设提供了宝贵经验。关于实施“千万工程”的重大意义，下列表述正确的是：<br>①成为建设美丽中国的实践源头和样板<br>②实现了全体人民共同富裕的奋斗目标<br>③推动“绿水青山就是金山银山”从理念变为现实<br>④促进农村发展方式变革并形成城乡融合发展新机制</p>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"C","multi":false,"explanation":"<p>本题考查政治常识。<br>①正确：“千万工程”成为建设美丽中国的实践源头。农村人居环境整治是建设美丽乡村、美丽中国的重要内容。浙江把人居环境整治同生态文明建设紧密结合起来，以美丽乡村建设行动计划全面提升“千万工程”，为建设美丽乡村、美丽中国提供了先行先试样板。<br>②错误：习近平总书记在党的二十大报告中指出，“中国式现代化是全体人民共同富裕的现代化。共同富裕是中国特色社会主义的本质要求，也是一个长期的历史过程”。我国目前还没有实现全体人民共同富裕的奋斗目标。<br>③正确：“千万工程”推动“绿水青山就是金山银山”从理念变为现实。“千万工程”持续改善农村人居环境，促进生态农业、低碳乡村发展，成为践行习近平生态文明思想的样板和典范。<br>④正确：“千万工程”促进农村地区变革发展理念、转变发展方式。“千万工程”在实施过程中，引导农村地区把整治村庄和经营村庄结合起来，把改善村容村貌与发展生产、富裕农民结合起来，走出了一条迈向农业高质高效、乡村宜居宜业、农民富裕富足的新路子。“千万工程”构建了城乡融合发展新机制。“千万工程”坚持统筹城乡发展，有效促进城市基础设施向农村延伸、城市公共服务向农村覆盖、城市现代文明向农村辐射，推动城乡一体化发展。<br>故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"常识判断"},"idx":4,"pid":"p4999a05dc1"},{"qid":"17900789","no":2,"type":"人文常识","module":"常识判断","stem":"<p>2023年完成的第三次全国农业种质资源普查，是中华人民共和国成立以来规模最大、覆盖范围最广、技术要求最高、参与人员最多的一次普查。关于农业种质资源，下列说法不正确的是：</p>","options":[{"k":"A","t":"农业种质资源工作属于社会公益性事业"},{"k":"B","t":"农业种质资源是现代种业发展的物质基础"},{"k":"C","t":"农业种质资源是培育突破性品种的亲本材料"},{"k":"D","t":"农业种质资源的主权由种植者和育种者拥有"}],"answer":"D","multi":false,"explanation":"<p>本题考查政治常识。<br>2020年2月11日，《国务院办公厅关于加强农业种质资源保护与利用的意见》（以下简称《意见》）发布。<br>A项正确：《意见》指出：“以习近平新时代中国特色社会主义思想为指导，全面贯彻党的十九大和十九届二中、三中、四中全会精神，落实新发展理念，以农业供给侧结构性改革为主线，进一步明确农业种质资源保护的基础性、公益性定位，坚持保护优先、高效利用、政府主导、多元参与的原则，创新体制机制，强化责任落实、科技支撑和法治保障，构建多层次收集保护、多元化开发利用和多渠道政策支持的新格局，为建设现代种业强国、保障国家粮食安全、实施乡村振兴战略奠定坚实基础。”<br>B项正确：《意见》指出：“农业种质资源是保障国家粮食安全与重要农产品供给的战略性资源，是农业科技原始创新与现代种业发展的物质基础。”<br>C项正确：种质资源又称遗传资源，种质是指生物体亲代传递给子代的遗传物质，它往往存在于特定品种之中。种质资源是培育突破性品种的亲本材料，如知名小麦品种郑麦9023、矮抗58、郑麦366等，正是从种质资源中提取出抗逆和抗病基因。<br>D项错误：《中华人民共和国种子法》第十一条第一款规定：“国家对种质资源享有主权。任何单位和个人向境外提供种质资源，或者与境外机构、个人开展合作研究利用种质资源的，应当报国务院农业农村、林业草原主管部门批准，并同时提交国家共享惠益的方案。国务院农业农村、林业草原主管部门可以委托省、自治区、直辖市人民政府农业农村、林业草原主管部门接收申请材料。国务院农业农村、林业草原主管部门应当将批准情况通报国务院生态环境主管部门。”<br>本题为选非题，故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"常识判断"},"idx":5,"pid":"p4999a05dc1"},{"qid":"17900788","no":3,"type":"人文常识","module":"常识判断","stem":"<p>马某与三个儿子签订了分家赡养协议：老大放弃分割家庭共有财产但也不履行赡养义务，老二、老三各分得一半的家庭共有财产并均等承担赡养义务。关于该分家赡养协议，下列说法正确的是：</p>","options":[{"k":"A","t":"是当事人真实的意思表示，合法有效"},{"k":"B","t":"体现了权利与义务的一致性，公平合理"},{"k":"C","t":"约定老大不承担赡养义务的内容无效"},{"k":"D","t":"分割家庭共有财产的约定违背公序良俗"}],"answer":"C","multi":false,"explanation":"<p>本题考查法律常识。<br>《中华人民共和国民法典》第二十六条第二款规定：“成年子女对父母负有赡养、扶助和保护的义务。”第一百五十三条规定：“违反法律、行政法规的强制性规定的民事法律行为无效。但是，该强制性规定不导致该民事法律行为无效的除外。违背公序良俗的民事法律行为无效。”由此可知，马某的三个儿子有赡养马某的义务，老大放弃分割家庭共有财产但也不履行赡养义务的约定违反法律规定，而不是违反公序良俗，因此，该协议无效。<br>故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"常识判断"},"idx":6,"pid":"p4999a05dc1"},{"qid":"17900797","no":4,"type":"人文常识","module":"常识判断","stem":"<p>刘某将一头耕牛出租给沈某，因沈某照管不周，耕牛走失。为此，双方达成赔偿协议，由沈某赔偿刘某2万元。沈某支付赔偿金后，发现耕牛被关押在邻近的农场。沈某与刘某便请求农场返还耕牛。农场认为耕牛毁坏了果园，拒绝返还。对此，下列说法正确的是：</p>","options":[{"k":"A","t":"耕牛毁坏果园，应由沈某承担赔偿责任"},{"k":"B","t":"沈某无须向农场支付耕牛关押期间的管护费"},{"k":"C","t":"刘某仅在2万元的限度内，向农场承担赔偿责任"},{"k":"D","t":"农场在获得刘某或沈某的赔偿之前有权关押耕牛"}],"answer":"A","multi":false,"explanation":"<p>本题考查法律常识。<br>A项正确，C项错误，根据《中华人民共和国民法典》第七百四十九条规定：“承租人占有租赁物期间，租赁物造成第三人人身损害或者财产损失的，出租人不承担责任。”题中，耕牛毁坏果园，应由承租人沈某承担赔偿责任。<br>B项错误，根据《中华人民共和国民法典》第三百一十七条第一款规定：“权利人领取遗失物时，应当向拾得人或者有关部门支付保管遗失物等支出的必要费用。”题中，沈某作为权利人应向农场支付耕牛关押期间的管护费。<br>D项错误，根据《中华人民共和国民法典》第三百一十四条规定：“拾得遗失物，应当返还权利人。拾得人应当及时通知权利人领取，或者送交公安等有关部门。”题中，农场应及时返还牛。<br>故正确答案为A。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"常识判断"},"idx":7,"pid":"p4999a05dc1"},{"qid":"17900795","no":5,"type":"人文常识","module":"常识判断","stem":"<p>我国要扎实做好非物质文化遗产的系统性保护，更好满足人民日益增长的精神文化需求，推进文化自信自强。关于非物质文化遗产，下列表述不正确的是：</p>","options":[{"k":"A","t":"是文化多样性中最富活力的重要组成部分"},{"k":"B","t":"包括古遗址、古墓葬、古建筑等文化实物或场所"},{"k":"C","t":"能在各社区或群体与自然和历史的互动中被不断地再创造"},{"k":"D","t":"是各族人民在长期的生产生活中创造的传统文化表现形式"}],"answer":"B","multi":false,"explanation":"<p>本题考查人文常识。<br>A项正确：非物质文化遗产是文化多样性中最富活力的重要组成部分，是人类文明的结晶和最宝贵的共同财富，承载着人类的智慧、人类历史的文明与辉煌。<br>B项错误，C项正确：根据联合国教科文组织《保护非物质文化遗产公约》，非物质文化遗产是指被各社区、群体，有时是个人，视为其文化遗产组成部分的各种社会实践、观念表述、表现形式、知识、技能以及相关的工具、实物、手工艺品和文化场所。这种非物质文化遗产世代相传，在各社区和群体适应周围环境以及与自然和历史的互动中，被不断地再创造，为这些社区和群体提供认同感和持续感，从而增强对文化多样性和人类创造力的尊重。而物质文化遗产是具有历史、艺术和科学价值的文物，包括遗址、古墓葬、古建筑等不可移动文物。<br>D项正确：根据《中华人民共和国非物质文化遗产法》，非物质文化遗产是指各族人民世代相传并视为其文化遗产组成部分的各种传统文化表现形式，以及与传统文化表现形式相关的实物和场所。<br>本题为选非题，故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"常识判断"},"idx":8,"pid":"p4999a05dc1"},{"qid":"17900949","no":6,"type":"科技常识","module":"常识判断","stem":"<p>谚语“蜻蜓低飞，天要下雨”，是人类通过观察动物的活动来预报天气所得到的经验总结。这一经验总结所体现的哲理是：</p>","options":[{"k":"A","t":"人类只有通过自己的实践活动才能把握信息"},{"k":"B","t":"人类的意识或思想活动是信息及其运动的中介"},{"k":"C","t":"人类通过意识活动把握客观事物运动变化的规律"},{"k":"D","t":"人类观察动物活动所获得的信息是一种自然信息"}],"answer":"C","multi":false,"explanation":"<p>本题考查政治常识。<br>A项错误：实践是认识的唯一来源，但认识的途径却包括直接经验和间接经验两种：前者是指由亲身参加变革现实的实践所获得的知识；后者是指从别人或书本那里学习得来的知识。<br>B项错误：信息是意识活动借以展开的中介，人类的意识活动能够帮助我们建立起正常的信息机制，在获得、储存和处理信息这三者之间建立起完整的连接链条和意义秩序。<br>C项正确：所谓“蜻蜓低飞，天要下雨”，并不是蜻蜓向我们发出了某种特定信息，而是人类意识或思维活动在不同的事件之间建立了联系，使得一种事物或现象的出现，在某种程度上代表了另一种事物或现象的存在，究其本质，是人的意识活动把握了客观事物运动变化的相互联系及其规律的结果。<br>D项错误：自然信息是指一切自然物发出的信息，它包括来自无机界和生物界的信息，如：我们观察到的宇宙间星球的运动变化；地球上的各种自然现象；我们欣赏的风景等。社会信息是指反映人类社会运动状态和方式的信息，其来源有两大方面：一是来源于人们对自然信息的观察研究；二是来源于人们构成社会时，社会系统联系沟通的需要，以及反映和交流人们的思想感情及意识形态的需要。人类观察动物活动所获得的信息来源于人们对自然信息的观察研究，属于社会信息。<br>故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"常识判断"},"idx":9,"pid":"p4999a05dc1"},{"qid":"17900959","no":7,"type":"科技常识","module":"常识判断","stem":"<p>古往今来，人类逐水而居，文明伴随而生，人类生产生活同湿地有着密切联系。下列关于湿地的说法不正确的是：</p>","options":[{"k":"A","t":"能吸收二氧化碳气体"},{"k":"B","t":"是哺乳动物种群的栖息地"},{"k":"C","t":"会排放出甲烷、氨气"},{"k":"D","t":"具有不可替代的综合功能"}],"answer":"C","multi":false,"explanation":"<p>本题考查地理国情。<br>湿地被称为地球的“肾”，可分为自然和人工两大类。自然湿地包括沼泽地、泥炭地、湖泊、河流、海滩和盐沼等，人工湿地主要有水稻田、水库、池塘等。<br>A项正确：湿地丰富的水分条件适宜植物生长，大部分湿地都有茂盛的植物，它们可以大量吸收空气中的二氧化碳。<br>B项正确：湿地为动物提供了丰富的食物来源 ，是哺乳动物、两栖动物、鸟类等的重要栖息地，也是鸟类长途迁徙中的理想落脚地。<br>C项错误：由于湿地水体的厌氧环境，且拥有大量微生物，被固定的碳在湿地环境中会通过呼吸作用或微生物的分解作用再次释放到大气中，碳释放以二氧化碳和甲烷为主。（氨气主要来自于化肥施用和家畜蓄养等农业活动，同时也有少量来自交通运输和工业等排放。）<br>D项正确：湿地不仅为人类的生产、生活提供多种资源，而且具有巨大的环境功能和效益，在抵御洪水、调节径流、蓄洪防旱、控制污染、调节气候、控制土壤侵蚀、促淤造陆、美化环境等方面有其他系统不可替代的综合功能。<br>本题为选非题，故正确答案为C。<br>【备注】本题存在瑕疵。C项中，湿地特别是使用氮肥的人工湿地，会释放一定的氨气。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"常识判断"},"idx":10,"pid":"p4999a05dc1"},{"qid":"17900794","no":8,"type":"人文常识","module":"常识判断","stem":"<p>我国正在开展完整社区建设的试点工作，探索社区服务可复制、可推广的经验。关于我国完整社区建设的要求，下列说法不正确的是：</p>","options":[{"k":"A","t":"要保持现有城市空间结构"},{"k":"B","t":"要合理确定社区人口规模"},{"k":"C","t":"要使居民有较强的认同感"},{"k":"D","t":"要有完备的各类公共设施"}],"answer":"A","multi":false,"explanation":"<p>本题考查政治常识。<br>2021年12月17日，住房和城乡建设部办公厅发出关于印发《完整居住社区建设指南》的通知。<br>A项错误，《完整居住社区建设指南》在“1.2完整居住社区的内涵”中的“3.完整居住社区是城市结构的基本单元”部分指出：“城市是一个有机生命体，由居住社区、城市组团等交织而成。但传统规划机械地将城市分割成了功能单一、相互分离的居住社区、工业区等，造成了不紧凑、不舒适、不宜居等诸多‘城市病’问题。建设完整居住社区，就是通过构建规模适宜、功能完善的基本细胞，优化调整城市结构、完善城市功能、激发城市活力，从根本上解决‘城市病’问题，推动城市转型发展。”<br>B项正确，《完整居住社区建设指南》在“2.1完整居住社区有关部署要求”中的“2.2完整居住社区的规模”部分指出：“各地应根据儿童、老年人等社区居民的步行能力、基本服务设施的服务能力以及社区综合管理能力等，合理确定完整居住社区规模。”<br>C项正确，《完整居住社区建设指南》在“1.1完整居住社区的概念”部分指出：“完整居住社区是指在居民适宜步行范围内有完善的基本公共服务设施、健全的便民商业服务设施、完备的市政配套基础设施、充足的公共活动空间、全覆盖的物业管理和健全的社区管理机制，且居民归属感、认同感较强的居住社区。”<br>D项正确，《完整居住社区建设指南》在“2.1完整居住社区有关部署要求”中的“2.3完整居住社区的建设要求”部分指出：“完整居住社区建设目标为基本公共服务设施完善、便民商业服务设施健全、市政配套基础设施完备、公共活动空间充足、物业管理全覆盖，以及社区管理机制健全。”<br>本题为选非题，故正确答案为A。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"常识判断"},"idx":11,"pid":"p4999a05dc1"},{"qid":"17900793","no":9,"type":"人文常识","module":"常识判断","stem":"<p>为顺应全面推进乡村振兴的新要求，我国充分挖掘和不断拓展农业的食品保障、生态涵养、休闲体验、文化传承等多种功能。关于农业的多种功能，下列说法不正确的是：</p>","options":[{"k":"A","t":"农业的多种功能最终来源于土地的多重效用"},{"k":"B","t":"农业的多种功能随着地域的不同而产生差异"},{"k":"C","t":"拓展农业多种功能的重点是发展乡村休闲旅游业"},{"k":"D","t":"拓展农业多种功能要坚持立足特色、政府主导原则"}],"answer":"D","multi":false,"explanation":"<p>本题考查政治常识。<br>A项正确：农业多功能性是指农业具有经济、生态、社会和文化等多方面的功能，它最终来源于土地的多效用性，并由土地资源边际效用所决定的土地资源价值量来衡量。<br>B项正确：农业的多功能性还体现为区域间的差异性。由于农业赖以生存和发展的基础是自然资源（如土地、光、热、水、地形、地貌、生物等），而这些资源又客观存在地域上的差异性。因此，农业的多功能性也必然随着地域的不同而产生差异，导致各功能的强弱差别等。<br>C项正确：《农业农村部关于拓展农业多种功能 促进乡村产业高质量发展的指导意见》在“一、总体要求”中的“（二）基本原则”部分提出：“绿色引领、功能拓展。践行‘绿水青山就是金山银山’理念，以乡村休闲旅游业为重点拓展农业多种功能，培育生态环保产业，开发可再生能源，做到保护与开发并重、传统与现代融合，推动乡村农文旅一体化发展。”<br>D项错误：《农业农村部关于拓展农业多种功能 促进乡村产业高质量发展的指导意见》在“一、总体要求”中的“（二）基本原则”部分提出：“立足特色、市场导向。立足乡村特色资源，面向市场需求，挖掘特色产品，以特色产业培育优质企业，以优质企业带动产业提升，更好发挥政府政策配套和公共服务作用，推动乡村特色资源加快转化增值。”<br>本题为选非题，故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"常识判断"},"idx":12,"pid":"p4999a05dc1"},{"qid":"17900801","no":10,"type":"人文常识","module":"常识判断","stem":"<p>我国要因地制宜推广先进性与实用性相结合的设施农业类型，加快建设适合国情农情的现代设施农业。下列不属于建设现代设施农业的措施的是：</p>","options":[{"k":"A","t":"加快传统优势产区设施改造提升"},{"k":"B","t":"全面布局全产业链发展现代设施农业"},{"k":"C","t":"引导潜力区实施非耕地设施农业开发"},{"k":"D","t":"强化大中城市现代化都市设施农业建设"}],"answer":"B","multi":false,"explanation":"<p>本题考查政治常识。<br>《全国现代设施农业建设规划（2023—2030年）》在“三、重点任务”部分指出：“立足种植、畜牧、渔业等行业特点，因地制宜探索推广先进性与实用性相结合的设施农业类型，加快走适合我国国情农情的现代设施农业发展之路。”其中重点任务主要有加快传统优势产区设施改造提升、引导潜力区实施非耕地设施农业开发、强化大中城市现代化都市设施农业建设、建设提升现代设施育苗（秧）中心等，不包括“全面布局全产业链发展现代设施农业”。<br>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"常识判断"},"idx":13,"pid":"p4999a05dc1"},{"qid":"17900798","no":11,"type":"人文常识","module":"常识判断","stem":"<p>我国统筹划定了城镇以及各类开发区的开发边界，作为调整经济结构、规划产业发展、推进城镇化不可逾越的红线。下列情形符合城镇开发边界要求的是：</p>","options":[{"k":"A","t":"某城镇不得擅自突破城镇开发边界的扩展倍数"},{"k":"B","t":"某区在城镇开发边界外建设了数字产业园"},{"k":"C","t":"某市缩减风景名胜区范围以扩大城镇用地"},{"k":"D","t":"某县大力推动城镇地上地下空间复合利用"}],"answer":"A","multi":false,"explanation":"<p>本题考查政治常识。<br>A项正确：《自然资源部关于做好城镇开发边界管理的通知（试行）》指出：“一、坚决维护‘三区三线’划定成果的严肃性和权威性······各类城镇建设所需要的用地（包括能源化工基地等产业园区、围填海历史遗留问题区域的城镇建设或产业类项目等）均需纳入全省（区、市）规划城镇建设用地规模和城镇开发边界扩展倍数统筹核算。不得擅自突破城镇建设用地规模和城镇开发边界扩展倍数，严禁违反法律和规划开展用地用海审批······”因此，“某城镇不得擅自突破城镇开发边界的扩展倍数”符合要求。<br>B项错误：《自然资源部关于做好城镇开发边界管理的通知（试行）》指出：“三、统筹做好规划城镇建设用地安排。引导城镇建设用地向城镇开发边界内集中，促进城镇集约集聚建设，提高土地节约集约利用水平。城镇开发边界外不得进行城镇集中建设，不得规划建设各类开发区和产业园区，不得规划城镇居住用地······”因此，“某区在城镇开发边界外建设了数字产业园”做法错误。<br>C项错误：《自然资源部关于做好城镇开发边界管理的通知（试行）》指出：“三、统筹做好规划城镇建设用地安排。引导城镇建设用地向城镇开发边界内集中······在落实最严格的耕地保护、节约用地和生态环境保护制度的前提下，结合城乡融合、区域一体化发展和旅游开发、边境地区建设等合理需要，在城镇开发边界外可规划布局有特定选址要求的零星城镇建设用地，并依据国土空间规划，按照‘三区三线’管控和城镇建设用地用途管制要求，纳入国土空间规划‘一张图’严格实施监督······”因此，“某市缩减风景名胜区范围以扩大城镇用地”并没有提及需要，说法片面。<br>D项错误：《自然资源部关于做好城镇开发边界管理的通知（试行）》指出：“二、推动城镇开发边界划定成果精准落地实施。各地要结合市县国土空间规划编制审批实施，进一步深化城镇开发边界内规划用地安排，细化功能分区和用地布局，统筹存量用地和增量用地、地上空间和地下空间，合理安排城镇建设用地规模、结构、布局和时序，使城镇开发边界划定成果精准落地实施······”因此，统筹地上空间和地下空间要结合市县国土空间规划编制审批实施，“某县大力推动城镇地上地下空间复合利用”说法过于绝对。<br>故正确答案为A。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"常识判断"},"idx":14,"pid":"p4999a05dc1"},{"qid":"17900776","no":1,"type":"片段阅读","module":"言语理解与表达","stem":"<p>文中提及的候鸟迁徙的原因不包括：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"遗传基因的作用"},{"k":"B","t":"寻找食物的本能"},{"k":"C","t":"繁衍后代的要求"},{"k":"D","t":"学习技能的需要"}],"answer":"D","multi":false,"explanation":"<p>A项：根据第三段“虽无父母教，它们却知道要去哪里······总之，这是刻在它们基因里的本能”可知，选项表述正确，排除。<br>B项：根据第四段“当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源”可知，选项表述正确，排除。<br>C项：根据第四段“那为何候鸟不待在热带、不再北归呢······更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖”可知，选项表述正确，排除。<br>D项：文段并未提及鸟类迁徙是为了学习技能，“学习技能的需要”无中生有，当选。<br>本题为选非题，故正确答案为D。<br>【文段出处】《科普｜候鸟怎样记住迁徙路？》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":15,"pid":"p4999a05dc1"},{"qid":"17900774","no":2,"type":"语句表达","module":"言语理解与表达","stem":"<p>根据文意，填入文章第四段画横线部分最恰当的一项是：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"鱼虾昆虫也有自己的物候"},{"k":"B","t":"候鸟不能长期适应热带生活"},{"k":"C","t":"热带地区也可能食物不足"},{"k":"D","t":"候鸟繁殖能力受到食物影响"}],"answer":"A","multi":false,"explanation":"<p>横线出现在文段中间，需联系前后文进行分析。文段开篇引出问题，即候鸟为何要迁徙。接着分析原因，指出候鸟是为寻找鱼虾昆虫等食物而迁徙。随后再次提出问题，即为何候鸟不待在热带、不再北归，横线处解释原因。根据后文可知，候鸟会选择在一个区域食物最丰富的时间集中觅食，说明候鸟之所以离开热带是因为这个地方在其他时间食物不丰富，即鱼虾昆虫在秋冬时间较为集中，春夏时间不再集中，有属于自己的周期性规律，即鱼虾昆虫也有自己的物候，对应A项。<br>B项：“不能长期适应热带生活”文段未提及，无法衔接前后文内容，排除。<br>C项：“食物不足”没有体现食物最丰富的时间，且不如“鱼虾昆虫”表述明确，排除。<br>D项：“繁殖能力”仅对应尾句第二个原因，无法与前文衔接，排除。<br>故正确答案为A。<br>【文段出处】《科普｜候鸟怎样记住迁徙路？》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":16,"pid":"p4999a05dc1"},{"qid":"17900777","no":3,"type":"片段阅读","module":"言语理解与表达","stem":"<p>文中对勺嘴鹬和丹顶鹤做比较，这一比较重在说明：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"候鸟养育后代方式的差异"},{"k":"B","t":"候鸟适应环境能力的差异"},{"k":"C","t":"不同候鸟生存策略的差异"},{"k":"D","t":"不同候鸟迁徙路线的差异"}],"answer":"C","multi":false,"explanation":"<p>第五段出现了勺嘴鹬和丹顶鹤的对比，需重点关注。文段开头给出观点，即“为了更好地生存，不同候鸟有不同的选择”。随后分别介绍了勺嘴鹬和丹顶鹤两种鸟类的选择，即：勺嘴鹬“为保存体力、保障远距离飞行和来年的成功繁殖”，雌鸟会先迁徙，到了秋天幼鸟再进行迁徙；丹顶鹤则由成鸟带着幼鸟一同迁徙，并指出“如果没有迁徙途中父母的‘教’和自己的‘学’，小鹤就会生存困难”。故文段意在通过勺嘴鹬和丹顶鹤在迁徙中采取的不同策略，来论证首句观点，对应C项。<br>A、B、D三项：文段通过勺嘴鹬和丹顶鹤的对比来论述观点，即阐述候鸟如何更好的“生存”，A项“养育后代方式”、B项“适应环境能力”及D项“候鸟迁徙路线”均为对比中的具体内容，非文段论述的重点，排除。<br>故正确答案为C。<br>【文段出处】《科普｜候鸟怎样记住迁徙路？》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":17,"pid":"p4999a05dc1"},{"qid":"17900783","no":4,"type":"片段阅读","module":"言语理解与表达","stem":"<p>下列关于候鸟“迁徙机制”的说法，符合文意的是：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"候鸟喜欢沿着海岸线迁徙"},{"k":"B","t":"有些猛禽迁徙需跨越高山"},{"k":"C","t":"陆地飞行比海上飞行省力"},{"k":"D","t":"候鸟迁徙后天因素影响大"}],"answer":"B","multi":false,"explanation":"<p>A项：根据第六段“值得注意的是，并不是所有候鸟都沿着海岸线飞”可知，“喜欢”无中生有，排除。<br>B项：根据第六段“老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例······会把我国从西向东、从高到低的三级阶梯间的‘台阶差’作为地标，再通过太阳位置来分辨南北，实现‘导航’飞行”可知，该项符合文意，当选。<br>C项：文中并未将“陆地飞行”和“海上飞行”哪种模式更省力进行对比，该项属于无关对比，排除。<br>D项：“后天因素影响大”无中生有，排除。<br>故正确答案为B。<br>【文段出处】《科普｜候鸟怎样记住迁徙路？》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":18,"pid":"p4999a05dc1"},{"qid":"17900787","no":5,"type":"片段阅读","module":"言语理解与表达","stem":"<p>根据文意，候鸟迁徙时“导航”可依据的因素不包括：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"不同地域的气温变化"},{"k":"B","t":"地形地貌的变化"},{"k":"C","t":"天体升落位置的变化"},{"k":"D","t":"磁场感应的变化"}],"answer":"A","multi":false,"explanation":"<p>A项：“不同地域的气温变化”文章并未提及，无中生有，当选；<br>B项：根据第六段“凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的‘台阶差’作为地标······实现‘导航’飞行”可知，该项属于候鸟迁徙时“导航”可依据的因素，排除；<br>C项：根据第七段“还有的鸟类懂得观测星星的东升西落来定位”可知，该项属于候鸟迁徙时“导航”可依据的因素，排除；<br>D项：根据第七段“科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向”可知，该项属于候鸟迁徙时“导航”可依据的因素，排除。<br>本题为选非题，故正确答案为A。<br>【文段出处】《科普｜候鸟怎样记住迁徙路？》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":19,"pid":"p4999a05dc1"},{"qid":"5919286","no":6,"type":"片段阅读","module":"言语理解与表达","stem":"<p>改革开放以来，中国经济发展取得了举世瞩目的成就，但在加速工业化和城镇化过程中消耗了大量能源、水、土地、矿产等资源。“高投入、高消耗、低产出”的粗放发展方式未得到彻底扭转，高质量发展面临的资源约束长期偏紧。党的十八大以来，我国部署实施全面节约战略，大幅降低能源、水、土地利用强度。大力发展循环经济，推动资源节约集约高效利用，取得积极成效。进入新发展阶段，实现高质量发展、推动产业转型升级、更好满足美好生活需要，都对资源节约和高效利用提出了更高要求。<br>这段文字意在强调：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"高质量发展以资源大量消耗作为代价"},{"k":"B","t":"我国资源消耗总量曾经长期居高不下"},{"k":"C","t":"经济发展与资源的开发利用息息相关"},{"k":"D","t":"新发展阶段需科学配置高效利用资源"}],"answer":"D","multi":false,"explanation":"<p>文段首先指出改革开放以来中国经济发展取得的成就，接着通过转折词“但”指出在发展过程中存在资源消耗过大、发展方式粗放以及资源约束长期偏紧等问题，接着指出党的十八大以来我国通过一系列做法在资源节约方面取得了积极成效，进入了新发展阶段，最后尾句通过“提出了更高要求”提出对策，强调新发展阶段需要更好地节约及高效利用资源，对应D项。<br>A、B两项，“以资源大量消耗作为代价”和“资源消耗总量曾经长期居高不下”均对应文段提出问题部分的内容，非重点，排除；<br>C项，“息息相关”偏离文段中心，文段重点强调新发展阶段提出的更高要求，并非强调关联性，排除。<br>故正确答案为D。<br>【文段出处】人民日报《科学配置促进资源节约和高效利用（新论）》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":20,"pid":"p4999a05dc1"},{"qid":"17900782","no":7,"type":"片段阅读","module":"言语理解与表达","stem":"<p>对旅游城市而言，游客的口碑就是发展的生命线。优化旅游环境，提升服务质量，让每一位游客安心旅游、放心消费，是打造高水平旅游业的关键。把精细化治理的“麻烦”留给自己，把畅快出游的方便留给游客，定能不断增强旅游吸引力、产业竞争力，更好谱写旅游高质量发展新篇章。<br>这段文字意在说明：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"旅游城市的生命力在于不断地优化环境"},{"k":"B","t":"旅游城市需以精细化治理提升服务质量"},{"k":"C","t":"好的游客口碑对旅游城市发展至关重要"},{"k":"D","t":"游客的感受是影响旅游发展的重要因素"}],"answer":"B","multi":false,"explanation":"<p>文段开篇引出“旅游城市”的话题，并指出游客的口碑的重要性，接着提出对策，即优化旅游环境，提升服务质量是关键，最后通过精细化治理对前文对策进行总结，并进行解释说明。故文段重在强调旅游城市需进行精细化治理，对应B项。<br>A项：根据“优化旅游环境，提升服务质量”可知，“优化环境”仅对应一个方面，表述片面，排除；<br>C项：“好的游客口碑”对应文段首句，属于引出话题的部分，非重点，排除；<br>D项：文段强调的核心话题是“旅游城市”，而非“旅游”，偏离文段核心话题，排除。<br>故正确答案为B。<br>【文段出处】《以精细化治理塑造旅游城市品牌》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":21,"pid":"p4999a05dc1"},{"qid":"17900771","no":8,"type":"片段阅读","module":"言语理解与表达","stem":"<p>当前，我国大田机械化水平约70%，农机数字化率约10%，畜牧业机械化水平约40%，而渔业的机械化水平只有30%左右。我国基本处在农业机械化阶段向数字化阶段过渡期，也有部分行业还在大力发展机械化阶段，这些现实条件决定了一定时间内发展智慧农业需要在少数地区、少数行业、少数企业开展试验示范。这样的试验可以率先选择在生产规模大、机械化数字化水平高、种植和养殖效益高、资金实力和运营能力强的企业进行。<br>这段文字重在说明：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"我国农业机械化水平还有一定提升空间"},{"k":"B","t":"我国农业数字化的发展尚处于初级阶段"},{"k":"C","t":"智慧农业应根据实际先行开展试验示范"},{"k":"D","t":"智慧农业目前还不具备全面推广的条件"}],"answer":"C","multi":false,"explanation":"<p>文段开篇通过一系列的数据介绍当前我国农业机械化、数字化发展现状，随后通过“需要”提出对策，指出我国农业现实条件决定了发展智慧农业需要在少数地区、少数行业等开展试验示范，尾句对智慧农业试验如何操作进行补充说明。故文段重点强调发展智慧农业需要开展试验示范，对应C项。<br>A、B两项：A项“农业机械化”、B项“农业数字化”对应文段开篇引出话题部分，非重点，且偏离文段核心话题“智慧农业”，排除。<br>D项：“还不具备全面推广的条件”为问题表述，非重点，文段重点为对策，强调应先开展试验示范，排除。<br>故正确答案为C。<br>【文段出处】《兼顾高效、低成本和绿色可持续》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":22,"pid":"p4999a05dc1"},{"qid":"17900767","no":9,"type":"片段阅读","module":"言语理解与表达","stem":"<p>杜鹃红山茶分布范围狭窄，野生种群数量仅千余株，种群结构呈衰退型，被国际自然保护联盟评为极危种。濒危的原因有生态愈加恶劣和人为破坏等外部原因，也有杜鹃红山茶自身的原因。杜鹃红山茶是异花传粉植物，一朵花的花粉落到另一朵花的柱头上才有机会结果。开花多时，柱头可授性与花粉活力均最低；开花少时，柱头可授性与花粉活力较强，有效传粉昆虫访花频率较低，从而导致花多果少，种子活力差，自身难以繁殖。<br>这段文字意在强调：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"生态恶劣是杜鹃红山茶濒危的主要原因"},{"k":"B","t":"杜鹃红山茶的繁殖机制与常见植物不同"},{"k":"C","t":"内因是导致杜鹃红山茶濒危的重要原因"},{"k":"D","t":"杜鹃红山茶目前面临濒危处境亟待解决"}],"answer":"C","multi":false,"explanation":"<p>文段开篇引出杜鹃红山茶濒危的话题，紧接着指出其濒危的原因，不仅有众所周知的外部因素，也有其自身原因。后文大篇幅围绕其自身原因展示论述，故文段重在解释内因如何导致杜鹃红山茶难以繁殖、走向濒危，对应C项。<br>A项，“生态恶劣”仅对应外部原因，非重点，排除；<br>B项，文段并未介绍其与常见植物的不同，无中生有，排除；<br>D项，“亟待解决”文段并未提及，无中生有，排除。<br>故正确答案为C。<br>【文段出处】《国家级“朋友”，你也可以拥有——杜鹃红山茶|花颜鸟语》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":23,"pid":"p4999a05dc1"},{"qid":"5919296","no":10,"type":"片段阅读","module":"言语理解与表达","stem":"<p>陶瓷是陶器和瓷器的总称。早在公元前8000年前的新石器时代，我们的祖先就发明了陶器。到了距今约2000年的东汉时期，成熟的瓷器也登上了历史舞台，进入百姓生活中。现如今，随着科学技术的迅猛发展，更多新型陶瓷以其高韧性、高抗弯强度和高耐磨性等优点被广泛用于各行各业。目前，科研人员还在研发更多超轻、耐用、耐高温、耐腐蚀的陶瓷材料，有望用于未来航天器的隔热保护。<br>下列说法与文意不符的是：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"陶器的出现比瓷器的发明要早六千年"},{"k":"B","t":"东汉时期陶器已经进入百姓生活之中"},{"k":"C","t":"新型陶瓷材料以其特殊物理性质应用广泛"},{"k":"D","t":"新型陶瓷材料未来有用于航天的发展前景"}],"answer":"A","multi":false,"explanation":"<p>A项，根据“到了距今约2000年的东汉时期，成熟的瓷器也登上了历史舞台”可知，文段仅论述了“成熟瓷器”出现的时间，而非瓷器首次出现的时间，且在文段出现的具体年份中，“公元前8000年前的新石器时代”与“距今约2000年的东汉时期”，两者间隔时间也并非“六千年”，表述错误，当选；<br>B项，根据“早在公元前8000年前的新石器时代，我们的祖先就发明了陶器。到了距今约2000年的东汉时期，成熟的瓷器也登上了历史舞台，进入百姓生活中”可知，一方面陶器早在新石器时代就被发明使用，另一方面成熟瓷器通过“也”与前文论述的陶器并列，说明陶器在东汉时期同样进入百姓生活中，表述正确，排除；<br>C项，根据“更多新型陶瓷以其高韧性、高抗弯强度和高耐磨性等优点被广泛用于各行各业”可知，表述正确，排除；<br>D项，根据“科研人员还在研发更多超轻、耐用、耐高温、耐腐蚀的陶瓷材料，有望用于未来航天器的隔热保护”可知，表述正确，排除。<br>本题为选非题，故正确答案为A。<br>【文段出处】知网《陶瓷家族新成员》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":24,"pid":"p4999a05dc1"},{"qid":"17900935","no":11,"type":"片段阅读","module":"言语理解与表达","stem":"<p>电力作为一种特殊商品，供求实时平衡尤其重要。近年来，我国以风电、光伏发电为代表的新能源发展成效显著，装机规模连续多年稳居全球首位。发展新能源综合效益巨大，但要立得住、立得稳、立得好，需要电网输配、电源、储能等协同支撑。新能源供给消纳体系有助于提升能源安全保障能力，推动绿色低碳发展。只有供给和消纳双管齐下、整体谋划，才能切实推动新能源大规模、高比例、市场化、高质量发展。<br>这段文字意在强调：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"我国新能源的装机规模位居世界首位"},{"k":"B","t":"我国应完善新能源供给消纳体系建设"},{"k":"C","t":"新能源高质量发展事关国家能源安全"},{"k":"D","t":"新能源电力需要具有实时平衡的特性"}],"answer":"B","multi":false,"explanation":"<p>文段开篇引出“电力”的话题，指出供求实时平衡对电力的重要性，接着介绍我国新能源发展成效显著、装机规模大的背景，之后通过转折词“但”指出发展新能源需要多方面协同支撑，随后指出新能源供给消纳体系能保障能源安全，推动绿色低碳发展，尾句通过“只有······才······”强调推动新能源向好发展离不开供给和消纳的支持。故文段核心话题为“新能源供给消纳体系”，对应B项。<br>A项：缺少文段主题词“新能源供给消纳体系”，并且“装机规模位居世界首位”为文段转折前的内容，非重点，排除。<br>C、D两项：均缺少文段主题词“新能源供给消纳体系”，排除。<br>故正确答案为B。<br>【文段出处】《让新能源发得出供得上用得好（经济新方位·巩固经济回升向好趋势）》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":25,"pid":"p4999a05dc1"},{"qid":"5919295","no":12,"type":"片段阅读","module":"言语理解与表达","stem":"<p>底线思维是一种富有哲学智慧的思维能力，是对中华优秀传统文化中相关思想观念的继承和发展。比如，孔子讲的“人无远虑，必有近忧”，孟子讲的“生于忧患而死于安乐”，都强调要增强忧患意识、防范化解风险，体现了底线思维。底线思维还是对唯物辩证法的坚持和运用。现实生活中矛盾无处不在、无时不有。要从矛盾的两个方面一分为二地看事物，不能只看有利的一面，忽视不利的一面，而是要通盘考虑各种因素，居安思危、未雨绸缪。<br>下列关于“底线思维”的说法不符合文意的是：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"传承和发展了中华优秀传统文化"},{"k":"B","t":"集中了儒家学说思想文化的精髓"},{"k":"C","t":"体现了辩证唯物主义的思维方法"},{"k":"D","t":"具有忧患意识且凝聚了哲学智慧"}],"answer":"B","multi":false,"explanation":"<p>A项，根据“底线思维是一种富有哲学智慧的思维能力，是对中华优秀传统文化中相关思想观念的继承和发展”可知，表述正确，排除；<br>B项，根据“孔子讲的‘人无远虑，必有近忧’，孟子讲的‘生于忧患而死于安乐’，都强调要增强忧患意识、防范化解风险，体现了底线思维”可知，文段表达的是孔孟思想体现了底线思维，而非底线思维集中了儒家学说思想文化的精髓，表述错误，当选；<br>C项，根据“底线思维还是对唯物辩证法的坚持和运用”可知，表述正确，排除；<br>D项，根据“底线思维是一种富有哲学智慧的思维能力”及“孔子讲的‘人无远虑，必有近忧’，孟子讲的‘生于忧患而死于安乐’，都强调要增强忧患意识、防范化解风险，体现了底线思维”可知，表述正确，排除。<br>本题为选非题，故正确答案为B。<br>【文段出处】人民日报《坚持底线思维（思想纵横）》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":26,"pid":"p4999a05dc1"},{"qid":"17900769","no":13,"type":"片段阅读","module":"言语理解与表达","stem":"<p>要通过标准化把分散的农户组织起来，进行无公害、绿色、有机生产，构建起标准化、常态化的供应链体系，这是农货变网货的基础。当务之急是要通过市场倒逼，实现产业链的标准化、数字化变革，引导龙头企业、合作社等新型经营主体，带动农户形成生产标准统一、利益分配共享的共同体，实现农产品从种到销全程标准化，拧紧“安全阀”。要借助数字技术，尽快实现农产品从地头到餐桌质量安全全程可追溯，让消费者放心买单的同时增加销量、提高附加值。<br>这段文字意在强调：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"形成农户利益分配共享共同体至关重要"},{"k":"B","t":"新型农业经营主体应该由市场机制催生"},{"k":"C","t":"应利用数字化技术加快农货变网货进程"},{"k":"D","t":"构建标准化产业链确保农产品质量安全"}],"answer":"D","multi":false,"explanation":"<p>文段开篇提出，要将分散的农户组织起来进行科学生产，构建供应链体系，这是农货变网货的基础。随后提出要通过市场倒逼实现变革，引导新型经营主体带动农户形成共同体，实现从种到销全程标准化，保障农产品质量安全。尾句提出要借助数字技术实现农产品安全全程可追溯，增加农产品销量、提高附加值。故文段从供应链体系标准化、从种到销全程标准化、农产品安全溯源三方面，提出要通过构建标准化产业链保障农产品质量安全，对应D项。<br>A项：“形成农户利益分配共享共同体”仅对应一方面的内容，表述片面，排除。<br>B、C两项：B项“新型农业经营主体应该由市场机制催生”和C项“利用数字化技术加快农货变网货进程”文段均未提及，无中生有，排除。<br>故正确答案为D。<br>【文段出处】《直播带货，如何从“一时火”变成“一直火”（话说新农村）》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":27,"pid":"p4999a05dc1"},{"qid":"17900912","no":14,"type":"片段阅读","module":"言语理解与表达","stem":"<p>近年来，“个人碳账户”逐渐走进人们的日常生活。打开手机应用软件，骑行、购买节能产品、不选一次性餐具等都可折算成“减排量”，在个人账户里一目了然。登录“碳普惠”“碳积分”“碳宝包”等小程序，低碳行动就可转换为减碳积分，积分还能进行绿色消费。这些包含个人碳排放场景应用、数据采集核算、积分跨界兑换等功能在内的碳减排支持体系，就属于“个人碳账户”。它简便又直观，能够帮助普通人算清“碳账”。<br>根据文意，建立“个人碳账户”的主要意义在于：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"引导人们在日常生活中采取低碳行动"},{"k":"B","t":"通过个人“碳账”管理推动绿色消费"},{"k":"C","t":"可利用信息技术完善碳减排系统建设"},{"k":"D","t":"有助于更好地采集个人碳排放数据"}],"answer":"B","multi":false,"explanation":"<p>文段开篇引出“个人碳账户”的话题，并介绍低碳行为的“减排量”在“个人碳账户”可以一目了然，接着介绍在一些小程序中低碳行动能带来的好处，后文指出这些碳减排支持体系就属于“个人碳账户”，最后通过指代词“它”进行总结，强调“个人碳账户”简便直观，能够帮助人们算清“碳账”。故文段为“分—总”结构，重点强调“个人碳账户”简便直观，能帮助人们算清绿色消费相关的“碳账”，更好地推动绿色消费，对应B项。<br>A项：文段重点论述“碳账”对于“消费”的作用，“采取低碳行动”不及B项“绿色消费”与文段对应准确，排除。<br>C项：“完善碳减排系统建设”偏离文段重点，文段重点论述帮助人们算清“碳账”，推动绿色消费，排除。<br>D项：“采集个人碳排放数据”仅对应“数据采集核算”，表述片面，文段还介绍了“积分跨界兑换”等，排除。<br>故正确答案为B。<br>【文段出处】《“个人碳账户”还应更多些》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":28,"pid":"p4999a05dc1"},{"qid":"5919289","no":15,"type":"片段阅读","module":"言语理解与表达","stem":"<p>一般来说，高速公路扩容改造方案主要有两种：一种是改扩建，即通过对既有高速公路进行拼宽或分离增建车道，提高通行能力；另一种是在既有高速公路通道内另建新线。在无特殊条件制约情况下，扩容改造项目应优先利用既有高速公路改扩建。因为既有高速公路一般占据了通道内较为理想的线位，周边相关路网及配套产业设施已基本形成，另建新线，往往难以取代既有公路承担的交通功能，若选择新线，工程、征拆、投资等规模都较大。<br>关于优先利用既有高速公路改扩建的理由，文段未涉及的是：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"工程造价征拆投资等投入相对较低"},{"k":"B","t":"既有高速公路线的线位已充分论证"},{"k":"C","t":"可以大大减少设计周期以缩短工期"},{"k":"D","t":"与现有路网和经济带的适应性最佳"}],"answer":"C","multi":false,"explanation":"<p>A项，根据“若选择新线，工程、征拆、投资等规模都较大”可知，文段提及了利用既有高速公路改扩建的“工程造价征拆投资等投入相对较低”，表述正确，排除；<br>B项，根据“既有高速公路一般占据了通道内较为理想的线位”“另建新线，往往难以取代既有公路承担的交通功能”可知，既有高速公路线位通常较为理想，建新线难以取代其交通功能，故“既有高速公路线的线位已充分论证”表述正确，排除；<br>C项，文段未提及“设计周期”“工期”相关的话题，无中生有，当选；<br>D项，根据“既有高速公路······周边相关路网及配套产业设施已基本形成，另建新线，往往难以取代既有公路承担的交通功能”可知，另建新线往往无法与现有的相关路网和配套产业设施相匹配，故“与现有路网和经济带的适应性最佳”表述正确，排除。<br>本题为选非题，故正确答案为C。<br>【文段出处】人民日报《扩容改造，让高速公路筋骨更强健》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":29,"pid":"p4999a05dc1"},{"qid":"17900722","no":16,"type":"片段阅读","module":"言语理解与表达","stem":"<p>近年来，我国数据产量每年保持约30%的增速，厘清各主体的数据权利与义务，有利于优化数据资产管理，促进数据有序流通。从安全角度看，数据分类分级是数据安全的基础。对于关系国家安全或重大公共利益的公共数据，要明确其公有性质，所有权归国家，根据数据级别采取不同的保护措施。对于承载个人信息的数据，应划定隐私与一般数据的边界，在保护隐私的同时通过脱敏、加密等技术手段促进一般数据流通使用。<br>这段文字意在强调：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"我国数据生产增长迅猛"},{"k":"B","t":"需创新研发数据使用流通技术手段"},{"k":"C","t":"数据保护事关国家安全"},{"k":"D","t":"应分类分级推进数据确权授权使用"}],"answer":"D","multi":false,"explanation":"<p>文段开篇介绍我国数据产量每年递增的背景，并指出厘清各主体的数据权利与义务的意义。随后从安全角度指出数据分类分级是数据安全的基础，并从公共数据和个人信息数据两方面具体论述数据分级分类对数据安全的意义。故文段重点强调数据分级分类对数据安全的重要性，对应D项。<br>A项：“数据生产增长迅猛”对应文段开头背景引入部分，非重点，排除；<br>B项：“创新研发数据使用流通技术手段”文段并未提及，无中生有，排除；<br>C项：数据保护对国家安全的重要性对应后文解释说明部分，非重点，且后文除了国家安全还提到了重大公共利益、个人信息数据，表述片面，排除。<br>故正确答案为D。<br>【文段出处】《加快建立完善数据产权制度（经济时评）》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":30,"pid":"p4999a05dc1"},{"qid":"17900922","no":17,"type":"片段阅读","module":"言语理解与表达","stem":"<p>几千年来，中医药生生不息。“传承不泥古，创新不离宗”，是中医药长盛不衰的秘诀。所谓“传承不泥古”，就是要领悟和把握中医药的精髓，不拘泥于经典，不死记方药，而是举一反三、灵活应用，不断超越古人的局限。所谓“创新不离宗”，就是在守住中医根本的基础上，与时俱进，大胆创新，正确处理变与不变的关系，因时制宜、因地制宜、因人制宜，使古老的中医药焕发新光彩。<br>这段文字主要说明的是：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"中医药应如何承前启后代代相传"},{"k":"B","t":"中医药发展需要超越古方的局限"},{"k":"C","t":"中医药传承必须坚守中医的根本"},{"k":"D","t":"中医药创新需要处理好哪些问题"}],"answer":"A","multi":false,"explanation":"<p>文段开篇提出观点，即“传承不泥古，创新不离宗”是中医药长盛不衰的秘诀，随后通过并列的形式分别介绍“传承不泥古”和“创新不离宗”的具体做法。故文段重点强调中医药如何长盛不衰、代代相传，对应A项。<br>B项：“超越古方的局限”仅对应“传承不泥古”的做法，表述片面，排除。<br>C项：“坚守中医的根本”仅对应“创新不离宗”的做法，表述片面，排除。<br>D项：文段重点强调中医药如何传承，“中医药创新”偏离文段重点，排除。<br>故正确答案为A。<br>【文段出处】《让中医代代薪火相传（无影灯）》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":31,"pid":"p4999a05dc1"},{"qid":"17900770","no":18,"type":"片段阅读","module":"言语理解与表达","stem":"<p>蝉是以维管植物组织为食的昆虫，在生态系统中发挥着重要的作用，如循环养分和增强土壤通气，还是鼹鼠和鸟类等动物的重要食物。快速的城市化、气候变化等威胁着蝉的生存。混凝土和压实的土壤使其若虫难以爬出地面。人为活动引起的栖息地破碎化和植物群落变化影响了它们的栖息、觅食、交配和呼叫能力。土壤污染使蝉容易受到真菌和细菌性疾病的影响。人类噪音干扰蝉的交配呼叫。气候变化加剧了洪水，淹没了若虫的“地下室”，威胁到它们的生存。<br>这段文字接下来最有可能讲述的是：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"人为活动与昆虫消失的关系"},{"k":"B","t":"蝉具备哪些重要的生态价值"},{"k":"C","t":"解决蝉目前生存困境的策略"},{"k":"D","t":"城市中昆虫数量减少的原因"}],"answer":"C","multi":false,"explanation":"<p>本题为接语选择题，应在通读全文的基础上，重点关注文段最后论述的核心话题。文段开篇引出“蝉”的话题，提到其具有重要生态价值，接着指出城市化和气候变化等因素威胁着蝉的生存，并通过列举一系列具体的事例进行解释说明，详细论述了蝉目前受到的生存威胁。根据话题一致原则和“提出问题+解决问题”的行文逻辑，后文应继续围绕“蝉”展开，论述如何解决蝉目前面临的困境，对应C项。<br>A、D两项：均偏离文段核心话题“蝉”，排除。<br>B项：“生态价值”前文已详细论述过，后文不会再论述，排除。<br>故正确答案为C。<br>【文段出处】《吃知了这事上了今天〈科学〉新闻》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":32,"pid":"p4999a05dc1"},{"qid":"17900924","no":19,"type":"语句表达","module":"言语理解与表达","stem":"<p>博物馆研学，要“研之有物”“学而广博”。博物馆研学不是“打卡”拍照的旅游，也不仅是提供托管服务，而是要让年轻一代明白，生而为中国人，最根本的是有中国人独特的精神世界，有百姓日用而不觉的价值观。近年来，中华文明探源工程等重大工程的研究成果，进一步证实了我国悠久的人类史和璀璨的文化史，其中也包含着中华优秀传统文化、革命文化和社会主义先进文化。这些都被缩影于文物当中。因此，博物馆研学，就是要<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>填入画横线部分最恰当的一项是：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"从文物中学习这些文化"},{"k":"B","t":"深入了解中华文明的独特性"},{"k":"C","t":"不断提高自身文化素养"},{"k":"D","t":"有的放矢地学习历史和文化"}],"answer":"A","multi":false,"explanation":"<p>横线位于文段尾句，且由横线前的“因此”可知，横线处是对前文的总结。文段开篇指出博物馆研学要“研之有物”“学而广博”，随后强调博物馆研学要让年轻一代明白生而为中国人，最根本的是有中国人独特的精神世界，接着指出近年来一系列重大工程的研究成果证实了我国的历史中包含着各种文化，之后通过“这些”总结前文，指出文化都被缩影于文物之中，故前文强调文物对文化的载体作用，对应A项。<br>B、C两项：B项“中华文明的独特性”及C项“提高自身文化素养”文段均未提及，无中生有，与前文衔接不当，且均未提及文段核心话题“文物”，偏离文段核心话题，排除。<br>D项：未提及文段核心话题“文物”，偏离文段核心话题，排除。<br>故正确答案为A。<br>【文段出处】《博物馆研学，如何研之有物、学而广博》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":33,"pid":"p4999a05dc1"},{"qid":"17900768","no":20,"type":"语句表达","module":"言语理解与表达","stem":"<p>①比如以珠峰为核心的珠穆朗玛峰国家级自然保护区内有高等植物2550种，动物509种<br>②作为世界之巅，珠峰给人的印象往往是很“高冷”的<br>③不过正因为珠峰太过高耸，喜马拉雅山脉北坡巨大的海拔落差也为各种动植物提供了良好的栖居地<br>④的确，山顶的高度已不适合任何动植物生活<br>⑤从“征服”珠峰，到了解珠峰、保护珠峰，我们一次又一次造访世界之巅的最终目的就是能更好地守护它<br>⑥是西藏生物多样性最为丰富的区域之一，值得我们倍加珍惜<br>将以上6个句子重新排列，语序正确的是：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"②③④⑥①⑤"},{"k":"B","t":"②④③①⑤⑥"},{"k":"C","t":"⑤①⑥③②④"},{"k":"D","t":"⑤②④③①⑥"}],"answer":"D","multi":false,"explanation":"<p>对比选项，确定首句。选项中首句为②句和⑤句，②句指出“珠峰”给人的印象，⑤句指出我们一次又一次造访珠峰的最终目的是更好地保护它，均可作为首句。<br>继续寻找其他线索。①句出现“比如”，随后介绍以珠峰为核心的珠穆朗玛峰国家级自然保护区内高等植物和动物的数量非常多，根据“观点+解释说明”的逻辑顺序，①句前需有对应的观点与之相连，且观点要围绕珠峰的生态环境展开。结合选项，①句前是③句、⑤句和⑥句，③句介绍珠峰为各种动植物提供了良好的栖居地，故①句是对③句的举例说明，③句放在①句之前符合逻辑，B、D两项保留。⑤句指出我们不断造访珠峰是为了保护珠峰，并未提及珠峰的生态环境，与①句内容不一致，⑤①两句相连不成立，排除C项。而⑥句是对西藏某一区域生物多样性的定性，结合①句可知，⑥句是对①句的定义，表示珠穆朗玛峰国家级自然保护区是西藏生物多样性最为丰富的区域之一，故应放在①句之后，排除A项。<br>对比B、D两项，区别在于①句后面是⑤句还是⑥句，①句介绍珠峰保护区内物种丰富，⑥句是对西藏某一区域生物多样性的定性，结合①句分析，即⑥句是对①句中珠峰物种多样性进行的定义，故①⑥两句话题一致，逻辑通顺。而⑤句相当于提出观点，即强调造访珠峰的最终目的是保护珠峰，应先引出保护珠峰的话题，再通过①⑥两句强调珠峰值得我们倍加珍惜，⑤句应在①⑥两句之前，故排除B项，D项当选。<br>故正确答案为D。<br>【文段出处】《再登珠峰！我们为什么要在地球之巅科考？》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":34,"pid":"p4999a05dc1"},{"qid":"17900928","no":21,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>“不一则不专，不专则不能。”持之以恒的专注追求，不仅是科研求索的唯一捷径，也是成就一切事业的关键基石。古往今来，多少有所建树者，正是在坚守一个人、一辈子、一件事的信念中，创造了令人<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的非凡业绩，留下了让世界惊叹的不朽<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线部分最恰当的一项是：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"刮目相看 成就"},{"k":"B","t":"另眼相待 丰碑"},{"k":"C","t":"叹为观止 华章"},{"k":"D","t":"拍案叫绝 功绩"}],"answer":"A","multi":false,"explanation":"<p>第一空，搭配“业绩”，且“创造了令人······的非凡业绩，留下了让世界······的不朽······”相同句式表并列，故横线处应体现创造了令人惊叹的业绩之意。A项“刮目相看”指用新的眼光来看待，C项“叹为观止”形容所见到的事物好到了极点，均符合文意，保留。B项“另眼相待”指用另一种眼光看待，多指看待某个人（或某种人）不同于一般，与文意不符，排除；D项“拍案叫绝”指拍着桌子叫好，形容非常赞赏，强调对某人的作品或者话语等赞赏，与“业绩”搭配不当，排除。<br>第二空，根据相同句式表并列可知，横线处需对应“业绩”，即所取得的事业成绩。A项“成就”指成绩、业绩，符合文意，当选。C项“华章”指称颂他人诗文华丽的赞美之词，文段此处指有所建树者自己所取得的事业成绩，并非称颂他人的赞美之词，与文意不符，排除。<br>故正确答案为A。<br>【文段出处】《“一辈子办成一件事”的人生价值》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":35,"pid":"p4999a05dc1"},{"qid":"5919300","no":22,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>北极和南极是地球的极巅，它们遥相呼应，各据一方。冰天雪地是极地的特色，寒冷干燥是那里的常态，那里<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，生态环境却别有洞天，企鹅在南极雪地疾走，白熊在北极冰水游泳，苍鹰在高峰之巅盘旋······神奇的世界、迷人的景象，令人<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线部分最恰当的一项是：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"与世隔绝 心旷神怡"},{"k":"B","t":"寸草不生 怦然心动"},{"k":"C","t":"人迹罕至 心驰神往"},{"k":"D","t":"冰冻三尺 赏心悦目"}],"answer":"C","multi":false,"explanation":"<p>第一空，横线前“那里”指代的是极地，根据前文“冰天雪地”“寒冷干燥”可知，横线处成语也应体现极地的特点，且根据横线后转折词“却”可知，横线前后语义相反，横线后描写极地生态环境别有洞天，各类动物在此处生存，故横线处成语应体现极地的环境不适合生物的生存。C项“人迹罕至”指人的足迹很少到达，符合文意，保留。A项“与世隔绝”指与外界社会隔断往来，置于此处程度过重，排除；B项“寸草不生”形容土地贫瘠，环境恶劣，连一点儿草都不长，与后文的“生态环境却别有洞天”相互矛盾，排除；D项“冰冻三尺”比喻事态的严重不是一天造成的，是日积月累而成的，形容长时间形成的问题，与文意无关，排除。<br>第二空，代入验证，根据前文“神奇的世界、迷人的景象”可知，横线处成语应形容极地景象带给人类的美好感受，C项“心驰神往”形容思想集中在追求和向往的事情或地方上，置于此处能够体现极地风景美丽，人们想要到达之意，当选。<br>故正确答案为C。<br>【文段出处】人民日报《极地科考 造福人类》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":36,"pid":"p4999a05dc1"},{"qid":"13628188","no":23,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>项目化学习是指从真实的问题情境出发，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>学生在一段时间内持续开展探究，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>创造性地解决问题，并最终形成项目成果的教学方式。目前，不少地区和学校已经在项目设计、实施方式、评价方法上积累了一定经验。<br>依次填入画横线部分最恰当的一项是：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"引导 尝试"},{"k":"B","t":"组织 实时"},{"k":"C","t":"激励 力求"},{"k":"D","t":"启发 同步"}],"answer":"A","multi":false,"explanation":"<p>本题可从第二空入手，根据“从真实的问题情境出发”以及“最终形成项目成果”可知，横线处词语需表达学生在探究过程中试图创造性地解决问题。A项“尝试”指试验，C项“力求”指尽最大的努力，均符合文意，保留。B项“实时”指与某事发生、发展的实际时间同步（做某事），D项“同步”泛指相互关联的事物在进行速度上协调一致，均强调时间、步调的一致，而根据前文“学生在一段时间内持续开展探究”可知，探究时间较长，探究问题与解决问题并非同时完成，与文意不符，排除。<br>第一空，根据“从真实的问题情境出发”可知，项目化学习是让学生利用真实的问题情境开展探究进而解决问题，A项“引导”指带领，或指引、诱导，置于此处意为利用真实的问题情境诱导学生开展探究，符合文意，当选。C项“激励”指激发，鼓励，着重强调用言行使振作起来，激发情感，而使受到更强的鼓励，“真实的问题情境”无法鼓励学生，与文意不符，排除。<br>故正确答案为A。<br>【文段出处】中国网教育《项目化学习让学生成为学习的主人》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":37,"pid":"p4999a05dc1"},{"qid":"5919311","no":24,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>人们很早就发现太阳并非一成不变，而是源源不断地往外喷发物质和能量，时而<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>、时而猛烈。黑子、耀斑、日冕物质抛射等太阳活动<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，所引发的太阳风暴不断搅动着日地、太阳系空间和行星周围的环境，在太空中产生各种各样短时间尺度的变化。<br>依次填入画横线部分最恰当的一项是：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"平缓 此起彼伏"},{"k":"B","t":"舒缓 瞬息万变"},{"k":"C","t":"温和 接踵而至"},{"k":"D","t":"平和 绵延不绝"}],"answer":"A","multi":false,"explanation":"<p>本题可从第二空入手。横线处搭配“太阳活动”，且根据后文“引发的太阳风暴不断搅动着太阳系空间和行星周围的环境”可知，横线处应表达太阳活动接连不断之意。A项“此起彼伏”指这里起来，那里落下，表示连续不断，与“太阳活动”搭配恰当，且与文意相符，保留。B项“瞬息万变”指在极短的时间内变化快而多，文段强调多种不同类型的太阳活动接连不断，而非变化多，与文意不符，且置于此处程度过重，排除；C项“接踵而至”指人们前脚跟着后脚，接连不断地来，形容人接连而来或事情持续发生，侧重强调事情发生得很紧凑，间隔很短，而A项“此起彼伏”强调多个事物无规律地连续出现，两项对比，A项“此起彼伏”与“黑子、耀斑、日冕物质抛射等太阳活动”的出现规律更契合，故排除C项；D项“绵延不绝”指接连不断，一直延续下去，多搭配“山川”“文化”“文明”等，与“太阳活动”搭配不当，排除。<br>第一空，代入验证。根据“时而······时而······”可知，横线处词语与“猛烈”语义相反。A项“平缓”指平稳、缓慢，与“猛烈”语义相反，符合文意，当选。<br>故正确答案为A。<br>【文段出处】《“太空天气预报”的作用（开卷知新）》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":38,"pid":"p4999a05dc1"},{"qid":"5919324","no":25,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>国防教育应面向全民，没有一个人、一个行业、一个领域可以<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，国防意识和国防素养不可能自发形成，必须<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>地推动国防教育进机关、进学校、进企业、进社区、进乡村、进军营、进网络等，实现全民国防教育“全覆盖”。<br>依次填入画横线部分最恰当的一项是：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"漠不关心 全力以赴"},{"k":"B","t":"置身事外 坚持不懈"},{"k":"C","t":"袖手旁观 持之以恒"},{"k":"D","t":"作壁上观 矢志不渝"}],"answer":"B","multi":false,"explanation":"<p>第一空，根据“面向全民”“不可能自发形成”“实现全民国防教育‘全覆盖’”可知，要让所有人、行业、领域都参与到国防教育当中，B项“置身事外”指把自己放在事情之外，毫不关心，与“没有”搭配，可以体现出“国防教育应面向全民”，保留。A项“漠不关心”指对人或事情一点儿也不关心，侧重强调不关心，与文段“面向全民”对应不当，排除；C项“袖手旁观”比喻置身事外，既不过问，也不协助别人，D项“作壁上观”比喻站在一旁看着，不动手帮助，均侧重强调“不提供帮助”，文段并无“提供帮助”之意，排除。<br>第二空，代入验证，B项“坚持不懈”指坚持到底，一点不松懈，与“不可能自发形成”“实现全民国防教育‘全覆盖’”等内容相对应，可以体现进行国防教育是一个需要持续发力、久久为功的过程，符合文意，当选。<br>故正确答案为B。<br>【文段出处】《新时代全民国防教育工作大家谈》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":39,"pid":"p4999a05dc1"},{"qid":"5919334","no":26,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>以电视屏和手机屏为终端，一些地方的数字乡村平台实现了服务和信息<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>下发到户，教育、医疗、农技等优质资源<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>到村，让村民“小事不出门、大事不出村”，提升了基层治理<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线部分最恰当的一项是：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"精准 下沉 效能"},{"k":"B","t":"及时 配置 效果"},{"k":"C","t":"全面 分发 效益"},{"k":"D","t":"分类 引入 效用"}],"answer":"A","multi":false,"explanation":"<p>第一空，根据“让村民‘小事不出门、大事不出村’”可知，横线处所填词语应体现服务和信息能够传达到户，使村民不用出门即可享受服务和信息。A项“精准”指非常准确、精确，B项“及时”指立刻、马上、不拖延，C项“全面”指完整周密或兼顾各方面的，均符合文意，保留。D项“分类”指按照种类、等级或性质分别归类，文段中信息应都通过电视屏和手机屏传播，不存在分类的情况，与文意无关，排除。<br>第二空，根据“让村民‘小事不出门、大事不出村’”可知，横线处所填词语应体现“教育、医疗、农技等优质资源”深入到村。A项“下沉”指深入、向下，B项“配置”指配备布置、安排，C项“分发”指逐个发给，均符合文意，保留。<br>第三空，根据“让村民‘小事不出门、大事不出村’”可知，基层治理让村民办事更加方便快捷，故横线处所填词语应体现基层治理效率得到提升。A项“效能”强调效用、作用，符合文意，且“提升基层治理效能”为常见搭配，当选。B项“效果”强调产生的结果（多指好的），C项“效益”指效果与利益，侧重强调收益，均与文段强调的效率提升不符，排除。<br>故正确答案为A。<br>【文段出处】《“数字乡村”推动农业农村现代化（人民时评）》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":40,"pid":"p4999a05dc1"},{"qid":"13628191","no":27,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>“地铁会合点”的选择虽然并非大手笔，但蕴含着城市善治的大道理。城市让生活更美好，这不仅体现在高楼大厦、车水马龙的繁华图景里，也蕴含在日常生活的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>中。满足老百姓更高品质的生活需求，不仅需要用科技手段实现<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，也需要用“绣花功夫”提升公共场域管理服务的精细化、<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>水平。<br>依次填入画横线处最恰当的一项是：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"细枝末节 智能化 人性化"},{"k":"B","t":"日积月累 便捷化 差异化"},{"k":"C","t":"熙熙攘攘 数字化 多元化"},{"k":"D","t":"井然有序 一体化 制度化"}],"answer":"A","multi":false,"explanation":"<p>第一空，根据“‘地铁会合点’的选择并非大手笔”“不仅体现在高楼大厦、车水马龙的繁华图景里，也蕴含在日常生活的”可知，横线处所填成语与“繁华图景”相对，应表达“城市让生活更美好”在日常生活的点滴细节中也有体现。A项“细枝末节”比喻事情或问题的细小而无关紧要的部分，符合文意，保留。B项“日积月累”指长时间地积累，D项“井然有序”指整整齐齐，次序分明，条理清楚，均无法与“繁华图景”对应，排除；C项“熙熙攘攘”形容人来人往，非常热闹，与前文“车水马龙的繁华图景”语义重复，排除。<br>第二空，代入验证，根据“用科技手段”可知，横线处所填词语应体现科技感。A项“智能化”指事物在计算机网络、大数据、物联网和人工智能等技术的支持下，所具有的能满足人的各种需求的属性，符合文意，保留。<br>第三空，代入验证，根据顿号可知，横线处所填词语与“精细化”对应，且根据“绣花功夫”可知，意在表达要优化提升管理服务的细节。A项“人性化”指设法使符合人性发展的要求，符合文意，当选。<br>故正确答案为A。<br>【文段出处】光明网－时评频道《【光明观澜】“地铁会合点”细节变化蕴含城市治理观念升级》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":41,"pid":"p4999a05dc1"},{"qid":"5919346","no":28,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>9月23日，中国农民丰收节如期而至，亿万农民成为<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的主角。他们站上舞台，唱起丰收欢歌、舞出丰收韵律；农民篮球邀请赛上，他们用篮球追逐热爱，彰显<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>活力和幸福能量；在非遗、传统民俗技艺展演上，他们秀出“绝活”；“农”味十足的趣味体育比赛里，他们<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>、一较高下。他们尽情享受、尽情释放，展示着新时代新农民昂扬向上的精神风貌。<br>依次填入画横线部分最恰当的一项是：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"理所当然 无限 争先恐后"},{"k":"B","t":"当仁不让 澎湃 你追我赶"},{"k":"C","t":"顺理成章 蓬勃 你争我夺"},{"k":"D","t":"毋庸置疑 旺盛 不甘示弱"}],"answer":"B","multi":false,"explanation":"<p>本题可从第三空入手，根据“‘农’味十足的趣味体育比赛里”及“他们尽情享受、尽情释放”可知，横线处应体现丰收节体育比赛热闹非凡、有趣味之意。B项“你追我赶”形容竞赛激烈，大家都不甘落后，常用于比赛的语境，符合文意，保留。A项“争先恐后”指争着向前，唯恐落后，C项“你争我夺”指相互争夺，D项“不甘示弱”指不甘心显得比别人差，形容好强，要追上或胜过对方，虽均可体现比赛的激烈，但置于文段竞争性过强，不如B项与文段对应更为准确，排除。<br>第一空，代入验证。根据“中国农民丰收节如期而至”可知，横线处应体现亿万农民是丰收节的主角之意。B项“当仁不让”表示应做之事，就应积极主动去做，不能推托，符合文意，且“成为当仁不让的主角”用法正确，保留。<br>第二空，代入验证。B项“澎湃”形容声势浩大，气势雄伟，置于此处可体现农民在篮球邀请赛上活力十足之意，符合文意，当选。<br>故正确答案为B。<br>【文段出处】光明网《锦绣沃野 风景正好》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":42,"pid":"p4999a05dc1"},{"qid":"5919350","no":29,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>当前，全球生物多样性下降趋势尚未得到根本<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，植物保护形势仍然十分严峻。保护植物就是保护人类的未来。我们应加快建立以国家公园为主体的自然保护地体系，让重要自然生态系统得到最<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的保护，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>建设国家植物园体系，构建以国家植物园为主体的全国植物迁地保护网络。<br>依次填入画横线部分最恰当的一项是：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"控制 严密 高规格"},{"k":"B","t":"抑制 有效 高水平"},{"k":"C","t":"遏制 严格 高质量"},{"k":"D","t":"压制 有力 高标准"}],"answer":"C","multi":false,"explanation":"<p>第一空，搭配“趋势”，根据“植物保护形势仍然十分严峻”可知，全球生物多样性下降趋势仍然存在，A项“控制”指掌握住不使任意活动或越出范围，B项“抑制”指压下去、控制，C项“遏制”指阻止、制止，置于此处均能体现全球生物多样性下降趋势仍然存在，符合文意，保留。D项“压制”指用强力限制，置于此处程度过重，且多搭配“对手”“火力”等，与“趋势”搭配不当，排除。<br>第二空，根据“加快建立以国家公园为主体的自然保护地体系”“建设国家植物园体系，构建以国家植物园为主体的全国植物迁地保护网络”可知，对自然生态系统要形成体系化、整体性、全方位保护，A项“严密”指周密、没有疏漏，C项“严格”指遵守或执行规定、规则十分认真、不偏离原则、不容马虎，均符合文意，保留。B项“有效”指有成效、有效果，侧重结果层面，而文段通过“建立”“建设”“构建”强调保护的举措，不如A、C两项更贴合文意，排除。<br>第三空，根据文意可知，文段侧重强调让植物得到更充分的保护，故横线处词语应体现更好地建设国家植物园体系，C项“高质量”侧重强调产品或工作更优，符合文意，当选。A项“高规格”侧重规范、格局更高，文段并未体现“格局更高”，且一般不与“建设”直接搭配使用，应论述为“建设高规格的国家植物园体系”，搭配不当，排除。<br>故正确答案为C。<br>【文段出处】人民日报《保护植物就是保护人类的未来（生态论苑）》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":43,"pid":"p4999a05dc1"},{"qid":"13628187","no":30,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>构建高水平全民健身公共服务体系，体现在以人民为中心的系统性建构中。从按人口要素<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>资源布局，到推动全民健身公共服务城乡区域<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>发展；从构建多层级健身设施网络和城镇社区15分钟健身圈，到建立分学段、跨区域的四级青少年体育赛事体系，人民对高品质生活的需求，决定了体育是<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的内容。<br>依次填入画横线部分最恰当的一项是：</p>","material":"<p>        每年5月底到6月底，在亚洲大陆北部的苔原地区，温度升到10摄氏度以上，勺嘴鹬迎来了繁育期。等到7月初，雏鸟纷纷破壳而出，等待它们的，将是一段漫长的旅程。</p><p>        苔原上夏季很短暂。雏鸟破壳后，雌性亲鸟经过短暂逗留就向南飞走了。雄鹬留下照顾雏鸟两周左右，等小勺嘴鹬刚能独立觅食，便也向温暖的南方迁徙。</p><p>        小勺嘴鹬怎么办？虽无父母教，它们却知道要去哪里，还知道怎么去——这可能是渐渐寒冷的环境所迫，可能是对周边其他候鸟的模仿，总之，这是刻在它们基因里的本能。</p><p>        候鸟为何要迁徙？有很多假说。当北方地区温度下降到0摄氏度及以下，水面冰封，鱼虾昆虫等食物变少，候鸟会在秋天来临时，一路南飞，寻找食物来源。那为何候鸟不待在热带、不再北归呢？因为<u>                    </u>，候鸟会选择在一个区域食物最丰富的时间集中觅食。更重要的是，热带并不利于勺嘴鹬这样来自西伯利亚的鸟类繁殖。</p><p>        为了更好地生存，不同候鸟有不同的选择。勺嘴鹬是一种早成鸟，亲鸟在产卵和孵化时消耗巨大。为保存体力、保障远距离飞行和来年的成功繁殖，雌鸟选择先行一步。到了秋天，幼鸟身体里的“迁徙基因”会被唤醒，它们“懂得”沿着亚洲大陆东边的海岸线向南飞，每几百公里小憩一到两天，直到我国江苏盐城东台条子泥湿地，在此换羽、停歇3个月，然后再出发，飞向广东或继续往南到东南亚越冬。好在勺嘴鹬“好养活”，滩涂上鱼虾管够，不需要特别照顾。而作为晚成鸟的丹顶鹤就幸福多了。小鹤在黑龙江扎龙国家级自然保护区出生后，父母会定期投喂、教它们怎么飞行，迁徙时还会带着小鹤一起，“手把手”教在哪选点、怎样觅食。这是因为雌鹤每次产卵一般只有两枚，对种群来说比较珍贵，加上迁徙路线只有2000多公里——先往东沿着陆地飞向海岸线，再一路南下到辽河口、黄河三角洲，再到越冬地盐城国家级珍禽自然保护区，鹤爸鹤妈有余力带着孩子一起飞。而且，鹤类的食物主要是植物块茎，要从湿地、滩涂中挖出来，有的能吃，有的不能吃——如果没有迁徙途中父母的“教”和自己的“学”,小鹤就会生存困难。</p><p>        不论是先天遗传还是要后天学习，不同候鸟都有一套巧妙的“迁徙机制”，以及精准的“导航系统”。值得注意的是，并不是所有候鸟都沿着海岸线飞。老鹰、雕等一些猛禽，就是沿着山脊线迁徙。以凤头蜂鹰为例，它们的食物在陆地上，且陆地上因太阳辐射带来的上升热气流更充足，让它们可以展开宽阔的翅膀借力，轻松滑翔。凤头蜂鹰会把我国从西向东、从高到低的三级阶梯间的“台阶差”作为地标，再通过太阳位置来分辨南北，实现“导航”飞行。</p><p>        那么，夜里迁徙的候鸟，靠什么“导航”呢？科学家在雀形目候鸟的身体中发现了一种感应电磁的蛋白，可根据地球南北极电磁感应的变化来分辨方向，还有的鸟类懂得观测星星的东升西落来定位。</p><p>        候鸟也有迷路的。遗憾的是，一旦迷路，大多数将无法存活。所以，如今候鸟的迁徙路线是经过成千上万年的探路、尝试、优化逐渐发展而来的，蕴含了大自然的无穷奥秘。</p>","materialNo":1,"options":[{"k":"A","t":"规划 平衡 举足轻重"},{"k":"B","t":"调整 协同 必不可少"},{"k":"C","t":"统筹 均衡 不可或缺"},{"k":"D","t":"优化 协调 至关重要"}],"answer":"C","multi":false,"explanation":"<p>第一空，根据“从······到······；从······到······”可知，后文内容是对首句“构建高水平全民健身公共服务体系，体现在以人民为中心的系统性建构中”的具体展开，“构建”指建立，侧重从无到有的过程，横线处也应体现从无到有之意，A项“规划”指比较全面的、长远的发展计划，C项“统筹”指通盘筹划，均可体现从无到有的过程，保留。B项“调整”指重新调配整顿，D项“优化”指采取一定措施使变得优秀，均侧重于在已有的基础上做些调配，并非是从无到有的过程，排除。<br>第二空，搭配“发展”，形容全民健身公共服务城乡区域发展的情况，A项“平衡”指倾向于保持稳定的情况，C项“均衡”指平衡，均与“发展”搭配恰当，保留。<br>第三空，搭配“内容”，C项“不可或缺”表示非常重要，不能有一点点的缺失，通常形容必不可少的因素或部分，与“内容”搭配恰当，当选。A项“举足轻重”比喻能起到影响全局的关键作用，通常搭配“地位”“作用”等，与“内容”搭配不当，排除。<br>故正确答案为C。<br>【文段出处】人民网《全民健身迎来全新发展契机（体坛观澜）》</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"言语理解与表达"},"idx":44,"pid":"p4999a05dc1"},{"qid":"5919074","no":1,"type":"数学运算","module":"数量关系","stem":"<p>-6，-2，-10，6，-26，（    ）</p>","options":[{"k":"A","t":"-90"},{"k":"B","t":"90"},{"k":"C","t":"-38"},{"k":"D","t":"38"}],"answer":"D","multi":false,"explanation":"<p>观察数列，无明显特征，优先考虑多级数列。后一项减前一项得到新数列：4，-8，16，-32，（    ），是公比为-2的等比数列，则下一项为（-32）×（-2）=64。故题干所求项为（-26）+64=38。<br>故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"数量关系"},"idx":45,"pid":"p4999a05dc1"},{"qid":"15121096","no":2,"type":"数学运算","module":"数量关系","stem":"<p>65.11，72.9，83.11，98.17，117.9，（    ）。</p>","options":[{"k":"A","t":"140.17"},{"k":"B","t":"140.5"},{"k":"C","t":"148.13"},{"k":"D","t":"148.17"}],"answer":"B","multi":false,"explanation":"<p>数列各项均为小数，优先考虑机械划分。整数部分形成数列：65，72，83，98，117，（    ），作差后得到新数列：7，11，15，19，（    ），是公差为4的等差数列，则整数部分下一项为117+19+4=140，排除C、D两项；观察发现，小数部分为整数部分的各位数字相加，只有B项（1+4+0=5）满足。<br>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"数量关系"},"idx":46,"pid":"p4999a05dc1"},{"qid":"15121123","no":3,"type":"数学运算","module":"数量关系","stem":"<p><img src=\"assets/img/gongshi/formula-8480548ac6b11d51.png\" class=\"tex\">，<img src=\"assets/img/gongshi/formula-a1b1ceb80d09988c.png\" class=\"tex\">，<img src=\"assets/img/gongshi/formula-29c8a7e6af9dcb90.png\" class=\"tex\">，<img src=\"assets/img/gongshi/formula-9770e5c725466ab5.png\" class=\"tex\">，<img src=\"assets/img/gongshi/formula-ae62accab49d439f.png\" class=\"tex\">，（    ）。</p>","options":[{"k":"A","t":"<p><img src=\"assets/img/gongshi/formula-c0de286e81adf969.png\" class=\"tex\"></p>"},{"k":"B","t":"<p><img src=\"assets/img/gongshi/formula-b274638bc17c52a5.png\" class=\"tex\"></p>"},{"k":"C","t":"<p><img src=\"assets/img/gongshi/formula-5756fdf9be49e144.png\" class=\"tex\"></p>"},{"k":"D","t":"<p><img src=\"assets/img/gongshi/formula-07f858456e13fb69.png\" class=\"tex\"></p>"}],"answer":"D","multi":false,"explanation":"<p>观察数列，有开方数和被开方数，优先考虑机械划分。原数列可转化为：<img src=\"assets/img/gongshi/formula-86bc045d8ce5a316.png\" class=\"tex\">，<img src=\"assets/img/gongshi/formula-a1b1ceb80d09988c.png\" class=\"tex\">，<img src=\"assets/img/gongshi/formula-5d6f68af219483f6.png\" class=\"tex\">，<img src=\"assets/img/gongshi/formula-9770e5c725466ab5.png\" class=\"tex\">，<img src=\"assets/img/gongshi/formula-ae62accab49d439f.png\" class=\"tex\">，（    ）。被开方数形成数列：3，5，9，17，33，（    ），后项减前项得到：2，4，8，16，（    ），是公比为2的等比数列，下一项为16×2=32，则所求项被开方数为33+32=65。开方数形成数列：2，5，10，17，26，（    ），后项减前项得到：3，5，7，9，（    ），是公差为2的等差数列，下一项为9+2=11，则所求项开方数为26+11=37。故所求项为<img src=\"assets/img/gongshi/formula-07f858456e13fb69.png\" class=\"tex\">。</p><p>故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"数量关系"},"idx":47,"pid":"p4999a05dc1"},{"qid":"5919082","no":4,"type":"数学运算","module":"数量关系","stem":"<p><img src=\"assets/img/gongshi/formula-478a48f2934d67c5.png\" class=\"tex\">，<img src=\"assets/img/gongshi/formula-361fbf4cb58d1617.png\" class=\"tex\">，<img src=\"assets/img/gongshi/formula-4c3aec0e7d115c6e.png\" class=\"tex\">，<img src=\"assets/img/gongshi/formula-04cecc08a4b824cf.png\" class=\"tex\">，<img src=\"assets/img/gongshi/formula-e141f0acdb89d316.png\" class=\"tex\">，（    ）。</p>","options":[{"k":"A","t":"<p><img src=\"assets/img/gongshi/formula-cd18f6b84d573684.png\" class=\"tex\"></p>"},{"k":"B","t":"<p><img src=\"assets/img/gongshi/formula-57af22ae24d56498.png\" class=\"tex\"></p>"},{"k":"C","t":"<p><img src=\"assets/img/gongshi/formula-450c53cb47df02b2.png\" class=\"tex\"></p>"},{"k":"D","t":"<p><img src=\"assets/img/gongshi/formula-e388b45079786c2a.png\" class=\"tex\"></p>"}],"answer":"C","multi":false,"explanation":"<p>数列各项均为分数，考虑分数数列。分子、分母分开看无明显规律，考虑整体看。各项分子、分母相加得到新数列：3，6，12，24，48，（    ），是公比为2的等比数列，则新数列下一项为48×2=96，即所求项分子、分母之和为96，观察选项，只有C项47+49=96满足。<br>故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"数量关系"},"idx":48,"pid":"p4999a05dc1"},{"qid":"5919083","no":5,"type":"数学运算","module":"数量关系","stem":"<p>某厂推出含酒的新品种巧克力，每颗的质量为10克，其中含酒2%，售价为17.5元，若酒的密度为0.9克/毫升，则500毫升酒做成的巧克力销售额为（    ）。</p>","options":[{"k":"A","t":"35875元"},{"k":"B","t":"36375元"},{"k":"C","t":"37625元"},{"k":"D","t":"39375元"}],"answer":"D","multi":false,"explanation":"<p>根据公式：质量=密度×体积，可得500毫升酒的质量=0.9×500=450克，每颗巧克力含酒质量=10×2%=0.2克。则500毫升酒做成的巧克力销售额<img src=\"assets/img/gongshi/formula-908153fb0d4a7e42.png\" class=\"tex\">元。</p><p>故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"数量关系"},"idx":49,"pid":"p4999a05dc1"},{"qid":"5919084","no":6,"type":"数学运算","module":"数量关系","stem":"<p>一列长为210米的动车以180千米/小时的速度行驶。某乘客拍窗外风景视频时，恰好拍到平行铁轨上一列长420米、相向而行的高速列车，该高速列车经过窗户的时间是3.6秒。若不计窗户长度，则该高速列车的速度为（    ）。</p>","options":[{"k":"A","t":"210千米/时"},{"k":"B","t":"240千米/时"},{"k":"C","t":"450千米/时"},{"k":"D","t":"630千米/时"}],"answer":"B","multi":false,"explanation":"<p>如下图所示，乘客拍到该高速列车即为车窗与平行列车的车头相对重合，该高速列车完全经过即为车窗与平行列车的车尾相对重合，则本题可转化为车窗与平行列车车尾的相遇问题，相遇距离即为平行列车的车长。根据相遇公式：<img src=\"assets/img/gongshi/formula-28bdb572bdbd620e.png\" class=\"tex\">，可得<img src=\"assets/img/gongshi/formula-908721672e909cc7.png\" class=\"tex\">千米/时，则该高速列车的速度=420-180=240千米/时。</p><p><img src=\"assets/img/timu/18ca50e0dc0aaa2.png\" class=\"fig\" style=\"width:466px;height:135px;\"></p><p>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"数量关系"},"idx":50,"pid":"p4999a05dc1"},{"qid":"17900756","no":7,"type":"数学运算","module":"数量关系","stem":"<p>元旦期间，某超市开展促销活动，甲、乙两种商品的单价之和为25元，购买甲商品2件及以上可享受八折优惠，购买乙商品4件及以上可享受六折优惠。小王下单购买了2件甲商品和4件乙商品，共优惠16元，则甲商品的单价是：</p>","options":[{"k":"A","t":"5元"},{"k":"B","t":"10元"},{"k":"C","t":"15元"},{"k":"D","t":"20元"}],"answer":"D","multi":false,"explanation":"<p>设甲商品的单价为x元，则乙商品的单价为（25-x）元。由于小王下单购买了2件甲商品和4件乙商品，共优惠16元，可列等式：<img src=\"assets/img/gongshi/formula-20a6c681c52dd2aa.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-08dbd8bfa7897e6f.png\" class=\"tex\">，解得x=20，即甲商品的单价是20元。</p><p>故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"数量关系"},"idx":51,"pid":"p4999a05dc1"},{"qid":"17900757","no":8,"type":"数学运算","module":"数量关系","stem":"<p>某咖啡厅共有20个座位，每天上午11：00开始营业，14：00后不再接待新客人，营业期间任何时刻的上座率都不低于80%。若来喝咖啡的顾客从入座到离开的时间不超过50分钟，则该咖啡厅每天营业期间消费的总人数最少为：</p>","options":[{"k":"A","t":"48"},{"k":"B","t":"56"},{"k":"C","t":"64"},{"k":"D","t":"72"}],"answer":"C","multi":false,"explanation":"<p>根据题意，所求为总人数最少，需要营业期间上座率尽可能低，且来喝咖啡的顾客在咖啡厅的时间尽可能长，即任何时刻的上座率为80%，来喝咖啡的顾客从入座到离开的时间均为50分钟。可知任何时刻咖啡厅均有20×80%=16人，11：00—14：00经历了180分钟，由于<img src=\"assets/img/gongshi/formula-bf757ad2e3cc58b6.png\" class=\"tex\">······30分钟，即需要4拨客人。则该咖啡厅每天营业期间消费的总人数最少为16×4=64人。</p><p>故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"数量关系"},"idx":52,"pid":"p4999a05dc1"},{"qid":"5919088","no":9,"type":"数学运算","module":"数量关系","stem":"<p>某超市为回馈消费者，将举办购物抽奖活动。每人只能抽奖一次，奖金有三种：一等奖888元，二等奖88元，三等奖8元。若前100个中奖者的奖金总额为2480元，则其中获得三等奖的最少有：</p>","options":[{"k":"A","t":"95人"},{"k":"B","t":"89人"},{"k":"C","t":"79人"},{"k":"D","t":"69人"}],"answer":"C","multi":false,"explanation":"<p>设获得一、二、三等奖的人数分别为x人、y人、z人，根据前100个中奖者的奖金总额为2480元，可列方程组：<img src=\"assets/img/gongshi/formula-d8bb900eee1e0ac7.png\" class=\"tex\">，整理可得：<img src=\"assets/img/gongshi/formula-58af4916e80b70b9.png\" class=\"tex\">，①×11-②得到：10z-100x=790，即z=10x+79。若想要获得三等奖的人数z最少，则x应尽量小，则当x=0时，z=79，即获得三等奖的最少有79人。</p><p>故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"数量关系"},"idx":53,"pid":"p4999a05dc1"},{"qid":"5919089","no":10,"type":"数学运算","module":"数量关系","stem":"<p>已知某家族4位成员的年龄总和为142岁，且他们的年龄恰好成等差数列，若其中一位的年龄为47岁，则这4人中最年长者的年龄为（    ）。</p>","options":[{"k":"A","t":"65岁"},{"k":"B","t":"70岁"},{"k":"C","t":"83岁"},{"k":"D","t":"90岁"}],"answer":"B","multi":false,"explanation":"<p>根据选项可知，47岁不是最年长者的年龄。又根据等差数列性质可知，4位成员中，第二大和第三大的年龄和为<img src=\"assets/img/gongshi/formula-d38a59363ed9a8de.png\" class=\"tex\">岁，且由于<img src=\"assets/img/gongshi/formula-72042608aab25c01.png\" class=\"tex\">，则47岁应是第二大的年龄，那么第三大的年龄为71-47=24岁，年龄公差为47-24=23岁，故这4人中最年长者的年龄为47+23=70岁。</p><p>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"数量关系"},"idx":54,"pid":"p4999a05dc1"},{"qid":"17900759","no":11,"type":"数学运算","module":"数量关系","stem":"<p>某居民楼居住人数介于90和110之间，其中50岁及以上居民占<img src=\"assets/img/gongshi/formula-cf17b45aa802082b.png\" class=\"tex\">，女性占<img src=\"assets/img/gongshi/formula-e9da98c7cd17065f.png\" class=\"tex\">。若该居民楼30岁及以上居民比30岁以下居民多20人，则30岁以下居民比50岁及以上居民多：</p>","options":[{"k":"A","t":"30人"},{"k":"B","t":"27人"},{"k":"C","t":"23人"},{"k":"D","t":"20人"}],"answer":"A","multi":false,"explanation":"<p>根据题意可知，该居民楼居住总人数应既是12的整数倍又是16的整数倍，即是48（12和16的最小公倍数）的整数倍；又根据总人数介于90和110之间，即总人数为96人。则30岁以下居民有<img src=\"assets/img/gongshi/formula-e5075a4071a99e99.png\" class=\"tex\">人，50岁及以上居民有<img src=\"assets/img/gongshi/formula-cf480dd5d12577b5.png\" class=\"tex\">人，故30岁以下居民比50岁及以上居民多38-8=30人。</p><p>故正确答案为A。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"数量关系"},"idx":55,"pid":"p4999a05dc1"},{"qid":"17900758","no":12,"type":"数学运算","module":"数量关系","stem":"<p>圆柱形容器底部放有一个长方体铁块，打开水龙头开始往容器中注水，6分钟水面恰好淹没铁块，再过16分钟灌满容器。若容器和铁块的高分别为45厘米和15厘米，则铁块和容器的体积之比是：</p>","options":[{"k":"A","t":"1：12"},{"k":"B","t":"1：9"},{"k":"C","t":"1：6"},{"k":"D","t":"1：3"}],"answer":"A","multi":false,"explanation":"<p>设圆柱形容器每厘米高的体积为a，赋值水龙头每分钟的注水量为1，根据题干“6分钟水面恰好淹没铁块”，则有：<img src=\"assets/img/gongshi/formula-db4ce45ebb979c6c.png\" class=\"tex\">①；又根据题干“再过16分钟灌满容器”，则有：45a-15a=16②，联立①②两式，解得<img src=\"assets/img/gongshi/formula-83ed35d492f80722.png\" class=\"tex\">，<img src=\"assets/img/gongshi/formula-e4045d91f977ccb4.png\" class=\"tex\">。则圆柱形容器的体积为45a=24，故铁块和容器的体积之比为2：24=1：12。</p><p>故正确答案为A。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"数量关系"},"idx":56,"pid":"p4999a05dc1"},{"qid":"5919095","no":13,"type":"数学运算","module":"数量关系","stem":"<p>小张所在单位共有4个科室，现以科室为单位组织文艺演出，每个科室出2个节目。演出结束后，因8个节目都非常精彩，决定从中随机选3个节目参加上级组织的汇演。则小张所在科室出的节目至少有一个被选送参加汇演的概率是：</p>","options":[{"k":"A","t":"<p><img src=\"assets/img/gongshi/formula-d7f4e62332540a58.png\" class=\"tex\"></p>"},{"k":"B","t":"<p><img src=\"assets/img/gongshi/formula-edfc085deb3fce9f.png\" class=\"tex\"></p>"},{"k":"C","t":"<p><img src=\"assets/img/gongshi/formula-ccfa50a9f85acf13.png\" class=\"tex\"></p>"},{"k":"D","t":"<p><img src=\"assets/img/gongshi/formula-87119e0664cd9b21.png\" class=\"tex\"></p>"}],"answer":"D","multi":false,"explanation":"<p>根据题意，总情况是从8个节目中随机选出3个，情况数为<img src=\"assets/img/gongshi/formula-4e273330cddbc5f7.png\" class=\"tex\">种；符合条件的情况是小张所在科室出的2个节目中至少有一个被选送，即有1个节目或者2个节目被选送。正面情况较复杂，可从反面分析。反面情况为3个选送节目均不来自小张所在的科室，则从另外8-2=6个节目中随机选出3个，情况数为<img src=\"assets/img/gongshi/formula-a308eddfdcb69c24.png\" class=\"tex\">种。故题干所求概率<img src=\"assets/img/gongshi/formula-f074e8268ff972ea.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-51d6b7c8f8a493e0.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-a88fbccb171d00be.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-d6a2140c0489f5ab.png\" class=\"tex\">。</p><p>故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"数量关系"},"idx":57,"pid":"p4999a05dc1"},{"qid":"5919097","no":14,"type":"数学运算","module":"数量关系","stem":"<p>某夫妇拟从2023年12月1日（星期五）起实施健身计划。妻子的计划是当天的日期为质数就游泳，丈夫的计划是每周一、三、五游泳。按该夫妇的计划，他们2023年12月同日游泳的天数是（    ）。</p>","options":[{"k":"A","t":"5"},{"k":"B","t":"4"},{"k":"C","t":"3"},{"k":"D","t":"2"}],"answer":"C","multi":false,"explanation":"<p>因丈夫每周一、三、五游泳，且2023年12月1日为周五，所以2023年12月丈夫前三次游泳的日期为1日（周五）、4日（周一）、6日（周三），以7天一星期的周期进行推算，2023年12月丈夫游泳的日期如下表所示：</p><p><img src=\"assets/img/timu/18ca516e52f5619.png\" class=\"fig\" style=\"width:700px;height:158px;\"></p><p>其中日期为质数的有11日、13日、29日，共3天，即该夫妇2023年12月同日游泳的天数是3天。</p><p>故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"数量关系"},"idx":58,"pid":"p4999a05dc1"},{"qid":"5919099","no":15,"type":"数学运算","module":"数量关系","stem":"<p>甲、乙、丙三人合作完成一项任务。乙先做9天，再和甲合作6天，完成了任务的60%，剩下的任务，若由丙做，恰好10天完成。甲、乙、丙三人的工作效率之比是：</p>","options":[{"k":"A","t":"5：4：6"},{"k":"B","t":"6：4：5"},{"k":"C","t":"10：15：12"},{"k":"D","t":"12：15：10"}],"answer":"A","multi":false,"explanation":"<p>根据题意可得，9×乙+6×（甲+乙）=60%×工作总量······①，10×丙=（1-60%）×工作总量······②，①÷②可得：<img src=\"assets/img/gongshi/formula-b717d23558a4bf21.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-f06f635481d0d95b.png\" class=\"tex\">，则2甲+5乙=5丙，依次代入选项：</p><p>A项：赋值甲、乙、丙三人的工作效率分别为5、4、6，则2×5+5×4=30=5×6，满足题干条件，当选；</p><p>B项：赋值甲、乙、丙三人的工作效率分别为6、4、5，则<img src=\"assets/img/gongshi/formula-27890fe4e2860c70.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-3ed54294e1dced6a.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-75b3858f3ef86941.png\" class=\"tex\">，不满足题干条件，排除；</p><p>C项：赋值甲、乙、丙三人的工作效率分别为10、15、12，则<img src=\"assets/img/gongshi/formula-b7f99e5fbff71a6f.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-3ed54294e1dced6a.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-6cc6b61a1d8be00a.png\" class=\"tex\">，不满足题干条件，排除；</p><p>D项：赋值甲、乙、丙三人的工作效率分别为12、15、10，则<img src=\"assets/img/gongshi/formula-6d1b49175914d0c5.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-3ed54294e1dced6a.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-f98ccdda1c5c5859.png\" class=\"tex\">，不满足题干条件，排除。</p><p>故正确答案为A。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"数量关系"},"idx":59,"pid":"p4999a05dc1"},{"qid":"5919100","no":16,"type":"数学运算","module":"数量关系","stem":"<p>某公司派出5名人力资源专员去2个一线城市和2个二线城市参加秋季招聘会。若每名专员只去其中1个城市，每个一线城市至少派1名专员，每个二线城市只派1名专员，则不同的派出方法共有（    ）。</p>","options":[{"k":"A","t":"60种"},{"k":"B","t":"72种"},{"k":"C","t":"120种"},{"k":"D","t":"144种"}],"answer":"C","multi":false,"explanation":"<p>5名专员分配到4个城市，其中每个一线城市至少派1名专员，每个二线城市只派1名专员，则5名专员中有3名专员分配到2个一线城市（分别为2名专员和1名专员），其余2名专员分配到2个二线城市（各1名专员）。从5名专员中选出2名专员，再从剩下3名专员中选出1名专员，这两组人分配到2个一线城市，有<img src=\"assets/img/gongshi/formula-a5c45a8a83c8c73b.png\" class=\"tex\">种；剩下2名专员分配到2个二线城市，有<img src=\"assets/img/gongshi/formula-868f62160c539f2f.png\" class=\"tex\">种。分步用乘法，则不同的派出方法共有60×2=120种。</p><p>故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"数量关系"},"idx":60,"pid":"p4999a05dc1"},{"qid":"17900760","no":17,"type":"数学运算","module":"数量关系","stem":"<p>甲瓶中有50克浓度为80%的溶液，加水50克混合后倒出40克至空瓶乙中；再往甲瓶中加水40克，混合后又倒出40克至乙瓶中。最终乙瓶中溶液的浓度是：</p>","options":[{"k":"A","t":"38%"},{"k":"B","t":"32%"},{"k":"C","t":"26%"},{"k":"D","t":"20%"}],"answer":"B","multi":false,"explanation":"<p>起初甲瓶中有50克浓度为80%的溶液，加入50克水后变为100克浓度为80%÷2=40%的溶液，则首次倒入乙瓶中的为40克浓度为40%的溶液；再往甲瓶中加水40克后，甲瓶中有100-40+40=100克浓度为<img src=\"assets/img/gongshi/formula-a786620610027c9c.png\" class=\"tex\">的溶液，则再次倒入乙瓶中的为40克浓度为24%的溶液，故最终乙瓶中溶液的浓度是<img src=\"assets/img/gongshi/formula-a04aae98ad6f5130.png\" class=\"tex\">。</p><p>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"数量关系"},"idx":61,"pid":"p4999a05dc1"},{"qid":"5919108","no":18,"type":"数学运算","module":"数量关系","stem":"<p>某基层工会共有180名会员，举行甲、乙两项工会活动，60%的会员参加甲活动，50%的会员参加乙活动，若只参加甲活动的会员有80人，则只参加乙活动的会员有（    ）。</p>","options":[{"k":"A","t":"10人"},{"k":"B","t":"28人"},{"k":"C","t":"62人"},{"k":"D","t":"72人"}],"answer":"C","multi":false,"explanation":"<p>根据题意可得，参加甲活动的会员人数为180×60%=108人，参加乙活动的会员人数为180×50%=90人，根据“只参加甲活动的会员有80人”，可得甲、乙两项活动都参加的会员人数为108-80=28人，如下图所示：</p><p><img src=\"assets/img/timu/18ca5173d283c76.png\" class=\"fig\" style=\"width:310px;height:276px;\"></p><p>则只参加乙活动的会员有90-28=62人。</p><p>故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"数量关系"},"idx":62,"pid":"p4999a05dc1"},{"qid":"5919119","no":19,"type":"数学运算","module":"数量关系","stem":"<p>如图所示，ABCDEF是一个边长为2的正六边形，圆O是<img src=\"assets/img/gongshi/formula-9d00bfbf530e8d7c.png\" class=\"tex\">的内切圆，则圆O的面积是（    ）。</p><p><img src=\"assets/img/timu/18ca512bf886d25.png\" class=\"fig\" style=\"width:246px;height:212px;\"></p>","options":[{"k":"A","t":"<p><img src=\"assets/img/gongshi/formula-993c1f9dd31d0ad5.png\" class=\"tex\"></p>"},{"k":"B","t":"<p><img src=\"assets/img/gongshi/formula-a8a0f9805bedecab.png\" class=\"tex\"></p>"},{"k":"C","t":"<p><img src=\"assets/img/gongshi/formula-502a580a7cb0dfe0.png\" class=\"tex\"></p>"},{"k":"D","t":"<p><img src=\"assets/img/gongshi/formula-820336e091800d28.png\" class=\"tex\"></p>"}],"answer":"A","multi":false,"explanation":"<p>方法一：由于ABCDEF是正六边形，可得AC=CE=EA，即<img src=\"assets/img/gongshi/formula-9d00bfbf530e8d7c.png\" class=\"tex\">为正三角形，则<img src=\"assets/img/gongshi/formula-9d00bfbf530e8d7c.png\" class=\"tex\">内切圆的圆心O即为正六边形ABCDEF的中心。作<img src=\"assets/img/gongshi/formula-9d00bfbf530e8d7c.png\" class=\"tex\">的中线AH，连接FO，<img src=\"assets/img/gongshi/formula-cd811c969b44c17f.png\" class=\"tex\">为正三角形，如下图所示：</p><p><img src=\"assets/img/timu/18ca51834027baa.png\" class=\"fig\" style=\"width:257px;height:241px;\"></p><p>已知AF=FE=2，且正六边形内角<img src=\"assets/img/gongshi/formula-530392b46674fd26.png\" class=\"tex\">，则<img src=\"assets/img/gongshi/formula-15c508586c89c904.png\" class=\"tex\">，<img src=\"assets/img/gongshi/formula-c1c6dfa2bcdf0202.png\" class=\"tex\">。在直角<img src=\"assets/img/gongshi/formula-783b3ab41c0f0b67.png\" class=\"tex\">中，<img src=\"assets/img/gongshi/formula-06b7b9d31d6de989.png\" class=\"tex\">，<img src=\"assets/img/gongshi/formula-a55f3d2af1d10d23.png\" class=\"tex\">，且AO=AF=2，所以所求圆半径OH=AH-AO=3-2=1，所求圆面积<img src=\"assets/img/gongshi/formula-78b685eec56a9589.png\" class=\"tex\">。</p><p>方法二：如下图所示，连接AO、FO，<img src=\"assets/img/gongshi/formula-eeefc175b8061d7e.png\" class=\"tex\">为正三角形，由于AO为<img src=\"assets/img/gongshi/formula-ef8cc04e75cdd434.png\" class=\"tex\">的中线且<img src=\"assets/img/gongshi/formula-d671aac161f2e9b6.png\" class=\"tex\">，则<img src=\"assets/img/gongshi/formula-7461b639dc7c7cb0.png\" class=\"tex\">，AG为<img src=\"assets/img/gongshi/formula-eeefc175b8061d7e.png\" class=\"tex\">的中线，即所求圆半径<img src=\"assets/img/gongshi/formula-e6c8034d257f6aca.png\" class=\"tex\">，所求圆面积<img src=\"assets/img/gongshi/formula-78b685eec56a9589.png\" class=\"tex\">。</p><p><img src=\"assets/img/timu/18ca518bff96707.png\" class=\"fig\" style=\"width:245px;height:234px;\"></p><p>故正确答案为A。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"数量关系"},"idx":63,"pid":"p4999a05dc1"},{"qid":"16095254","no":1,"type":"类比推理","module":"判断推理","stem":"<p>参加或指导小微堵点改造项目的不可能同时有以下哪两个人？</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"王教授和马教授"},{"k":"B","t":"马教授和小刘"},{"k":"C","t":"小刘和小周"},{"k":"D","t":"小周和王教授"}],"answer":"C","multi":false,"explanation":"<p>第一步：分析题干条件。<br>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；<br>（2）每位工作人员只能参加一个项目，提倡多人合作；<br>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；<br>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。<br>第二步：根据题干条件进行推理。<br>提问方式为“不可能”，优先考虑代入法。<br>代入A项，若指导小微堵点改造项目的是王教授和马教授，由条件（4）可知，指导历史街区微改造项目的是钱教授，结合条件（1）中的“每位教授至少指导一位工作人员”可知，历史街区微改造项目必须有工作人员参加，此时只要这两个项目都分别有至少一位工作人员参加即可，与题干条件不矛盾，该项可能成立，排除；<br>代入B项，若指导小微堵点改造项目的是马教授，参加小微堵点改造项目的是小刘，由条件（4）可知，指导历史街区微改造项目的是钱教授，结合条件（1）中的“每位教授至少指导一位工作人员”可知，历史街区微改造项目必须有工作人员参加，小郑参加小微堵点改造或跨区断头路建设项目，那么此时小周参加历史街区微改造项目即可，与题干条件不矛盾，该项可能成立，排除；<br>代入C项，若参加小微堵点改造项目的是小刘和小周，由条件（4）可知，小郑参加小微堵点改造或跨区断头路建设项目，此时3名工作人员中没有人可以参加由钱教授指导的历史街区微改造项目，不符合条件（1）中的“每位教授至少指导一位工作人员”，该项不可能成立，当选；<br>代入D项，若参加小微堵点改造项目的是小周，指导小微堵点改造项目的是王教授，由条件（4）可知，小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目，结合条件（1）中的“每位教授至少指导一位工作人员”可知，历史街区微改造项目必须有工作人员参加，此时小刘参加历史街区微改造项目即可，与题干条件不矛盾，该项可能成立，排除。<br>本题为选非题，故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":64,"pid":"p4999a05dc1"},{"qid":"16095256","no":2,"type":"类比推理","module":"判断推理","stem":"<p>如果小周参加小型城市客厅打造项目，则以下哪一项一定为真？</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"小刘参加历史街区微改造项目"},{"k":"B","t":"王教授指导小型城市客厅打造项目"},{"k":"C","t":"马教授指导小微堵点改造项目"},{"k":"D","t":"小郑参加跨区断头路建设项目"}],"answer":"A","multi":false,"explanation":"<p>第一步：分析题干条件。<br>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；<br>（2）每位工作人员只能参加一个项目，提倡多人合作；<br>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；<br>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目；<br>（5）小周参加小型城市客厅打造项目。<br>第二步：根据题干条件进行推理。<br>条件（4）与条件（5）中有确定信息，优先从确定信息入手推理。由条件（4）可知，钱教授指导历史街区微改造项目，结合条件（1）中的“每位教授至少指导一位工作人员”可知，历史街区微改造项目一定有工作人员参加；由条件（4）可知，小郑参加小微堵点改造或跨区断头路建设项目，由条件（5）可知，小周参加小型城市客厅打造项目，结合条件（2）中的“每位工作人员只能参加一个项目”可知，参加历史街区微改造项目的工作人员不可能是小郑、小周，且只有3名工作人员，所以小刘一定参加历史街区微改造项目，对应A项。<br>故正确答案为A。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":65,"pid":"p4999a05dc1"},{"qid":"5919637","no":3,"type":"类比推理","module":"判断推理","stem":"<p>保护知识产权：保护创新</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"人之初：性本善"},{"k":"B","t":"德不孤：必有邻"},{"k":"C","t":"勤有功：戏无益"},{"k":"D","t":"经一事：长一智"}],"answer":"D","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>“保护知识产权”是“保护创新”的重要手段和举措，通过“保护知识产权”能达到“保护创新”的目的，二者为方式与目的的对应关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：“人之初，性本善”的意思是人出生之初，禀性本身都是善良的。“人之初”与“性本善”不是方式与目的的对应关系，与题干逻辑关系不一致，排除。<br>B项：“德不孤，必有邻”的意思是有道德的人是不会孤单的，必定会有志同道合的人来与他为伴。“德不孤”与“必有邻”不是方式与目的的对应关系，与题干逻辑关系不一致，排除。<br>C项：“勤有功，戏无益”的意思是人只要勤奋努力，就会有所成就；而嬉戏贪玩则对人没有任何好处。“勤有功”与“戏无益”不是方式与目的的对应关系，与题干逻辑关系不一致，排除。<br>D项：“经一事，长一智”的意思是亲身经历了某件事情，就能增长关于这方面的知识。通过“经一事”能达到“长一智”的目的，二者为方式与目的的对应关系，与题干逻辑关系一致，当选。<br>故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":66,"pid":"p4999a05dc1"},{"qid":"5919643","no":4,"type":"类比推理","module":"判断推理","stem":"<p>吴王好剑客：百姓多创瘢</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"白日依山尽：黄河入海流"},{"k":"B","t":"问君何能尔：心远地自偏"},{"k":"C","t":"海上生明月：天涯共此时"},{"k":"D","t":"烽火连三月：家书抵万金"}],"answer":"D","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>“吴王好剑客，百姓多创瘢”的意思是吴王喜爱精通剑术的侠客，为此老百姓身上伤痕累累。因为“吴王好剑客”，所以“百姓多创瘢”，二者为因果对应关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：“白日依山尽，黄河入海流”的意思是太阳依傍着西山慢慢地沉落，滔滔黄河朝着大海汹涌奔流。“白日依山尽”与“黄河入海流”为并列关系，与题干逻辑关系不一致，排除。<br>B项：“问君何能尔？心远地自偏”的意思是问我如何能做到这样，只要心中所想远离世俗，自然就会觉得所处地方僻静了。“问君何能尔”不是“心远地自偏”的原因，二者不是因果对应关系，与题干逻辑关系不一致，排除。<br>C项：“海上生明月，天涯共此时”的意思是茫茫的海上升起一轮明月，使人忆起远隔天涯海角的亲友，此时应该都在望着这轮明月。“海上生明月”不是“天涯共此时”的原因，二者不是因果对应关系，与题干逻辑关系不一致，排除。<br>D项：“烽火连三月，家书抵万金”的意思是连绵的战火已经持续很长时间了，家书难得，一封抵得上万两黄金。因为“烽火连三月”，所以“家书抵万金”，二者为因果对应关系，与题干逻辑关系一致，当选。<br>故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":67,"pid":"p4999a05dc1"},{"qid":"5919659","no":5,"type":"类比推理","module":"判断推理","stem":"<p>年华未暮：容貌先秋</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"十年树木：百年树人"},{"k":"B","t":"宁为玉碎：不为瓦全"},{"k":"C","t":"言者无心：听者有意"},{"k":"D","t":"人无远虑：必有近忧"}],"answer":"C","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>“年华未暮，容貌先秋”的意思是未到衰老的年纪，而容颜已经老去，虽然“年华未暮”，但是“容貌先秋”，二者为转折的对应关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：“十年树木，百年树人”的意思是培植树木需要十年，培育人才需要百年，指培养人才很不容易，二者为并列关系，与题干逻辑关系不一致，排除；<br>B项：“宁为玉碎，不为瓦全”的意思是宁愿做高贵的玉器而破碎，也不愿做低贱的瓦器得以保全，比喻宁为正义事业而牺牲，也不苟且偷生，二者为并列关系，与题干逻辑关系不一致，排除；<br>C项：“言者无心，听者有意”的意思是说话的人不注意，而听话的人却很留神，虽然“言者无心”，但是“听者有意”，二者为转折的对应关系，与题干逻辑关系一致，当选；<br>D项：“人无远虑，必有近忧”的意思是人若没有长远的谋虑，一定很快就有忧患，二者为条件的对应关系，与题干逻辑关系不一致，排除。<br>故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":68,"pid":"p4999a05dc1"},{"qid":"5919632","no":6,"type":"类比推理","module":"判断推理","stem":"<p>海：海沟：海量</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"天：天眼：天堑"},{"k":"B","t":"碑：碑座：碑林"},{"k":"C","t":"火：火焰：火气"},{"k":"D","t":"心：心房：心腹"}],"answer":"C","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>“海沟”指深度超过6000米的狭长的海底凹地，其中“海”是指海洋，是海的本义；“海量”指极大的数量、很大的酒量或宽宏的度量，其中“海”指像海一样，是海的引申义。二者含义不同，且第二个词为本义，第三个词为引申义。<br>第二步：判断选项词语间逻辑关系。<br>A项：“天眼”指佛教所说五眼之一、道教所说天神之眼，其中“天”指天空，是天的本义；“天堑”指天然形成的隔断交通的大沟，其中“天”指天然的，不是天的引申义，与题干逻辑关系不一致，排除；<br>B项：“碑座”指石碑下边的底座，“碑林”指聚集在一起的众多石碑，其中“碑”均指刻着文字或图画，竖起来作为纪念物或标记的石头，均是碑的本义，与题干逻辑关系不一致，排除；<br>C项：“火焰”指燃烧着的可燃气体，其中“火”指物体燃烧时所发出的光和焰，是火的本义；“火气”多指怒气、暴躁的脾气，其中“火”指像火一样，是火的引申义。二者含义不同，且第二个词为本义，第三个词为引申义，与题干逻辑关系一致，当选；<br>D项：“心房”指心脏内部上面左右两个空腔，也指人的内心，其中“心”是指心脏，是心的本义；“心腹”指亲信的人，其中“心”不是指像心一样，与题干逻辑关系不一致，排除。<br>故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":69,"pid":"p4999a05dc1"},{"qid":"5919634","no":7,"type":"类比推理","module":"判断推理","stem":"<p>梅花：梅花糕：糕</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"葡萄：葡萄酒：酒"},{"k":"B","t":"珊瑚：珊瑚树：树"},{"k":"C","t":"桥头：桥头堡：堡"},{"k":"D","t":"面包：面包车：车"}],"answer":"D","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>“梅花糕”因外形像“梅花”而得名，“梅花糕”是“糕”的一种，二者为种属关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：“葡萄酒”因原材料为“葡萄”而得名，与题干逻辑关系不一致，排除。<br>B项：“珊瑚树”因外形像“珊瑚”而得名，“珊瑚树”是“树”的一种，二者为种属关系，与题干逻辑关系一致，保留。<br>C项：“桥头堡”指为控制重要桥梁、渡口而设立的碉堡、地堡或据点，不是因外形像什么而得名，与题干逻辑关系不一致，排除。<br>D项：“面包车”因外形像“面包”而得名，“面包车”是“车”的一种，二者为种属关系，与题干逻辑关系一致，保留。<br>对比B、D两项，题干的“梅花糕”“糕”、D项的“面包车”“车”均是人工产物，而B项的“珊瑚树”“树”均是自然产物，故D项与题干逻辑关系更一致。<br>故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":70,"pid":"p4999a05dc1"},{"qid":"5919658","no":8,"type":"类比推理","module":"判断推理","stem":"<p>球赛：球员：裁判</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"教学：教师：家长"},{"k":"B","t":"庭审：被告：法官"},{"k":"C","t":"球场：球员：观众"},{"k":"D","t":"手术：患者：护士"}],"answer":"B","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>“球员”参与“球赛”，二者为活动与主体的对应关系；“裁判”判罚“球员”，二者为主体与被判罚对象的对应关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：“教师”参与“教学”，二者为活动与主体的对应关系，但“家长”不能判罚“教师”，与题干逻辑关系不一致，排除。<br>B项：“被告”参与“庭审”，二者为活动与主体的对应关系；“法官”判罚“被告”，二者为主体与被判罚对象的对应关系。与题干逻辑关系一致，当选。<br>C项：“球员”在“球场”打球，二者是地点与主体的对应关系，与题干逻辑关系不一致，排除。<br>D项：“患者”接受“手术”，而不是参与“手术”，且“护士”不能判罚“患者”，与题干逻辑关系不一致，排除。<br>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":71,"pid":"p4999a05dc1"},{"qid":"5919630","no":9,"type":"类比推理","module":"判断推理","stem":"<p>期刊：月刊：目录页</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"房屋：公寓：天花板"},{"k":"B","t":"能源：电池：电子书"},{"k":"C","t":"银行：企业：理财室"},{"k":"D","t":"欧盟：法国：凯旋门"}],"answer":"A","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>期刊是定期出版的刊物，月刊是期刊的一种，前两词为种属关系；目录页是月刊的组成部分，后两词为组成关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：公寓是房屋的一种，前两词为种属关系；天花板是公寓的组成部分，后两词为组成关系，与题干逻辑关系一致，当选；<br>B项：电池是一种能源，前两词为种属关系；当电子书指手持阅读器时，电池是电子书的组成部分，后两词为组成关系，但顺序与题干相反，与题干逻辑关系不一致，排除；<br>C项：有的银行是企业，有的银行不是企业，有的企业是银行，有的企业不是银行，前两词为交叉关系，与题干逻辑关系不一致，排除；<br>D项：法国是欧盟的成员国，前两词为组成关系；凯旋门是法国的代表性建筑，后两词为对应关系，与题干逻辑关系不一致，排除。<br>故正确答案为A。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":72,"pid":"p4999a05dc1"},{"qid":"16095259","no":10,"type":"类比推理","module":"判断推理","stem":"<p>手术机器人：医疗设备：高新装备</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"公办中学：事业单位：教育机构"},{"k":"B","t":"重大项目：在建工程：跨境设施"},{"k":"C","t":"耄耋老人：健康老人：高龄老人"},{"k":"D","t":"管理成本：人力成本：生产成本"}],"answer":"A","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>手术机器人既是医疗设备，又是高新装备，第一词与后两词均是种属关系；有的医疗设备是高新装备，有的医疗设备不是高新装备，有的高新装备是医疗设备，有的高新装备不是医疗设备，后两词是交叉关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：事业单位指接受国家或地方财政拨款，从事教育、科技、文化、卫生等活动，具备法人条件的社会服务组织。公办中学既是事业单位，又是教育机构，第一词与后两词均是种属关系；有的事业单位是教育机构，有的事业单位不是教育机构，有的教育机构是事业单位，有的教育机构不是事业单位，后两词是交叉关系，与题干逻辑关系一致，当选；<br>B项：有的重大项目是在建工程，有的重大项目不是在建工程，有的在建工程是重大项目，有的在建工程不是重大项目，前两词是交叉关系，与题干逻辑关系不一致，排除；<br>C项：耄耋老人指八九十岁的老人，有的耄耋老人是健康老人，有的耄耋老人不是健康老人，有的健康老人是耄耋老人，有的健康老人不是耄耋老人，前两词是交叉关系，与题干逻辑关系不一致，排除；<br>D项：管理成本与生产成本是并列关系，与题干逻辑关系不一致，排除。<br>故正确答案为A。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":73,"pid":"p4999a05dc1"},{"qid":"5919649","no":11,"type":"类比推理","module":"判断推理","stem":"<p>杞人忧天 之于 （    ） 相当于  （    ） 之于 自不量力</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"庸人自扰；螳臂当车"},{"k":"B","t":"局促不安；蜉蝣撼树"},{"k":"C","t":"叶公好龙；夜郎自大"},{"k":"D","t":"郑人买履；自以为是"}],"answer":"A","multi":false,"explanation":"<p>逐一代入选项。<br>A项：“杞人忧天”借指为不必要忧虑的事情而忧虑，“庸人自扰”指本来没有问题而自己瞎着急或自找麻烦，二者为近义关系；“螳臂当车”比喻不正确估计自己的力量，去做办不到的事情，必然招致失败，“自不量力”指不能正确估计自己的力量（多指做力不能及的事情），二者为近义关系。前后逻辑关系一致，当选。<br>B项：“杞人忧天”借指为不必要忧虑的事情而忧虑，“局促不安”的意思是拘谨不自然，形容举止拘束，心中不安，二者无明显逻辑关系；“蜉蝣撼树”比喻通过贬低他人来抬高自己，“自不量力”指不能正确估计自己的力量（多指做力不能及的事情），二者无明显逻辑关系。前后逻辑关系不一致，排除。<br>C项：“杞人忧天”借指为不必要忧虑的事情而忧虑，“叶公好龙”比喻说是爱好某事物，其实并不真爱好，二者无明显逻辑关系；“夜郎自大”指妄自尊大，“自不量力”指不能正确估计自己的力量（多指做力不能及的事情），二者为近义关系。前后逻辑关系不一致，排除。<br>D项：“杞人忧天”借指为不必要忧虑的事情而忧虑，“郑人买履”指照搬条文，不考虑客观实际的教条做法，二者无明显逻辑关系；“自以为是”指认为自己的看法和做法都正确，不接受别人的意见，“自不量力”指不能正确估计自己的力量（多指做力不能及的事情），二者无明显逻辑关系。前后逻辑关系不一致，排除。<br>故正确答案为A。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":74,"pid":"p4999a05dc1"},{"qid":"17900824","no":12,"type":"类比推理","module":"判断推理","stem":"<p>（    ） 之于 白蚁 相当于 岩羊 之于 （    ）</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"昆虫；山羊"},{"k":"B","t":"树木；雪豹"},{"k":"C","t":"蚂蚁；老鹰"},{"k":"D","t":"蚁后；羊群"}],"answer":"B","multi":false,"explanation":"<p>逐一代入选项。<br>A项：“白蚁”是一种“昆虫”，二者为种属关系；“岩羊”和“山羊”为并列关系。前后逻辑关系不一致，排除。<br>B项：“白蚁”啃食“树木”，二者为捕食者和被捕食者的对应关系；“雪豹”捕食“岩羊”，二者为捕食者和被捕食者的对应关系。前后逻辑关系一致，当选。<br>C项：“白蚁”属于等翅目昆虫，“蚂蚁”属于膜翅目昆虫，二者为并列关系；“老鹰”捕食“岩羊”，二者为捕食者和被捕食者的对应关系。前后逻辑关系不一致，排除。<br>D项：有的“蚁后”是“白蚁”，有的“蚁后”不是“白蚁”，有的“白蚁”是“蚁后”，有的“白蚁”不是“蚁后”，二者为交叉关系；“岩羊”是“羊群”的组成部分，二者为组成关系。前后逻辑关系不一致，排除。<br>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":75,"pid":"p4999a05dc1"},{"qid":"17900822","no":13,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性。</p><p><img src=\"assets/img/timu/1906d9e0e657868.png\" class=\"fig\" style=\"width:600px;height:287px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"C","multi":false,"explanation":"<p>元素组成不同，优先考虑属性规律。观察发现，题干已知图形均为规整的字母，考虑对称性。题干第一、三、五幅图均为只轴对称的图形，第二、四幅图均为只中心对称的图形，因此问号处应选择一个只中心对称的图形，只有C项符合。<br>故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":76,"pid":"p4999a05dc1"},{"qid":"17900827","no":14,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性。</p><p><img src=\"assets/img/timu/1906d9ec95fbce5.png\" class=\"fig\" style=\"width:600px;height:283px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"D","multi":false,"explanation":"<p>元素组成不同，优先考虑数量规律。观察发现，元素<img src=\"assets/img/timu/1906d9f67862d57.png\" class=\"fig\" style=\"width:52px;height:52px;\">的数量依次为1、2、3、4、5、？，故问号处该元素的数量应为6，排除A项。再次观察发现，每幅图中的四角星在该图中的位置分别为上、右、下、左、上、？，因此问号处图形中四角星在该图中的位置应为右，只有D项符合。</p><p>故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":77,"pid":"p4999a05dc1"},{"qid":"17900833","no":15,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性。</p><p><img src=\"assets/img/timu/1906d9f40967742.png\" class=\"fig\" style=\"width:600px;height:272px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"D","multi":false,"explanation":"<p>元素组成不同，且无明显属性规律，考虑数量规律。观察发现，图形中出现类似天平的示意图，将两端小元素转化为质量关系，可得：<img src=\"assets/img/timu/1906da08fc71b1d.png\" class=\"fig\" style=\"width:32px;height:39px;\">&gt;<img src=\"assets/img/timu/1906da1d1d3caed.jpg\" class=\"fig\" style=\"width:41px;height:41px;\">，<img src=\"assets/img/timu/1906da1feef1dbc.jpg\" class=\"fig\" style=\"width:38px;height:42px;\">&gt;<img src=\"assets/img/timu/1906da21a47192e.jpg\" class=\"fig\" style=\"width:35px;height:35px;\">，<img src=\"assets/img/timu/1906da23ac2a07c.jpg\" class=\"fig\" style=\"width:39px;height:39px;\">&gt;<img src=\"assets/img/timu/1906da1feef1dbc.jpg\" class=\"fig\" style=\"width:38px;height:42px;\">，<img src=\"assets/img/timu/1906da21a47192e.jpg\" class=\"fig\" style=\"width:35px;height:35px;\">&gt;<img src=\"assets/img/timu/1906da08fc71b1d.png\" class=\"fig\" style=\"width:32px;height:39px;\">，<img src=\"assets/img/timu/1906da23ac2a07c.jpg\" class=\"fig\" style=\"width:39px;height:39px;\">&gt;<img src=\"assets/img/timu/1906da1d1d3caed.jpg\" class=\"fig\" style=\"width:41px;height:41px;\">。串联后可得：<img src=\"assets/img/timu/1906da370ea3fe5.jpg\" class=\"fig\" style=\"width:39px;height:39px;\">&gt;<img src=\"assets/img/timu/1906da38a20911c.jpg\" class=\"fig\" style=\"width:38px;height:42px;\">&gt;<img src=\"assets/img/timu/1906da398c9b82d.jpg\" class=\"fig\" style=\"width:35px;height:35px;\">&gt;<img src=\"assets/img/timu/1906da3ae65ac1f.png\" class=\"fig\" style=\"width:32px;height:39px;\">&gt;<img src=\"assets/img/timu/1906da3be032a53.jpg\" class=\"fig\" style=\"width:41px;height:41px;\">。故问号处图形中两个小元素也应符合此规律，排除B、C两项。继续观察发现，题干图形中天平依次倾向于左侧、右侧、左侧、右侧、左侧、？，故问号处图形中的天平应倾向于右侧，只有D项符合。</p><p>故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":78,"pid":"p4999a05dc1"},{"qid":"16095253","no":16,"type":"图形推理","module":"判断推理","stem":"<p>请从四个选项中选出最恰当的一项填入问号处，使题干图形呈现一定的规律性。</p><p><img src=\"assets/img/timu/18d7c59e6718df3.png\" class=\"fig\" style=\"width:600px;height:285px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"B","multi":false,"explanation":"<p>元素组成基本相同，题干每幅图形都是由直线和小白圆组成，考虑功能元素的标记作用。观察发现，小白圆只标记1条线，且若把每幅图的最外面那条线当作第1条线，那么小白圆依次标记在第1条线、第2条线、第3条线、第4条线、第5条线上，故？处图形中的小白圆应只标记在第6条线上，只有B项符合。<br>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":79,"pid":"p4999a05dc1"},{"qid":"12304867","no":17,"type":"图形推理","module":"判断推理","stem":"<p>请从四个选项中选出最恰当的一项填入问号处，使题干图形呈现一定的规律性。</p><p><img src=\"assets/img/timu/18d7c0792910dd5.png\" class=\"fig\" style=\"width:400px;height:450px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"D","multi":false,"explanation":"<p>元素组成不同，优先考虑属性规律。观察发现，题干出现全直线、全曲线图形，可以考虑曲直性。九宫格优先看横行，第一行图形分别为有曲有直图形、全曲线图形、全直线图形；经验证，第二行符合此规律；第三行应用此规律，故“？”处图形应是全直线图形，排除B项；继续观察发现，题干图形出现明显封闭空间，考虑面数量，第一行图形面数量均为1，第二行图形面数量均为2，第三行前两幅图形面数量均为3，故“？”处图形面数量应为3，排除C项；对比A、D两项，A项图形部分数为2，D项图形部分数为1，题干图形部分数均为1，只有D项符合。<br>故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":80,"pid":"p4999a05dc1"},{"qid":"12334416","no":18,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性。</p><p><img src=\"assets/img/timu/1907ca70bb852f5.jpg\" class=\"fig\" style=\"width:634px;height:696px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"B","multi":false,"explanation":"<p>元素组成相同，优先考虑位置规律。九宫格优先横向看，第一行中，图一经过逆时针旋转<img src=\"assets/img/gongshi/formula-baa9dcf22db28066.png\" class=\"tex\">得到图二，图二经过上下翻转得到图三；第二行经验证，符合该规律；第三行应用规律，只有B项符合。</p><p>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":81,"pid":"p4999a05dc1"},{"qid":"16095267","no":19,"type":"图形推理","module":"判断推理","stem":"<p>下边四个图形中，只有一个是由上边的四个图形拼合（只能通过上、下、左、右平移）而成的，请把它找出来。</p><p><img src=\"assets/img/timu/18d7c0b29f384c2.jpg\" class=\"fig\" style=\"width:509px;height:321px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"B","multi":false,"explanation":"<p>本题考查平面拼合，可采用平行且等长相消的方式解题。消去平行且等长的线段后进行组合即可得到轮廓图，即为B项。平行且等长相消的方式如下图所示：</p><p><img src=\"assets/img/timu/18d7c11289e778d.png\" class=\"fig\" style=\"width:500px;height:324px;\"></p><p>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":82,"pid":"p4999a05dc1"},{"qid":"16095271","no":20,"type":"图形推理","module":"判断推理","stem":"<p>下边四个图形中，只有一个是由上边的四个图形拼合（只能通过上、下、左、右平移）而成的，请把它找出来。</p><p><img src=\"assets/img/timu/18d7c0ccc97c26e.jpg\" class=\"fig\" style=\"width:493px;height:308px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"A","multi":false,"explanation":"<p>本题考查平面拼合，可采用平行且等长相消的方式解题。消去平行且等长的线段后进行组合即可得到轮廓图，即为A项。平行且等长相消的方式如下图所示：</p><p><img src=\"assets/img/timu/18d7c0e498da9c1.jpg\" class=\"fig\" style=\"width:494px;height:311px;\"></p><p>故正确答案为A。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":83,"pid":"p4999a05dc1"},{"qid":"16095258","no":21,"type":"图形推理","module":"判断推理","stem":"<p>选项四个图形中，只有一个是由题干的四个图形拼合（只能通过上、下、左、右平移）而成的，请把它找出来。</p><p><img src=\"assets/img/timu/1907112cc903318.png\" class=\"fig\" style=\"width:500px;height:326px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"B","multi":false,"explanation":"<p>本题考查平面拼合，可采用平行且等长相消的方法解题。消去平行且等长的线段后进行组合可得到轮廓图，即为B项。平行且等长相消的方式如下图所示。</p><p><img src=\"assets/img/timu/19071140e34d64c.png\" class=\"fig\" style=\"width:527px;height:337px;\"></p><p>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":84,"pid":"p4999a05dc1"},{"qid":"16095266","no":22,"type":"图形推理","module":"判断推理","stem":"<p>下边四个图形中，只有一个是由上边的四个图形拼合（只能通过上、下、左、右平移）而成的，请把它找出来。</p><p><img src=\"assets/img/timu/18d7c0ad6dd1424.png\" class=\"fig\" style=\"width:500px;height:314px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"B","multi":false,"explanation":"<p>本题考查平面拼合，消去弯曲程度一致且等长的曲线后进行拼合，即可得到轮廓图，即为B项。具体拼合方式如下图所示：</p><p><img src=\"assets/img/timu/18d7d8384083be0.png\" class=\"fig\" style=\"width:507px;height:266px;\"></p><p>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":85,"pid":"p4999a05dc1"},{"qid":"17900828","no":23,"type":"图形推理","module":"判断推理","stem":"<p>左边图形恰好可以分割为右边的某三个图形（可以平移、旋转，但不能翻转），请找出不属于分割所得的图形。</p><p><img src=\"assets/img/timu/1906d9ebe2a738e.png\" class=\"fig\" style=\"width:600px;height:156px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"B","multi":false,"explanation":"<p>本题考查平面拼合，可采用平行且等长相消的方式解题。A项、D项与旋转后的C项消去平行且等长的线段后进行组合，可得到题干轮廓图，平行且等长相消的方式如下图所示。</p><p><img src=\"assets/img/timu/1906d9fe95c6450.png\" class=\"fig\" style=\"width:154px;height:156px;\"></p><p>本题为选非题，故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":86,"pid":"p4999a05dc1"},{"qid":"17900846","no":24,"type":"图形推理","module":"判断推理","stem":"<p>左边给定的是六面体的外表面展开图，右边哪一项能由它折叠而成？</p><p><img src=\"assets/img/timu/1906da0f988d508.png\" class=\"fig\" style=\"width:600px;height:154px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"D","multi":false,"explanation":"<p>本题为空间重构题。将题干展开图中的面依次标上序号，如下图所示，逐一分析选项。</p><p><img src=\"assets/img/timu/1906da17bf95d03.png\" class=\"fig\" style=\"width:600px;height:149px;\"></p><p>A项：选项由面f、面g和面i构成，在题干展开图和选项中，以面g中挨着两个白色小圆的边为起始边，分别对面g顺时针画边，题干展开图中边2同时挨着面f中的白色小圆和黑色小圆，而选项中边2只挨着一个黑色小圆，选项与题干展开图不一致，排除。</p><p><img src=\"assets/img/timu/1906da1a0c1760d.png\" class=\"fig\" style=\"width:600px;height:152px;\"></p><p>B项：选项由面f、面g和面i构成，且由题干展开图中面f内小圆和面g内小圆的相对位置可知，选项中的顶面为面i。在题干展开图和选项中，以面i靠近白色小圆的边为起始边，分别对面i顺时针画边，题干展开图中边1挨着面h，而选项中边1不挨着面h，选项与题干展开图不一致，排除。</p><p><img src=\"assets/img/timu/1906da1c98fd922.png\" class=\"fig\" style=\"width:600px;height:157px;\"></p><p>C项：选项一定有面g，面g和面k为相对面，不能同时出现在立体图中，故选项由面e、面g和面h构成。题干展开图中面e内的小弓形挨着面f，而选项中面e内的小弓形挨着面h，选项与题干展开图不一致，排除。</p><p>D项：选项由面e、面h和面k构成，选项与题干展开图一致，当选。</p><p>故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":87,"pid":"p4999a05dc1"},{"qid":"12304871","no":25,"type":"图形推理","module":"判断推理","stem":"<p>下列是四个正方体的外表面展开图，其中哪个展开图还原成正方体后，存在有同一个公共顶点的三个面，且其上的数字之和为8？</p><p><img src=\"assets/img/timu/18d7c088b740b2d.png\" class=\"fig\" style=\"width:600px;height:198px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"B","multi":false,"explanation":"<p>观察发现，选项展开图的六个面中出现的数字均分别为1-6，若想在1-6中选出3个数字相加刚好是8，只有两种情况：①面1、面2和面5两两相邻；②面1、面3和面4两两相邻。逐一分析选项：</p><p>A项：面1和面4为相对面，故面1、面3和面4无法两两相邻；面2和面5为相对面，故面1、面2和面5无法两两相邻。两种情况均不符合要求，排除；</p><p>B项：面1、面2和面5两两相邻，存在同一个公共顶点（如下图所示），且其上的数字之和为8，满足要求，当选；</p><p><img src=\"assets/img/timu/18d7c09e1466688.png\" class=\"fig\" style=\"width:543px;height:188px;\"></p><p>C项：面3和面4为相对面，故面1、面3和面4无法两两相邻；面1和面2为相对面，故面1、面2和面5无法两两相邻。两种情况均不符合要求，排除；</p><p>D项：面3和面4为相对面，故面1、面3和面4无法两两相邻；面1和面5为相对面，故面1、面2和面5无法两两相邻。两种情况均不符合要求，排除。</p><p>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":88,"pid":"p4999a05dc1"},{"qid":"16095252","no":26,"type":"图形推理","module":"判断推理","stem":"<p>将下列三棱锥的展开图还原成三棱锥后，有一个与其他三个不一样，请把它找出来。</p><p><img src=\"assets/img/timu/18d7c08d407374c.png\" class=\"fig\" style=\"width:600px;height:201px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"D","multi":false,"explanation":"<p>本题考查空间重构。在选项展开图中，以只有两个扇形的面上的空白顶点作为起始点，进行顺时针画边，如下图所示，逐一分析选项。</p><p><img src=\"assets/img/timu/18d7c09405a311e.png\" class=\"fig\" style=\"width:600px;height:202px;\"></p><p>A项：选项中右边两个面为图案一样的面，边1不挨着其中任意一个面中的小扇形。</p><p>B项：选项中最左边和最右边两个面为图案一样的面，边1不挨着其中任意一个面中的小扇形。</p><p>C项：选项中最上边和左下边为图案一样的面，边1不挨着其中任意一个面中的小扇形。</p><p>D项：选项中最上边和右下边为图案一样的面，边1与最上边面中的小扇形有公共点。</p><p>本题为选非题，故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":89,"pid":"p4999a05dc1"},{"qid":"12304861","no":27,"type":"图形推理","module":"判断推理","stem":"<p>左图是由14个黑白小正方体组成的立体图形，右面四个选项中有一项不是该立体图形的视图，请把它找出来。</p><p><img src=\"assets/img/timu/18d7c066e7e7c36.png\" class=\"fig\" style=\"width:600px;height:161px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"A","multi":false,"explanation":"<p>本题考查三视图。</p><p>A项：该项不是该立体图形的视图，若为轮廓一致的主视图，应如下图所示，当选；</p><p><img src=\"assets/img/timu/18d7c0d8133fbd3.png\" class=\"fig\" style=\"width:180px;height:180px;\"></p><p>B项：从上往下可以看到，为俯视图，排除；</p><p>C项：从左往右可以看到，为左视图，排除；</p><p>D项：从后往前可以看到，为后视图，排除。</p><p>本题为选非题，故正确答案为A。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":90,"pid":"p4999a05dc1"},{"qid":"12304865","no":28,"type":"逻辑判断","module":"判断推理","stem":"<p>一只鸟除非两翼健壮并以共同的力量来推动身体，否则它不能飞向天空。根据以上陈述，可以推出以下哪些结论？<br>①一只鸟如果两翼健壮并以共同的力量来推动身体，那么它能够飞向天空<br>②一只鸟如果能够飞向天空，那么它两翼健壮并以共同的力量来推动身体<br>③一只鸟若两翼不健壮或不能以共同的力量来推动身体，那么它不能飞向天空<br>④一只鸟如果不能飞向天空，那么它两翼不健壮或不能以共同力量来推动身体</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"①②"},{"k":"B","t":"②③"},{"k":"C","t":"③④"},{"k":"D","t":"②④"}],"answer":"B","multi":false,"explanation":"<p>第一步：翻译题干。</p><p>题干翻译为：飞向天空<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">两翼健壮 且 以共同的力量来推动身体。</p><p>第二步：逐一分析选项。</p><p>①翻译为：两翼健壮 且 以共同的力量来推动身体<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">飞向天空，是对题干逻辑关系的肯后，肯后无必然结论，无法推出；</p><p>②翻译为：飞向天空<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">两翼健壮 且 以共同的力量来推动身体，是对题干逻辑关系的肯前，肯前必肯后，可以推出；</p><p>③翻译为：<img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">两翼健壮 或 <img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">以共同的力量来推动身体<img src=\"assets/img/gongshi/formula-692b70564d8c5bce.png\" class=\"tex\">飞向天空，是对题干逻辑关系的否后，否后必否前，可以推出；</p><p>④翻译为：<img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">飞向天空<img src=\"assets/img/gongshi/formula-692b70564d8c5bce.png\" class=\"tex\">两翼健壮 或 <img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">以共同的力量来推动身体，是对题干逻辑关系的否前，否前无必然结论，无法推出。</p><p>综上所述，②③可以推出，对应B项。</p><p>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":91,"pid":"p4999a05dc1"},{"qid":"10975246","no":29,"type":"逻辑判断","module":"判断推理","stem":"<p>某学校模拟派出骨干教师指导山区教师人才培训项目。甲、乙、丙、丁四位教师积极报名参加，学校决定从他们四人中挑选出若干人员，考虑到各方面情况，派出人员要符合以下要求：<br>①只有乙参加，甲才参加；<br>②如果丙参加，那么丁不参加；<br>③如果乙参加，那么丙也参加。<br>根据以上信息，以下哪项不可能为真？</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"甲和丙参加"},{"k":"B","t":"丁参加，乙不参加"},{"k":"C","t":"甲和丁参加"},{"k":"D","t":"甲参加，丁不参加"}],"answer":"C","multi":false,"explanation":"<p>第一步：翻译题干条件。</p><p>（1）甲<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">乙；</p><p>（2）丙<img src=\"assets/img/gongshi/formula-692b70564d8c5bce.png\" class=\"tex\">丁；</p><p>（3）乙<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">丙。</p><p>将（1）（2）（3）串联可得：（4）甲<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">乙<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">丙<img src=\"assets/img/gongshi/formula-692b70564d8c5bce.png\" class=\"tex\">丁。</p><p>第二步：根据题干条件进行推理。</p><p>根据条件（4）可知，甲参加时丁一定不参加，因此C项不可能为真。</p><p>本题为选非题，故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":92,"pid":"p4999a05dc1"},{"qid":"17900831","no":30,"type":"逻辑判断","module":"判断推理","stem":"<p>人体总能量代谢主要由静息代谢水平和活动能量代谢水平决定。静息代谢指人体在静止状态下消耗的能量，活动能量代谢指人们在日常活动或运动状态下所消耗的能量。近年来，M市成年人的总能量代谢水平呈现下降趋势。有人据此认为，M市成年人的静息代谢水平近年来也呈下降趋势。<br>以下哪项如果为真，最能支持上述人士的观点？</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"近年来，M市成年人逐渐重视饮食结构均衡，减少各种高能量食物摄入"},{"k":"B","t":"近年来，M市成年人开始重视身体锻炼，平均每天的锻炼时长有所增加"},{"k":"C","t":"近年来，M市成年人劳动强度普遍降低，许多人不再从事高强度体力劳动"},{"k":"D","t":"近年来，M市成年人总能量代谢水平下降幅度比活动能量代谢水平下降幅度小"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：M市成年人的静息代谢水平近年来也呈下降趋势。<br>论据：人体总能量代谢主要由静息代谢水平和活动能量代谢水平决定。近年来，M市成年人的总能量代谢水平呈现下降趋势。<br>本题论点说的是“静息代谢水平呈下降趋势”，即部分下降，而论据说的是“总能量代谢水平呈下降趋势”，即整体下降，加强优先考虑补充论据，即说明另一部分（活动能量代谢水平）的情况。<br>第二步：逐一分析选项。<br>A项：该项指出M市的成年人减少高能量食物摄入，而论点说的是静息代谢水平呈下降趋势，话题不一致，无法加强，排除。<br>B项：该项指出M市的成年人平均每天的锻炼时长有所增加，说明活动能量代谢水平在上升，结合论据中总能量代谢水平下降，可以推出静息代谢水平下降，补充论据，可以加强，当选。<br>C项：该项指出M市的成年人劳动强度降低，说明活动能量代谢水平在下降，结合论据中总能量代谢水平下降，无法推出静息代谢水平一定下降了（静息代谢水平也可能上升了，但上升幅度小于活动能量代谢水平的下降幅度），为不明确项，无法加强，排除。<br>D项：该项指出M市成年人总能量代谢水平下降幅度比活动能量代谢水平下降幅度小，当整体下降的幅度小于一个因素下降的幅度时，另一个因素的变化情况无法确定，为不明确项，无法加强，排除。<br>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":93,"pid":"p4999a05dc1"},{"qid":"10975252","no":31,"type":"逻辑判断","module":"判断推理","stem":"<p>某学校举办田径运动会，所有参加800米跑的运动员都参加了100米跑，所有参加100米跑的运动员都参加了跳高，有些参加跳远的运动员参加了投掷链球，所有参加跳远的运动员都没有参加跳高。<br>根据以上陈述，不能推出以下哪项？</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"所有参加800米跑的运动员都参加了跳高"},{"k":"B","t":"所有参加投掷链球的运动员都没有参加跳高"},{"k":"C","t":"所有参加跳远的运动员都没有参加100米跑"},{"k":"D","t":"有些参加800米跑的运动员参加了跳远"}],"answer":"D","multi":false,"explanation":"<p>第一步：翻译题干。</p><p>（1）参加800米跑<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">参加100米跑；</p><p>（2）参加100米跑<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">参加跳高；</p><p>（3）有的参加跳远<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">参加投掷链球；</p><p>（4）参加跳远<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">参加跳高。</p><p>将（1）（2）（4）串联可得：（5）参加800米跑<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">参加100米跑<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">参加跳高<img src=\"assets/img/gongshi/formula-692b70564d8c5bce.png\" class=\"tex\">参加跳远。</p><p>第二步：逐一分析选项。</p><p>A项：翻译为“参加800米跑<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">参加跳高”，“参加800米跑”是对条件（5）的肯前，肯前必肯后，可以推出，排除。</p><p>B项：翻译为“参加投掷链球<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">参加跳高”，将条件（3）换位可得“有的参加投掷链球<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">参加跳远”，与条件（4）串联可得“有的参加投掷链球<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">参加跳远<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">参加跳高”，“有的”无法推出“所有”，即“所有参加投掷链球的运动员都没有参加跳高”可能为真，也可能为假，保留。</p><p>C项：翻译为“参加跳远<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-7ab67fb9ad7cdd2c.png\" class=\"tex\">参加100米跑”，“参加跳远”是对条件（5）的否后，否后必否前，可以推出，排除。</p><p>D项：翻译为“有的参加800米跑<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">参加跳远”，与条件（5）矛盾，无法推出，保留。</p><p>对比B、D两项，B项可能为真，D项一定为假，择优选D项。</p><p>本题为选非题，故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":94,"pid":"p4999a05dc1"},{"qid":"12304863","no":32,"type":"逻辑判断","module":"判断推理","stem":"<p>某车间共有18人，他们分别来自山东、江苏、浙江、安徽和福建5省。在18人中，每省至少有1人，且来自各省的人数均不相同。已知：<br>来自山东和江苏的共有5人；<br>来自江苏和浙江的共有6人；<br>来自浙江和福建的共有7人；<br>根据上述信息，可以推出以下哪项？</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"18人中来自山东的有1人"},{"k":"B","t":"18人中来自浙江的有2人"},{"k":"C","t":"18人中来自福建的有5人"},{"k":"D","t":"18人中来自安徽的有6人"}],"answer":"D","multi":false,"explanation":"<p>第一步：分析题干条件。<br>（1）山东+江苏=5；<br>（2）江苏+浙江=6；<br>（3）浙江+福建=7；<br>（4）山东+江苏+浙江+安徽+福建=18；<br>（5）在18人中，每省至少有1人，且来自各省的人数均不相同。<br>第二步：根据题干条件进行推理。<br>将条件（1）和（3）相加可得条件（6）：山东+江苏+浙江+福建=12。<br>再用条件（4）与条件（6）相减可得：安徽=6，对应D项。<br>故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":95,"pid":"p4999a05dc1"},{"qid":"16095272","no":33,"type":"类比推理","module":"判断推理","stem":"<p>甲：小明十岁就能用英语与英国人流利对话，语言天赋真是出类拔萃。<br>乙：小明跟着父母在英国住了两年，能流利对话不足为奇。<br>以下哪项与题干对话方式最为相似？</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"<p>甲：这款热水器的价格比市面上常见的热水器高出一倍，太不划算了</p><p>乙：这款产品用的是航天级别的材料，在同材质热水器中性价比很高</p>"},{"k":"B","t":"<p>甲：小李以前容易冲动，进入职场一年后稳重多了</p><p>乙：小李承担了单位大量重要工作，变得稳重一点理所当然</p>"},{"k":"C","t":"<p>甲：小张的数学一直很好，进入高中后，物理、化学等科目的学习很轻松</p><p>乙：数学强调科学思维，掌握科学思维的人学习物理、化学当然没有难度</p>"},{"k":"D","t":"<p>甲：小刘在过去的一年中连续犯下三起盗窃案，真是无可救药</p><p>乙：人非圣贤，孰能无过，相信在经过改造之后他会洗心革面</p>"}],"answer":"A","multi":false,"explanation":"<p>第一步：分析题干逻辑关系。<br>甲根据“小明十岁就能用英语与英国人流利对话”的现象，得出“小明的语言天赋出类拔萃”的结论，而乙提出“小明跟着父母在英国住了两年”的理由来解释现象，用“能流利对话不足为奇”来否定甲的结论。<br>第二步：逐一分析选项。<br>A项：甲根据“这款热水器的价格比市面上常见的热水器高出一倍”的现象，得出“这款热水器不划算”的结论，乙提出“这款产品用的是航天级别的材料”的理由来解释现象，用“在同材质热水器中性价比很高”来否定甲的结论，与题干对话方式一致，当选；<br>B项：甲提出“小李以前容易冲动，进入职场一年后稳重多了”的结论，乙提出“小李承担了单位大量重要工作，变得稳重一点理所当然”的理由来解释甲的结论，与题干对话方式不一致，排除；<br>C项：甲提出“小张的数学一直很好，进入高中后，物理、化学等科目的学习很轻松”的结论，乙提出“数学强调科学思维，掌握科学思维的人学习物理、化学当然没有难度”的理由来解释甲的结论，与题干对话方式不一致，排除；<br>D项：甲根据“小刘在过去的一年中连续犯下三起盗窃案”的现象，得出“小刘无可救药”的结论，乙得出的观点“相信在经过改造之后小刘会洗心革面”是一种预测，而非事实，用预测否定甲的结论，与题干对话方式不一致，排除。<br>故正确答案为A。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":96,"pid":"p4999a05dc1"},{"qid":"12304873","no":34,"type":"逻辑判断","module":"判断推理","stem":"<p>卖早点、修家电、配钥匙·····老百姓家门口的社区商业，是以社区居民为服务对象、服务半径为步行15分钟左右范围内的商业形态。近年来，许多城市大力推进社区商业建设，以更好地满足居民的消费需求。不过，也有专家担忧，家门口商业服务的完善，在给居民生活带来便利的同时可能也会使快递业逐步萎缩。<br>以下哪项如果为真，最能缓解上述专家的担忧？</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"为了方便居民，很多城市推进社区商业建设时，都将快递驿站作为社区商业的重要组成部分"},{"k":"B","t":"社区商业主要提供汽车保养、幼儿托管等服务类业态，社区购物在居民整体购物消费中占比很少"},{"k":"C","t":"社会经济发展必然包含新旧行业的更迭，社区商业作为新的消费增长点，吸纳了大量传统行业的劳动者就业"},{"k":"D","t":"许多大型商超组建了自己的配送车队，可为周边5公里范围内居民提供商品一小时送达服务"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：家门口商业服务的完善，在给居民生活带来便利的同时可能也会使快递业逐步萎缩。<br>论据：无。<br>本题提问为“缓解上述专家的担忧”即削弱上述专家的担忧，且只有论点没有论据，削弱优先考虑削弱论点，即说明家门口商业服务的完善不会使快递业逐步萎缩。<br>第二步：逐一分析选项。<br>A项：该项说的是很多城市将快递驿站作为社区商业的重要组成部分，说明家门口商业服务完善后快递驿站依然很重要，可能不会使快递业逐步萎缩，削弱论点，可以削弱，保留；<br>B项：该项说的是社区购物在居民整体购物消费中占比很少，说明社区商业的建设对居民原有的购物方式影响不大，也就不会使快递业逐步萎缩，削弱论点，可以削弱，保留；<br>C项：该项说的是社区商业吸纳了大量传统行业的劳动者就业，是在说社区商业促进了就业，并未提及对快递业的影响，为无关项，无法削弱，排除；<br>D项：该项说的是许多大型商超提供限时配送服务，大型商超不属于社区商业，提供的配送服务不属于快递业，为无关项，无法削弱，排除。<br>对比A、B两项，A项说的是快递驿站的重要性，但是快递驿站重要并不能明确说明快递业的情况，而B项明确说明了对居民原有的购物方式影响不大，即不会对快递业有影响，综合对比，B项比A项更加明确，因此优选B项。<br>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":97,"pid":"p4999a05dc1"},{"qid":"12304874","no":35,"type":"逻辑判断","module":"判断推理","stem":"<p>一项研究发现，成年小白鼠去除一个关键生物钟基因后，昼夜节律完全消失，虽然生活质量有所下降，但寿命并未受到显著影响，心血管健康状况甚至有所改善。据此，研究人员推断昼夜节律缺失对健康的危害可能没有我们想象得那么大。<br>回答以下哪个问题最有助于评价上述研究人员所做出的推断？</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"成年小白鼠去除生物钟基因后出现的心血管情况改善是否会延长小白鼠的寿命"},{"k":"B","t":"成年小白鼠去除生物钟基因之后的休息时间是否与未去除之前的休息时间相同"},{"k":"C","t":"成年小白鼠去除生物钟基因后的寿命和心血管健康状况能否代表整体健康状况"},{"k":"D","t":"成年小白鼠去除生物钟基因之后的生活质量是否会影响小白鼠的整体健康状况"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：昼夜节律缺失对健康的危害可能没有我们想象得那么大。<br>论据：成年小白鼠去除一个关键生物钟基因后，昼夜节律完全消失，虽然生活质量有所下降，但寿命并未受到显著影响，心血管健康状况甚至有所改善。<br>本题论点讨论的是“昼夜节律缺失”和“整体健康状况”之间的关系，论据讨论的是“昼夜节律缺失”和“寿命、心血管健康状况”之间的关系，二者话题不一致，且提问方式为“最有助于”评价研究人员的推断，可以考虑搭桥，即建立“寿命、心血管健康状况”与“整体健康状况”之间的关系。<br>第二步：逐一分析选项。<br>A项：该项讨论的是“心血管健康状况”与“寿命”之间的关系，而不是“寿命、心血管健康状况”与“整体健康状况”之间的关系，即使心血管状况改善能够延长寿命，仍无法得知整体健康状况如何，无助于评价研究人员的推断，排除；<br>B项：该项讨论的是“去除生物钟基因前后的休息时间”，论点说的是“昼夜节律缺失”和“整体健康状况”的关系，话题不一致，无助于评价研究人员的推断，排除；<br>C项：该项讨论的是“寿命、心血管健康状况”与“整体健康状况”之间的关系，如果寿命和心血管健康状况能代表整体健康状况，则说明研究人员的推断成立，有助于评价研究人员的推断，当选；<br>D项：该项讨论的是“生活质量”与“整体健康状况”之间的关系，但研究人员是通过“寿命”与“心血管健康状况”得出的论点，不如C项更有助于评价研究人员的推断，排除。<br>故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":98,"pid":"p4999a05dc1"},{"qid":"17900825","no":36,"type":"定义判断","module":"判断推理","stem":"<p>涉农执法：指有关行政执法部门对涉及“三农”的生产经营活动的各种问题开展的执法活动。<br>下列不属于涉农执法的是：</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"某食品工厂生产的饮料经抽样检测，有多项不合格，执法人员对当事人做出没收违法所得并罚款的行政处罚"},{"k":"B","t":"执法大队经调查取证，查实辖区内的某农贸经营部销售假农药，依法责令其召回已售出的该农药，并对当事人做出行政处罚"},{"k":"C","t":"在对某乡村猪肉交易市场进行执法检查时，发现，郑某售卖的猪肉没有检验标识，依法对他进行了处罚"},{"k":"D","t":"种瓜大户老刘为了扩大销路，在瓜园门口挂上了“香瓜开园啦”的条幅。邻居张律师说，他未经批准打广告，不合法，建议他撤下横幅"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“行政执法部门”“涉及‘三农’的生产经营活动的各种问题”。<br>第二步：逐一分析选项。<br>A项：某食品工厂生产的饮料经检测不合格，执法人员对当事人做出行政处罚，符合“行政执法部门”“涉及‘三农’的生产经营活动的各种问题”，符合定义，排除。<br>B项：某农贸经营部销售假农药，执法大队责令其召回并对当事人做出行政处罚，符合“行政执法部门”“涉及‘三农’的生产经营活动的各种问题”，符合定义，排除。<br>C项：在执法检查中，因郑某售卖的猪肉没有检验标识而对他进行了处罚，符合“行政执法部门”“涉及‘三农’的生产经营活动的各种问题”，符合定义，排除。<br>D项：种瓜大户老刘未经批准在瓜园门口打广告，邻居张律师认为这种行为不合法，建议他撤下横幅，张律师不是行政执法部门的人员，不符合“行政执法部门”，不符合定义，当选。<br>本题为选非题，故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":99,"pid":"p4999a05dc1"},{"qid":"10975254","no":37,"type":"定义判断","module":"判断推理","stem":"<p>数字游民：指工作时间不受限制，地域可以自主选择，利用网络数字手段完成本职工作的从业人员。<br>下列属于数字游民的是：</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"小雷辞职后游走在不同的城市，白天在市区游玩特色街区，晚上到热闹的广场跟着市民一起跳舞，随时随地向天南地北的粉丝直播，月收入比以前多得多"},{"k":"B","t":"康女士居住在很远的小区，每天通勤时间差不多需要三四个小时，工作十分辛苦。最近，她的居家办公申请得到了批准，不用天天去公司打卡了"},{"k":"C","t":"黄先生年初被公司派驻到某山区工作，闲暇之余利用微信公众号帮助当地乡亲销售土特产，并通过网络众筹建起了雪乡旅舍，有时亲自担任导游。默默无闻的小山村很快变成了远近闻名的旅游村"},{"k":"D","t":"潮玩设计师周先生到新公司后，再也不担心迟到早退。昨天也许还是短裤、T恤和凉鞋，明天就换成了密不透风的户外运动装。他要做的只是每天晚上将自己的灵感、新想法报告给部门主管"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“工作时间不受限制”、“地域可以自主选择”、“利用网络数字手段完成本职工作”。<br>第二步：逐一分析选项。<br>A项：小雷作为自媒体从业者，游走在不同城市，符合“地域可以自主选择”，随时随地向粉丝直播，说明其工作并不受时间的限制，且利用互联网完成工作，符合“工作时间不受限制”、“利用网络数字手段完成本职工作”，符合定义，当选。<br>B项：康女士因通勤时间很长申请了居家办公，说明其工作地点虽然是家里但还是受公司管理，工作时间受到限制，不符合“工作时间不受限制”，不符合定义，排除。<br>C项：黄先生被公司派驻到某山区工作，说明其工作地点比较固定，不符合“地域可以自主选择”，不符合定义，排除。<br>D项：周先生的新工作不需要考虑迟到早退，但仍需要每天晚上汇报工作，说明其工作时间仍受到一定的限制，不符合“工作时间不受限制”，同时，未明确体现周先生可自由选择办公地点，不符合“地域可以自主选择”，不符合定义，排除。<br>故正确答案为A。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":100,"pid":"p4999a05dc1"},{"qid":"10975256","no":38,"type":"定义判断","module":"判断推理","stem":"<p>代际责任：指在不超出自身能力的前提下，相邻两代人的一方向另一方主动提供经济帮扶、生活照顾、健康保障、精神抚慰等各种支持的行为。<br>下列不属于代际责任的是：</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"苏女士把父母接到身边后，忙乎了一个多月，带着父母熟悉小区健身器材，到社区老年活动中心打牌下棋，在公园找人聊天，终于帮他们重新找到了“组织”"},{"k":"B","t":"邵先生和妻子一直在城里忙于打拼，女儿正在读小学。每到寒暑假，邵先生的父母都会专程赶到城里，把孙女接回农村老家痛痛快快地玩上整个假期"},{"k":"C","t":"罗奶奶像无数为孩子婚事发愁的长辈一样，每到周末就去附近公园的相亲角浏览展板上的照片、简历，觉得合适的就记下基本情况、电话号码。虽然快三十岁的孙女根本不着急，她却一直乐此不疲"},{"k":"D","t":"毛先生喜欢第一时间把遇到的趣事分享到家族微信群，却很少得到期待的回应，一怒之下退了群。后来，儿子又把他请回，还邀约了几位有同样爱好的长辈，群里逐渐热闹起来，他也时不时点赞或评论几句"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“不超出自身能力的前提下”、“相邻两代人”、“一方向另一方主动提供经济帮扶、生活照顾、健康保障、精神抚慰等各种支持”。<br>第二步：逐一分析选项。<br>A项：苏女士将把父母接到身边，且主动协助他们适应环境、找到“组织”，符合“相邻两代人”、“一方向另一方主动提供经济帮扶、生活照顾、健康保障、精神抚慰等各种支持”，符合定义，排除。<br>B项：邵先生的父母会在寒暑假时专程把孙女接回农村老家，这减轻了忙于工作的邵先生夫妇的负担，符合“相邻两代人”、“一方向另一方主动提供经济帮扶、生活照顾、健康保障、精神抚慰等各种支持”，符合定义，排除。<br>C项：罗奶奶乐此不疲地去相亲角浏览照片、简历以帮助孙女完成婚事，但这属于祖孙之间的支持，不符合“相邻两代人”，不符合定义，当选。<br>D项：毛先生因不能得到期待的回应而生气退群，儿子请回他，且邀约了几位有同样爱好的长辈，使父亲情绪好转，符合“相邻两代人”、“一方向另一方主动提供经济帮扶、生活照顾、健康保障、精神抚慰等各种支持”，符合定义，排除。<br>本题为选非题，故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":101,"pid":"p4999a05dc1"},{"qid":"17900844","no":39,"type":"定义判断","module":"判断推理","stem":"<p>滑动门时刻：指双方交往过程中，当一方发出寻求理解和支持的信号时，对方及时予以积极回应，从而进一步提高双方关系质量的关键时机。<br>下列属于滑动门时刻的是：</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"小袁：“今天天气太好了，前天有个朋友说江边的风景很漂亮，花儿也开得很灿烂。”小康：“天气确实不错，要不咱们现在就去？”"},{"k":"B","t":"妈妈躺在床上看手机，儿子走过来，发现妈妈正在看桂林的视频，就说：“哇，桂林真漂亮啊！”妈妈马上说：“这不是我们前年一起去时拍的吗？”"},{"k":"C","t":"弟弟：“每次周末都宅在家里，除了刷手机还是刷手机，无聊死了！”哥哥：“那你想干嘛？天天上班本来就很累，周末待在家就是最好的休息。”"},{"k":"D","t":"余老外出旅游回来后，一到家就兴冲冲地向女儿展示手机里的风景照。正在电脑上忙乎的女儿抬起头，瞅了一眼：“好好好，这些照片拍得太有水平了！”"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“双方交往过程中”、“当一方发出寻求理解和支持的信号时”、“对方及时予以积极回应”。<br>第二步：逐一分析选项。<br>A项：小袁说今天天气好、江边风景漂亮，小康回应天气确实不错，并提议两人一同前往，说明小康对小袁的话做出了积极回应，符合“双方交往过程中”、“当一方发出寻求理解和支持的信号时”、“对方及时予以积极回应”，符合定义，当选。<br>B项：儿子说视频中的桂林很漂亮，妈妈通过反问的语气表示这是他们前年一起去时拍的，说明妈妈并没有对儿子的话给予积极回应，不符合“当一方发出寻求理解和支持的信号时”、“对方及时予以积极回应”，不符合定义，排除。<br>C项：弟弟抱怨周末宅在家里刷手机很无聊，哥哥通过反问的语气表示周末待在家就是最好的休息，说明哥哥并没有对弟弟的话给予积极回应，不符合“当一方发出寻求理解和支持的信号时”、“对方及时予以积极回应”，不符合定义，排除。<br>D项：余老兴冲冲地向女儿展示旅游时拍的风景照，正在电脑上忙乎的女儿只是抬起头，瞅了一眼，举动略显敷衍，说明她并没有对爸爸的行为给予积极回应，不符合“当一方发出寻求理解和支持的信号时”、“对方及时予以积极回应”，不符合定义，排除。<br>故正确答案为A。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":102,"pid":"p4999a05dc1"},{"qid":"17900802","no":40,"type":"定义判断","module":"判断推理","stem":"<p>社会纠偏：指由公众主导，不排除政府相关部门或社会团体参与，有效化解各种矛盾或冲突，以促进社会和谐的偏差纠正方式。<br>下列属于社会纠偏的是：</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"有关部门根据市民的提议，把竣工不久的某大型立交桥附近的一片闲置的空地改建成了绿化场地，并安装了单双杠、跑步机、乒乓球台等多种健身器材，成了周围市民喜欢的休闲娱乐广场"},{"k":"B","t":"导游因强迫游客购买翡翠玉石遭到游客下车抵制的视频冲上热搜后，团队游购物陷阱等丑闻相继曝光。面对来自社会的巨大压力，旅行社、景点进行了针对性整顿，投诉大幅减少"},{"k":"C","t":"超市、菜市场的肉类和蔬果在商家“生鲜灯”的灯光下显得光鲜水灵，但买到家中一点也不新鲜。对此，市场监督管理总局明确规定不得使用对食品真实色泽造成明显改变的照明设施误导消费者"},{"k":"D","t":"高彩礼不仅是农村青年男女结婚的障碍，也引发了大量纠纷。近年来，尽管人大代表多次提交整治高彩礼的建议，不少地方也陆续出台了彩礼最高限额的政策规定，但农村高彩礼问题仍然没有得到解决"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“由公众主导”“有效化解矛盾或冲突”。<br>第二步：逐一分析选项。<br>A项：有关部门根据市民的提议把空地改建成绿化场地，没有涉及矛盾或冲突，不符合“有效化解矛盾或冲突”，不符合定义，排除。<br>B项：因旅游乱象、丑闻相继曝光，旅行社和景点承担了来自社会的压力，符合“由公众主导”，导游强迫游客购物的行为遭到游客抵制，体现了矛盾冲突，经整顿后投诉减少，符合“有效化解矛盾或冲突”，符合定义，当选。<br>C项：规定“不得使用对食品真实色泽造成明显改变的照明设施误导消费者”的的主体是市场监督管理总局，未体现公众的反应，不符合“由公众主导”，不符合定义，排除。<br>D项：农村高彩礼引发大量纠纷，但农村高彩礼问题仍然没有得到解决，不符合“有效化解矛盾或冲突”，不符合定义，排除。<br>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":103,"pid":"p4999a05dc1"},{"qid":"16095275","no":41,"type":"定义判断","module":"判断推理","stem":"<p>文字讨好症：指网络对话过程中，通过调整用词、添加语气词或特定符号避免聊天时带来的冷漠与疏离，让对话变得更加轻松、愉悦、舒适。<br>下列属于文字讨好症的是：</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"<p>小胡正忙得不可开交，突然收到同事微信，请他帮忙校对文档有没有错误，小胡回复“<img src=\"assets/img/timu/18d7c83962929dc.png\" class=\"fig\" style=\"width:50px;height:53px;\">”，同事回复道：“好，有问题随时沟通。”</p>"},{"k":"B","t":"<p>小刘刚把年终考核表发给人事秘书就收到回复：“格式不对，请重新修改！”小刘立即回复：“嗯嗯，好的好的，你们太能折腾了。”</p>"},{"k":"C","t":"<p>遇到同事吐槽领导，老赵虽然不太认同，但总是习惯性地附和；听到朋友的旅游经历，不管喜不喜欢，都会竖起大拇指：“哇哇哇！太棒了！”</p>"},{"k":"D","t":"<p>小秦下班到家累瘫在沙发上，突然收到客户投诉信息，立刻坐起来逐字逐句推敲回复用语，“好哒”“好滴”“<img src=\"assets/img/timu/18d7c83bb630d39.png\" class=\"fig\" style=\"width:50px;height:43px;\">”不断在屏幕上跳动</p>"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“网络对话过程中”、“调整用词、添加语气词或特定符号”、“避免聊天时带来的冷漠与疏离，让对话变得更加轻松、愉悦、舒适”。<br>第二步：逐一分析选项。<br>A项：小胡正忙时接到同事请求帮助的信息，回复“OK”的表情，是用简洁的回复以节约时间，同事回复“随时沟通”，属于正常的工作交流，不符合“调整用词、添加语气词或特定符号”、“避免聊天时带来的冷漠与疏离，让对话变得更加轻松、愉悦、舒适”，不符合定义，排除；<br>B项：小刘收到需要修改文件格式的信息后回复“嗯嗯，好的好的，你们太能折腾了”，属于不耐烦的语气，不符合“避免聊天时带来的冷漠与疏离，让对话变得更加轻松、愉悦、舒适”，不符合定义，排除；<br>C项：听到朋友的旅游经历，老赵都会竖起大拇指进行附和，说明两人的对话方式为面对面，不符合“网络对话过程中”，不符合定义，排除；<br>D项：小秦下班后收到客户的投诉信息并回复，符合“网络对话过程中”，推敲回复用语，并发送“好哒”“好滴”的词语以及“抱拳”的表情，符合“调整用词、添加语气词或特定符号”、“避免聊天时带来的冷漠与疏离，让对话变得更加轻松、愉悦、舒适”，符合定义，当选。<br>故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":104,"pid":"p4999a05dc1"},{"qid":"16095273","no":42,"type":"定义判断","module":"判断推理","stem":"<p>消费者教育：指通过有计划的宣传或培训，引导民众更新消费观念，掌握消费技能，培养消费习惯，使其形成产品购买的合理预期。<br>下列属于消费者教育的是：</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"丁先生根据亲身经历写出了一份新疆自驾游的攻略，包括具体线路、沿途景点门票、酒店、美食等，还推荐了几个口碑很好的当地导游，发布到了多家网站上，大批网友经过验证后给予了好评"},{"k":"B","t":"某网站的帖子图文并茂地分析了各种榨汁机、豆浆机、养生壶、料理机的优缺点，推荐了一款黑科技“破壁机”，详细介绍了它的材质、功能、操作方法以及明星的使用体验，最后还附上了商家的二维码"},{"k":"C","t":"某购物网站邀请网络写手连载长篇小说，让员工发动亲朋好友评论转发，大批粉丝追更到凌晨，网站贴心地附上了缓解眼睛疲劳的新产品供大家免费试用，两三个月后，访问量和营业额都有了显著提高"},{"k":"D","t":"某知名品牌菜刀拍蒜后刀身断裂的视频在多个社交网站引发网友吐槽，厂家回应称视频中的菜刀属于高科技新品，硬度高，材质脆，受横向冲击时容易断裂，不适合拍蒜"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“有计划的宣传或培训”、“引导民众更新消费观念，掌握消费技能，培养消费习惯”、“形成产品购买的合理预期”。<br>第二步：逐一分析选项。<br>A项：丁先生写出新疆自驾游攻略，目的是为了方便大家更便捷的出游，并非为了引导民众更新消费观念，不符合“引导民众更新消费观念，掌握消费技能，培养消费习惯”，不符合定义，排除；<br>B项：某网站分析了一些小家电的优缺点，让消费者了解相关产品的不同性能，符合“有计划的宣传或培训”，其中推荐了一款“破壁机”，并附上商家的二维码，目的是为了让消费者选择购买，符合“引导民众更新消费观念，掌握消费技能，培养消费习惯”、“形成产品购买的合理预期”，符合定义，当选；<br>C项：某购物网站邀请网络写手连载长篇小说，并为熬夜追更的粉丝免费提供缓解眼睛疲劳的新产品，目的是为了提高网站的访问量和营业额，并非为了引导民众更新消费观念，不符合“引导民众更新消费观念，掌握消费技能，培养消费习惯”，不符合定义，排除；<br>D项：厂家对菜刀质量问题的回应，目的是为了解释菜刀因拍蒜而刀身断裂的原因，并非为了引导民众更新消费观念，不符合“引导民众更新消费观念，掌握消费技能，培养消费习惯”，不符合定义，排除。<br>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":105,"pid":"p4999a05dc1"},{"qid":"16095292","no":43,"type":"定义判断","module":"判断推理","stem":"<p>鸡蛋理论：源自一家食品公司配方齐全的蛋糕粉滞销，后来故意去掉其中的蛋黄，让顾客烘培时自行添加，蛋糕粉反而变得畅销的案例。现指对于一个物品付出的劳动或情感越多就越容易高估其价值的认知规律；也指在不增加难度的前提下，让消费者适当参与部分生产环节打造个性化产品以增加成就感，进而提高销售效果的商业经营策略。<br>下列不属于鸡蛋理论的是：</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"张女士周日买了鸡腿和调料包，带着五岁的儿子一起动手涂抹调料、添加葱姜、搅拌均匀，放进空气炸锅烤上几分钟，就成了香喷喷的DIY鸡腿，孩子竟一连吃了五六个"},{"k":"B","t":"小梅选购毕业礼物时发现一家销售定制手环的网店，商家介绍说可以免费在手环上刻印自己姓名，她一下子买了二十多个，收到礼物的同学都很开心"},{"k":"C","t":"赵先生画出设计图草稿后，总会发到部门工作群，并附上一些考虑不太成熟的小问题请大家参与评论。因为每次都会有不少人踊跃参与，最终的设计方案在公司很容易通过"},{"k":"D","t":"很多草莓种植户在销售期，都会开放“自采自买”模式，自己采摘的草莓自己买下。价格不一定比超市或者菜场便宜，但是顾客有满满的收获感和满足感，吃起来更香了"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“一个物品付出的劳动或情感越多就越容易高估其价值”、“让消费者适当参与部分生产环节打造个性化产品”、“增加成就感，提高销售效果”。<br>第二步：逐一分析选项。<br>A项：张女士带着儿子一起制作鸡腿，儿子在制作鸡腿的过程中付出了劳动且最终一连吃了五六个，符合“一个物品付出的劳动或情感越多就越容易高估其价值”，符合定义，排除；<br>B项：商家介绍可以在手环上刻印姓名，小梅便在网店为同学们定制了二十多个带自己姓名的手环，符合“让消费者适当参与部分生产环节打造个性化产品”、“增加成就感，提高销售效果”，符合定义，排除；<br>C项：赵先生将设计图草稿中的问题发到部门工作群和其他同事一起讨论，最终的设计方案很容易通过，说明部门的内部讨论可以有效完善设计方案，但没有高估设计方案的价值，不符合“一个物品付出的劳动或情感越多就越容易高估其价值”，且设计方案的内部讨论不涉及消费者，也不符合“让消费者适当参与部分生产环节打造个性化产品”、“增加成就感，提高销售效果”，不符合定义，当选；<br>D项：草莓种植户在销售期开放“自采自买”模式，顾客可以将自己采摘的草莓买下，符合“让消费者适当参与部分生产环节打造个性化产品”、“增加成就感，提高销售效果”，符合定义，排除。<br>本题为选非题，故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":106,"pid":"p4999a05dc1"},{"qid":"16095264","no":44,"type":"定义判断","module":"判断推理","stem":"<p>选择支持效应：指人们做出某一选择后，就会找出多种理由来证明它的正确性，并排斥其他可能选择的现象。<br>下列属于选择支持效应的是：</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"孔女士周末喜欢开车带小孩到周边景点亲子游，每次总会带上同事朱女士的女儿。她认为两人是朋友，这样的活动既可以开阔孩子视野，又可以密切两家关系。朱女士偶尔也会一同去"},{"k":"B","t":"钱先生的餐馆开业后，顾客首次进店消费享受8折优惠，第二次以后7折优惠。家人都担心会亏本，他却坚信只要有了回头客，生意一定会越来越好"},{"k":"C","t":"曹女士常常到小商店买日用品，觉得既省钱又省心。儿子发现她刚买的运动鞋几天就穿坏了，劝她到商场买品牌运动鞋，她不以为然，认为这鞋便宜，穿着又很舒服，自己身体硬朗，不会出什么事儿"},{"k":"D","t":"某野生动物园为了保护自然生态及游客安全，分片区建了许多防护围栏，有网友抱怨：“参观这个动物园要走不少冤枉路”。景区很快就规划出最佳游览线路图并在园内各处作了醒目“标记”"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“人们做出某一选择后”、“会找出多种理由来证明它的正确性”、“排斥其他可能选择”。<br>第二步：逐一分析选项。<br>A项：孔女士周末喜欢开车带小孩到周边景点亲子游，每次总会带上同事朱女士的女儿，符合“人们做出某一选择后”，孔女士认为两人是朋友，这样的活动既可以开阔孩子视野，又可以密切两家关系，符合“会找出多种理由来证明它的正确性”，但并没有体现“排斥其他可能选择”，不符合定义，排除；<br>B项：钱先生的餐馆开业后，采取了一些优惠措施，符合“人们做出某一选择后”，钱先生坚信只要有了回头客，生意就会越来越好，只体现了“有回头客”这一种理由，不符合“会找出多种理由来证明它的正确性”，不符合定义，排除；<br>C项：曹女士常常到小商店买日用品，符合“人们做出某一选择后”，她认为小商店买的运动鞋便宜，穿着又很舒服，自己身体硬朗，不会出什么事儿，符合“会找出多种理由来证明它的正确性”，儿子劝曹女士到商场买品牌运动鞋，她不以为然，符合“排斥其他可能选择”，符合定义，当选；<br>D项：某野生动物园分片区建了许多防护围栏，符合“人们做出某一选择后”，有网友抱怨动物园的缺点，景区很快就做出改进，不符合“排斥其他可能选择”，不符合定义，排除。<br>故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":107,"pid":"p4999a05dc1"},{"qid":"17900893","no":45,"type":"定义判断","module":"判断推理","stem":"<p>驳岸：指用砖石、植被或混凝土等材料建造在水体边缘与陆地交界处的保护性工程设施。江河湖泊驳岸用来防止堤岸因被水流长时间冲刷而塌方；园林驳岸用于遮挡园内建筑物，增加景观层次感和丰富度。<br>下列不属于驳岸的是：</p>","material":"<p>市住建局3名工作人员小郑、小周、小刘打算参加“青年党员下基层”调研活动。可选的有小微堵点改造、跨区断头路建设、小型城市客厅打造、历史街区微改造4个调研项目。指导调研的有王教授、钱教授、马教授，且他们只能指导上述三位工作人员，已知：</p><p>（1）每位工作人员参加的项目都必须有教授指导，每位教授至少指导一位工作人员；</p><p>（2）每位工作人员只能参加一个项目，提倡多人合作；</p><p>（3）每位教授只能指导一个项目，一个项目也可由多位教授共同指导；</p><p>（4）小郑参加小微堵点改造或跨区断头路建设项目，钱教授指导历史街区微改造项目。</p>","materialNo":1,"options":[{"k":"A","t":"缺失题目正在全力以赴征集，将会第一时间上传。（正确答案默认设置为B项。）"},{"k":"B","t":"缺失"},{"k":"C","t":"缺失"},{"k":"D","t":"缺失"}],"answer":"B","multi":false,"explanation":"<p>题目缺失，正在征集，暂以B项代替。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"判断推理"},"idx":108,"pid":"p4999a05dc1"},{"qid":"17900916","no":1,"type":"综合","module":"资料分析","stem":"<p>2022年我国网络零售交易额为：</p>","material":"<p>        2022年，我国网络购物用户8.5亿人，使用率为79.2%；网络直播用户7.5亿人，比上年增长6.8%，占网民总数的70.3%；直播电商行业交易额为3.5万亿元，较2017年增长178倍，直播电商行业渗透率（直播电商行业渗透率<img src=\"assets/img/gongshi/formula-d78ff121e40ba037.png\" class=\"tex\">）为25.3%；重点监测电商平台直播场次超1.2亿场，较2020年增长5倍；直播电商行业三大平台交易额分别为1.5万亿元、0.9万亿元和0.8万亿元。</p><p><img src=\"assets/img/timu/1907134d84c047d.png\" class=\"fig\" style=\"width:597px;height:156px;\"></p>","materialNo":1,"options":[{"k":"A","t":"0.9万亿元"},{"k":"B","t":"8.5万亿元"},{"k":"C","t":"13.8万亿元"},{"k":"D","t":"15.3万亿元"}],"answer":"C","multi":false,"explanation":"<p>根据题干“2022年我国网络零售交易额为”，结合资料时间为2022年及资料给出直播电商行业渗透率<img src=\"assets/img/gongshi/formula-d78ff121e40ba037.png\" class=\"tex\">，可判定本题为现期比重问题。定位文字资料可知，2022年我国直播电商行业交易额为3.5万亿元，直播电商行业渗透率为25.3%。根据公式：整体<img src=\"assets/img/gongshi/formula-e94c4ad87ea0e515.png\" class=\"tex\">，可得题干所求<img src=\"assets/img/gongshi/formula-793c091f5b1b4104.png\" class=\"tex\">万亿元，与C项最接近。</p><p>故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"资料分析"},"idx":109,"pid":"p4999a05dc1"},{"qid":"17900920","no":2,"type":"综合","module":"资料分析","stem":"<p>2022年与2021年我国直播电商行业交易额之比为：</p>","material":"<p>        2022年，我国网络购物用户8.5亿人，使用率为79.2%；网络直播用户7.5亿人，比上年增长6.8%，占网民总数的70.3%；直播电商行业交易额为3.5万亿元，较2017年增长178倍，直播电商行业渗透率（直播电商行业渗透率<img src=\"assets/img/gongshi/formula-d78ff121e40ba037.png\" class=\"tex\">）为25.3%；重点监测电商平台直播场次超1.2亿场，较2020年增长5倍；直播电商行业三大平台交易额分别为1.5万亿元、0.9万亿元和0.8万亿元。</p><p><img src=\"assets/img/timu/1907134d84c047d.png\" class=\"fig\" style=\"width:597px;height:156px;\"></p>","materialNo":1,"options":[{"k":"A","t":"5：3"},{"k":"B","t":"6：5"},{"k":"C","t":"7：3"},{"k":"D","t":"7：4"}],"answer":"D","multi":false,"explanation":"<p>根据题干“2022年与2021年······之比为”，可判定本题为比值计算问题。定位文字资料可知，2022年我国直播电商行业交易额为3.5万亿元；定位表格资料可知，2021年我国直播电商行业用户数为4.3亿人，人均年消费额为4640元。则2021年我国直播电商行业交易额<img src=\"assets/img/gongshi/formula-a5428056054fde7e.png\" class=\"tex\">万亿元，故题干所求比值约为3.5：2=7：4。</p><p>故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"资料分析"},"idx":110,"pid":"p4999a05dc1"},{"qid":"17900939","no":3,"type":"增长","module":"资料分析","stem":"<p>若2019-2022年我国直播电商行业企业数、用户数、人均年消费额的年均增速分别用<img src=\"assets/img/gongshi/formula-fe689eec2a1eedbe.png\" class=\"tex\">、<img src=\"assets/img/gongshi/formula-b2680b7e955cc287.png\" class=\"tex\">、<img src=\"assets/img/gongshi/formula-b2314f4519b631c5.png\" class=\"tex\">表示。则下列关系式正确的是：</p>","material":"<p>        2022年，我国网络购物用户8.5亿人，使用率为79.2%；网络直播用户7.5亿人，比上年增长6.8%，占网民总数的70.3%；直播电商行业交易额为3.5万亿元，较2017年增长178倍，直播电商行业渗透率（直播电商行业渗透率<img src=\"assets/img/gongshi/formula-d78ff121e40ba037.png\" class=\"tex\">）为25.3%；重点监测电商平台直播场次超1.2亿场，较2020年增长5倍；直播电商行业三大平台交易额分别为1.5万亿元、0.9万亿元和0.8万亿元。</p><p><img src=\"assets/img/timu/1907134d84c047d.png\" class=\"fig\" style=\"width:597px;height:156px;\"></p>","materialNo":1,"options":[{"k":"A","t":"<p><img src=\"assets/img/gongshi/formula-3186747b1bd20876.png\" class=\"tex\"></p>"},{"k":"B","t":"<p><img src=\"assets/img/gongshi/formula-f0e1f188362b08d7.png\" class=\"tex\"></p>"},{"k":"C","t":"<p><img src=\"assets/img/gongshi/formula-7e903cbbcc118dd1.png\" class=\"tex\"></p>"},{"k":"D","t":"<p><img src=\"assets/img/gongshi/formula-709a2dd7457feba4.png\" class=\"tex\"></p>"}],"answer":"B","multi":false,"explanation":"<p>根据题干“······年均增速······下列关系式正确的是”，可判定本题为年均增长率问题。定位表格资料可知2018-2022年我国直播电商行业企业数、用户数及人均年消费额。根据年均增长率公式：<img src=\"assets/img/gongshi/formula-cfc3b7227943ca1c.png\" class=\"tex\">（n为年份差），当年份差相同时，直接比较<img src=\"assets/img/gongshi/formula-4d79e426c95b2bf5.png\" class=\"tex\">即可。则2019-2022年我国直播电商行业企业数、用户数、人均年消费额的<img src=\"assets/img/gongshi/formula-4d79e426c95b2bf5.png\" class=\"tex\">分别为：企业数，<img src=\"assets/img/gongshi/formula-b04653ecce26d823.png\" class=\"tex\">；用户数，<img src=\"assets/img/gongshi/formula-9ac36ed968502eea.png\" class=\"tex\">；人均年消费额，<img src=\"assets/img/gongshi/formula-bf056c71c14e4e96.png\" class=\"tex\">。则年均增速由低到高排序为<img src=\"assets/img/gongshi/formula-33dd342b8a20833b.png\" class=\"tex\">。</p><p>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"资料分析"},"idx":111,"pid":"p4999a05dc1"},{"qid":"17900953","no":4,"type":"比重","module":"资料分析","stem":"<p>下列能够表示2022年我国直播电商行业三大平台交易额比例关系的示意图是：</p>","material":"<p>        2022年，我国网络购物用户8.5亿人，使用率为79.2%；网络直播用户7.5亿人，比上年增长6.8%，占网民总数的70.3%；直播电商行业交易额为3.5万亿元，较2017年增长178倍，直播电商行业渗透率（直播电商行业渗透率<img src=\"assets/img/gongshi/formula-d78ff121e40ba037.png\" class=\"tex\">）为25.3%；重点监测电商平台直播场次超1.2亿场，较2020年增长5倍；直播电商行业三大平台交易额分别为1.5万亿元、0.9万亿元和0.8万亿元。</p><p><img src=\"assets/img/timu/1907134d84c047d.png\" class=\"fig\" style=\"width:597px;height:156px;\"></p>","materialNo":1,"options":[{"k":"A","t":"<p><img src=\"assets/img/timu/1906db4d7d11dfa.png\" class=\"fig\" style=\"width:153px;height:149px;\"></p>"},{"k":"B","t":"<p><img src=\"assets/img/timu/1906db4e937e061.png\" class=\"fig\" style=\"width:153px;height:149px;\"></p>"},{"k":"C","t":"<p><img src=\"assets/img/timu/1906db4fbd4ad1c.png\" class=\"fig\" style=\"width:153px;height:150px;\"></p>"},{"k":"D","t":"<p><img src=\"assets/img/timu/1906db50aeaf4c5.png\" class=\"fig\" style=\"width:153px;height:152px;\"></p>"}],"answer":"A","multi":false,"explanation":"<p>根据题干“······2022年······比例关系的示意图是”，结合资料时间为2022年，可判定本题为现期比重问题。定位文字资料可知，2022年我国直播电商行业三大平台交易额分别为1.5万亿元、0.9万亿元和0.8万亿元。因为1.5&lt;0.9+0.8，所以1.5万亿元未占到三大平台交易额的一半，排除B、D两项；又因为1.5万亿元明显大于0.9万亿元，所以排除C项。<br>故正确答案为A。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"资料分析"},"idx":112,"pid":"p4999a05dc1"},{"qid":"17900955","no":5,"type":"综合","module":"资料分析","stem":"<p>能够从上述资料中推出的是：</p>","material":"<p>        2022年，我国网络购物用户8.5亿人，使用率为79.2%；网络直播用户7.5亿人，比上年增长6.8%，占网民总数的70.3%；直播电商行业交易额为3.5万亿元，较2017年增长178倍，直播电商行业渗透率（直播电商行业渗透率<img src=\"assets/img/gongshi/formula-d78ff121e40ba037.png\" class=\"tex\">）为25.3%；重点监测电商平台直播场次超1.2亿场，较2020年增长5倍；直播电商行业三大平台交易额分别为1.5万亿元、0.9万亿元和0.8万亿元。</p><p><img src=\"assets/img/timu/1907134d84c047d.png\" class=\"fig\" style=\"width:597px;height:156px;\"></p>","materialNo":1,"options":[{"k":"A","t":"2017年我国直播电商行业交易额超过250亿元"},{"k":"B","t":"2020年我国直播电商行业直播场次超过2000万场"},{"k":"C","t":"2019—2022年，我国直播电商行业企业数增速逐年加快"},{"k":"D","t":"2019—2022年，我国直播电商行业用户数增加最多的是2022年"}],"answer":"B","multi":false,"explanation":"<p>A项：定位文字资料可知，2022年我国直播电商行业交易额为3.5万亿元，较2017年增长178倍。根据公式：基期量<img src=\"assets/img/gongshi/formula-0136d9c7a25c249d.png\" class=\"tex\">，可得2017年我国直播电商行业交易额<img src=\"assets/img/gongshi/formula-ceabfb60edd58c27.png\" class=\"tex\">亿元，未超过250亿元，错误。 </p><p>B项：定位文字资料可知，2022年我国重点监测电商平台直播场次超1.2亿场，较2020年增长5倍。根据公式：基期量<img src=\"assets/img/gongshi/formula-0136d9c7a25c249d.png\" class=\"tex\">，可得2020年我国重点监测电商平台直播场次超过<img src=\"assets/img/gongshi/formula-f617fee2c977eb29.png\" class=\"tex\">亿场=2000万场，2020年我国直播电商行业直播场次必然多于重点监测电商平台直播场次，即超过2000万场，正确。</p><p>C项：定位表格资料可知2018—2022年我国直播电商行业企业数。根据公式：增长率<img src=\"assets/img/gongshi/formula-9ad7a88fa1bfefd7.png\" class=\"tex\">，可得2021年直播电商行业企业数同比增速<img src=\"assets/img/gongshi/formula-7a7faac1e41ae70f.png\" class=\"tex\">，2022年直播电商行业企业数同比增速<img src=\"assets/img/gongshi/formula-e159b8e5bd8e9fec.png\" class=\"tex\">，则2021年同比增速&gt;2022年同比增速，并非逐年加快，错误。</p><p>D项：定位表格资料可知2018—2022年我国直播电商行业用户数。根据公式：增长量=现期量-基期量，可得2019—2022年我国直播电商行业用户数同比增长量分别为：2019年，2.5-2.2=0.3亿人；2020年，3.7-2.5=1.2亿人；2021年，4.3-3.7=0.6亿人；2022年，4.7-4.3=0.4亿人。因此2019—2022年我国直播电商行业用户数增加最多的是2020年，错误。</p><p>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"资料分析"},"idx":113,"pid":"p4999a05dc1"},{"qid":"17900761","no":6,"type":"增长","module":"资料分析","stem":"<p>2023年第二季度，该市工业用电量同比增加：</p>","material":"<p><img src=\"assets/img/timu/1906d95c1406b79.png\" class=\"fig\" style=\"width:664px;height:431px;\"></p>","materialNo":2,"options":[{"k":"A","t":"4.5亿千瓦时"},{"k":"B","t":"3.8亿千瓦时"},{"k":"C","t":"11.7亿千瓦时"},{"k":"D","t":"3.0亿千瓦时"}],"answer":"B","multi":false,"explanation":"<p>根据题干“2023年第二季度，该市工业用电量同比增加”，结合选项带单位，可判定本题为增长量计算问题。定位表格资料可知，2022年1—3月该市累计工业用电量为81.6亿千瓦时，1—6月累计为169.8亿千瓦时；2023年1—3月该市累计工业用电量为81.3亿千瓦时，1—6月累计为173.3亿千瓦时。则所求增长量=2023年第二季度工业用电量-2022年第二季度工业用电量=（173.3-81.3）-（169.8-81.6）=92-88.2=3.8亿千瓦时。<br>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"资料分析"},"idx":114,"pid":"p4999a05dc1"},{"qid":"17900762","no":7,"type":"综合","module":"资料分析","stem":"<p>2022年第一季度—2023年第二季度，该市进出口总额最多的季度是：</p>","material":"<p><img src=\"assets/img/timu/1906d95c1406b79.png\" class=\"fig\" style=\"width:664px;height:431px;\"></p>","materialNo":2,"options":[{"k":"A","t":"2022年第二季度"},{"k":"B","t":"2022年第三季度"},{"k":"C","t":"2022年第四季度"},{"k":"D","t":"2023年第二季度"}],"answer":"C","multi":false,"explanation":"<p>定位表格资料可知，该市2022年1—3月累计进出口总额为1388.0亿元，1—6月累计进出口总额为2988.0亿元，1—9月累计进出口总额为4566.0亿元，1—12月累计进出口总额为6292.0亿元；2023年1—3月累计进出口总额为1443.0亿元，1—6月累计进出口总额为2915.0亿元。则该市各季度进出口总额分别为：2022年第二季度=2988.0-1388.0=1600亿元；2022年第三季度=4566.0-2988.0=<img src=\"assets/img/gongshi/formula-f86d1080db9305b6.png\" class=\"tex\">亿元；2022年第四季度=6292.0-4566.0=<img src=\"assets/img/gongshi/formula-9880f0580d6dfc77.png\" class=\"tex\">亿元；2023年第二季度=2915.0-1443.0=<img src=\"assets/img/gongshi/formula-3ee8ae39fa4f0113.png\" class=\"tex\">亿元。比较可得，2022年第四季度该市进出口总额最多。</p><p>故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"资料分析"},"idx":115,"pid":"p4999a05dc1"},{"qid":"17900763","no":8,"type":"增长","module":"资料分析","stem":"<p>2023年第二季度，该市第三产业增加值是：</p>","material":"<p><img src=\"assets/img/timu/1906d95c1406b79.png\" class=\"fig\" style=\"width:664px;height:431px;\"></p>","materialNo":2,"options":[{"k":"A","t":"2623亿元"},{"k":"B","t":"2766亿元"},{"k":"C","t":"3262亿元"},{"k":"D","t":"4087亿元"}],"answer":"A","multi":false,"explanation":"<p>根据题干“2023年第二季度，该市第三产业增加值是”，结合资料给出该市2023年1—3月、1—6月的地区生产总值和第三产业增加值占比，可判定本题为现期比重计算问题。定位表格资料可知，该市2023年1—3月、1—6月累计地区生产总值分别为4230.0亿元、8317.0亿元，第三产业增加值占比分别为65.4%、64.8%。根据公式：部分=整体×比重，可得2023年第二季度该市第三产业增加值=2023年1—6月第三产业增加值-2023年1—3月第三产业增加值=8317.0×64.8%-4230.0×65.4%&lt;8317×65%-4230×65%=（8317-4230）×65%=4087×65%&lt;4100×65%=2665亿元，只有A项符合。<br>故正确答案为A。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"资料分析"},"idx":116,"pid":"p4999a05dc1"},{"qid":"17900764","no":9,"type":"增长","module":"资料分析","stem":"<p>2023年上半年，该市地区生产总值、社会消费品零售总额、实际利用外资、工业用电量四个指标中同比增速最快的是：</p>","material":"<p><img src=\"assets/img/timu/1906d95c1406b79.png\" class=\"fig\" style=\"width:664px;height:431px;\"></p>","materialNo":2,"options":[{"k":"A","t":"地区生产总值"},{"k":"B","t":"社会消费品零售总额"},{"k":"C","t":"实际利用外资"},{"k":"D","t":"工业用电量"}],"answer":"C","multi":false,"explanation":"<p>根据题干“2023年上半年······同比增速最快的是”，可判定本题为一般增长率问题。定位表格资料可知，2022年1—6月该市累计地区生产总值为7879.0亿元，社会消费品零售总额为4000.0亿元，实际利用外资为35.3亿美元，工业用电量为169.8亿千瓦时；2023年1—6月该市累计地区生产总值为8317.0亿元，社会消费品零售总额为4358.0亿元，实际利用外资为39.6亿美元，工业用电量为173.3亿千瓦时。根据公式：增长率<img src=\"assets/img/gongshi/formula-9ad7a88fa1bfefd7.png\" class=\"tex\">，可得各选项的增速分别为：地区生产总值，<img src=\"assets/img/gongshi/formula-6b3e41c58b126cc5.png\" class=\"tex\">；社会消费品零售总额，<img src=\"assets/img/gongshi/formula-e6e56412623621d5.png\" class=\"tex\">；实际利用外资，<img src=\"assets/img/gongshi/formula-f73b1708c8a938ac.png\" class=\"tex\">；工业用电量，<img src=\"assets/img/gongshi/formula-d8184c67ef41de5d.png\" class=\"tex\">。比较可知，2023年上半年，四个指标中实际利用外资的同比增速最快。</p><p>故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"资料分析"},"idx":117,"pid":"p4999a05dc1"},{"qid":"17900765","no":10,"type":"综合","module":"资料分析","stem":"<p>能够从上述资料中推出的是：</p>","material":"<p><img src=\"assets/img/timu/1906d95c1406b79.png\" class=\"fig\" style=\"width:664px;height:431px;\"></p>","materialNo":2,"options":[{"k":"A","t":"2023年1—6月，该市进口额没有超过1100亿元"},{"k":"B","t":"2023年第二季度，该市出口额环比增速高于进出口总额环比增速"},{"k":"C","t":"2022年第二季度—2023年第二季度，该市季度固定资产投资最大值是1705亿元"},{"k":"D","t":"2022年1月—2023年6月，该市月平均社会消费品零售总额超过700亿元"}],"answer":"B","multi":false,"explanation":"<p>A项：定位表格资料可知，该市2023年1—6月累计进出口总额为2915.0亿元，出口占进出口总额的比重为58.1%。根据公式：部分=整体×比重，则2023年1—6月该市进口额=2915.0×（1-58.1%）=2915×41.9%&gt;2900×40%=1160亿元，即超过了1100亿元，错误；</p><p>B项：定位表格资料可知，该市2023年1—3月累计、1—6月累计出口占进出口总额的比重分别为57.8%、58.1%。1—6月累计=第一季度（1—3月累计）+第二季度，根据混合比重结论“混合后居中”可得，第一季度出口额占比（57.8%）&lt;1—6月累计出口额占比（58.1%）&lt;第二季度出口额占比，可知第二季度出口额占比环比上升。根据两期比重比较结论“当a（部分增长率）&gt;b（整体增长率）时，比重上升”，反之，当比重上升时，a&gt;b，故2023年第二季度出口额环比增速（a）&gt;进出口总额环比增速（b），正确；</p><p>C项：定位表格资料可知该市2022—2023年上半年固定资产投资额。则2022年第二季度固定资产投资=3040.0-1323.0=1717亿元&gt;1705亿元，错误；</p><p>D项：定位表格资料可知，该市2022年1—12月累计社会消费品零售总额为7832.0亿元，2023年1—6月累计社会消费品零售总额为4358.0亿元。则2022年1月—2023年6月该市月平均社会消费品零售总额<img src=\"assets/img/gongshi/formula-d39a1b2a5b9c3ab9.png\" class=\"tex\">亿元&lt;700亿元，错误。</p><p>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"资料分析"},"idx":118,"pid":"p4999a05dc1"},{"qid":"15121341","no":11,"type":"综合","module":"资料分析","stem":"<p>2022年我国酱油进口量与“十三五”时期（2016-2020年）的年均进口量相差：</p>","material":"<p><img src=\"assets/img/timu/18d776527543f62.png\" class=\"fig\" style=\"width:676px;height:419px;\"></p>","materialNo":3,"options":[{"k":"A","t":"0.19万吨"},{"k":"B","t":"0.21万吨"},{"k":"C","t":"0.23万吨"},{"k":"D","t":"0.25万吨"}],"answer":"A","multi":false,"explanation":"<p>根据题干“······‘十三五’时期（2016-2020年）的年均进口量······”，可判定本题为现期平均数问题。定位表格可知2016-2020年、2022年我国酱油进口量。根据公式：平均数<img src=\"assets/img/gongshi/formula-7d3edb2d0cd29191.png\" class=\"tex\">，则“十三五”时期（2016-2020年）的年均进口量<img src=\"assets/img/gongshi/formula-8ae128efece34d50.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-5522529ad222edf0.png\" class=\"tex\">万吨，故2022年我国酱油进口量与“十三五”时期（2016-2020年）的年均进口量相差1.36-1.17=0.19万吨。</p><p>故正确答案为A。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"资料分析"},"idx":119,"pid":"p4999a05dc1"},{"qid":"15121354","no":12,"type":"增长","module":"资料分析","stem":"<p>2016-2022年我国酱油进出口总额比上年减少的年份是：</p>","material":"<p><img src=\"assets/img/timu/18d776527543f62.png\" class=\"fig\" style=\"width:676px;height:419px;\"></p>","materialNo":3,"options":[{"k":"A","t":"2016年"},{"k":"B","t":"2018年"},{"k":"C","t":"2020年"},{"k":"D","t":"2022年"}],"answer":"C","multi":false,"explanation":"<p>根据题干“2016-2022年······比上年减少的年份是”，可判定本题为增长量计算问题。定位表格可知2015-2022年我国酱油进口额与出口额。根据公式：增长量=现期量-基期量，选项中2016年、2018年、2020年、2022年进出口总额同比增量分别为：</p><p>2016年，（2109+11940）-（1758+11320）&gt;0，不符合题意；</p><p>2018年，<img src=\"assets/img/gongshi/formula-8b764ced250ce46f.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-5fe125da87b6914c.png\" class=\"tex\">，不符合题意；</p><p>2020年，<img src=\"assets/img/gongshi/formula-bdcb053074103a7d.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-bcf55dc921f37435.png\" class=\"tex\">，符合题意；</p><p>2022年，<img src=\"assets/img/gongshi/formula-4529de8b3dd77174.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-b92fbffdb34bdc78.png\" class=\"tex\">，不符合题意。</p><p>故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"资料分析"},"idx":120,"pid":"p4999a05dc1"},{"qid":"15121362","no":13,"type":"增长","module":"资料分析","stem":"<p>2016-2022年我国酱油进口量、出口量、进口额、出口额4个指标中年均增速最快的是：</p>","material":"<p><img src=\"assets/img/timu/18d776527543f62.png\" class=\"fig\" style=\"width:676px;height:419px;\"></p>","materialNo":3,"options":[{"k":"A","t":"进口量"},{"k":"B","t":"出口量"},{"k":"C","t":"进口额"},{"k":"D","t":"出口额"}],"answer":"D","multi":false,"explanation":"<p>根据题干“2016-2022年······年均增速最快的是”，可判定本题为年均增长率问题。定位表格可知2015年、2022年我国酱油进口量、出口量、进口额、出口额。根据公式：<img src=\"assets/img/gongshi/formula-6de24baa2becef83.png\" class=\"tex\">，年份差相同时，比较<img src=\"assets/img/gongshi/formula-4d79e426c95b2bf5.png\" class=\"tex\">即可。进口量，<img src=\"assets/img/gongshi/formula-791ac0ddf88e523a.png\" class=\"tex\">；出口量，<img src=\"assets/img/gongshi/formula-e0f4b157be4c395e.png\" class=\"tex\">；进口额，<img src=\"assets/img/gongshi/formula-e944171a830e14ea.png\" class=\"tex\">；出口额，<img src=\"assets/img/gongshi/formula-edd9160c83f97ae9.png\" class=\"tex\">。比较可知，2016-2022年我国酱油出口额年均增速最快。</p><p>故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"资料分析"},"idx":121,"pid":"p4999a05dc1"},{"qid":"15121371","no":14,"type":"比重","module":"资料分析","stem":"<p>2022年我国酱油进口额占进出口总额的比重是：</p>","material":"<p><img src=\"assets/img/timu/18d776527543f62.png\" class=\"fig\" style=\"width:676px;height:419px;\"></p>","materialNo":3,"options":[{"k":"A","t":"8.2%"},{"k":"B","t":"9.4%"},{"k":"C","t":"10.1%"},{"k":"D","t":"10.7%"}],"answer":"B","multi":false,"explanation":"<p>根据题干“2022年······占······的比重是”，结合材料给出2022年的数据，可判定本题为现期比重问题。定位表格可得：2022年我国酱油进口额为1905万美元，出口额为18385万美元。根据公式：比重<img src=\"assets/img/gongshi/formula-d63da1f151f9c3a5.png\" class=\"tex\">，则2022年我国酱油进口额占进出口总额的比重是<img src=\"assets/img/gongshi/formula-95e7fa01c5cbf438.png\" class=\"tex\">。</p><p>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"资料分析"},"idx":122,"pid":"p4999a05dc1"},{"qid":"15121390","no":15,"type":"综合","module":"资料分析","stem":"<p>从上述材料中不能推出的是：</p>","material":"<p><img src=\"assets/img/timu/18d776527543f62.png\" class=\"fig\" style=\"width:676px;height:419px;\"></p>","materialNo":3,"options":[{"k":"A","t":"2022年我国酱油进口均价比出口均价高50%以上"},{"k":"B","t":"2016-2022年我国酱油出口量年均增加超过0.9万吨"},{"k":"C","t":"2022年我国酱油出口量占进出口总量的比重比上年有所提高"},{"k":"D","t":"2016-2022年我国酱油进口量和进口额均比上年增加的年份有5个"}],"answer":"D","multi":false,"explanation":"<p>A项：定位表格可知2022年我国酱油进、出口量及进、出口额。根据公式：均价<img src=\"assets/img/gongshi/formula-bce1a2fecb9d5e4b.png\" class=\"tex\">，则2022年我国酱油进口均价为<img src=\"assets/img/gongshi/formula-2a894c6485cbcc5f.png\" class=\"tex\">美元/吨，出口均价为<img src=\"assets/img/gongshi/formula-b9b66d02082da481.png\" class=\"tex\">美元/吨，前者比后者高<img src=\"assets/img/gongshi/formula-f4b51eb19338d036.png\" class=\"tex\">，正确；</p><p>B项：定位表格可得：2015年与2022年我国酱油的出口量分别为11.74万吨和18.61万吨。根据公式：年均增长量<img src=\"assets/img/gongshi/formula-637d7c4ead96ab9d.png\" class=\"tex\">，则2016-2022年我国酱油出口量年均增加<img src=\"assets/img/gongshi/formula-7492c2a60971b25d.png\" class=\"tex\">万吨，正确；</p><p>C项：定位表格可知2021年与2022年我国酱油出口量与进口量。方法一：根据公式：比重<img src=\"assets/img/gongshi/formula-d63da1f151f9c3a5.png\" class=\"tex\">，则2022年出口量占进出口总量的比重为<img src=\"assets/img/gongshi/formula-1c040a406be6628c.png\" class=\"tex\">，2021年的比重为<img src=\"assets/img/gongshi/formula-2c675f79a6675808.png\" class=\"tex\">，前者大于后者，即2022年我国酱油出口量占进出口总量的比重比上年有所提高，正确；</p><p>方法二：出口量+进口量=进出口总量，且2022年出口量同比增速为正（18.61＞18.34），进口量同比增速为负（1.17＜1.35），根据混合增长率口诀“混合后居中”，则<img src=\"assets/img/gongshi/formula-975309eb8a3fac51.png\" class=\"tex\">。又根据两期比重比较结论“部分增长率＞整体增长率，则比重上升”，<img src=\"assets/img/gongshi/formula-5fc85b1caf1b2fef.png\" class=\"tex\">，则2022年我国酱油出口量占进出口总量的比重比上年有所提高，正确；</p><p>D项：定位表格可知2015-2022年各年我国酱油进口量和进口额。进口量和进口额均比上年增加的年份有2016年、2017年、2019年和2021年，共4个年份，错误。</p><p>本题为选非题，故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"资料分析"},"idx":123,"pid":"p4999a05dc1"},{"qid":"15121335","no":16,"type":"增长","module":"资料分析","stem":"<p>2015-2022年我国游戏市场用户数增加最多的年份是：</p>","material":"<p><img src=\"assets/img/timu/18d7726c16b25fd.png\" class=\"fig\" style=\"width:700px;height:323px;\"></p><p><img src=\"assets/img/timu/18d7726cf6d007b.png\" class=\"fig\" style=\"width:615px;height:375px;\"></p>","materialNo":4,"options":[{"k":"A","t":"2016年"},{"k":"B","t":"2018年"},{"k":"C","t":"2019年"},{"k":"D","t":"2020年"}],"answer":"B","multi":false,"explanation":"<p>根据题干“······增加最多······”，可以判定本题为增长量比较问题。定位表格材料可得，2015-2020年我国游戏市场用户数分别为534、566、583、626、641、665百万人。根据公式：增长量=现期量-基期量，可得选项中各年份我国游戏市场用户数增长量如下：<br>2016年，566-534=32百万人；<br>2018年，626-583=43百万人；<br>2019年，641-626=15百万人；<br>2020年，665-641=24百万人。<br>比较可知，2018年我国游戏市场用户数增加最多。<br>故正确答案为B。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"资料分析"},"idx":124,"pid":"p4999a05dc1"},{"qid":"15121343","no":17,"type":"综合","module":"资料分析","stem":"<p>2015-2022年我国游戏市场销售收入和用户数量变动趋势相同的年份有：</p>","material":"<p><img src=\"assets/img/timu/18d7726c16b25fd.png\" class=\"fig\" style=\"width:700px;height:323px;\"></p><p><img src=\"assets/img/timu/18d7726cf6d007b.png\" class=\"fig\" style=\"width:615px;height:375px;\"></p>","materialNo":4,"options":[{"k":"A","t":"4个"},{"k":"B","t":"5个"},{"k":"C","t":"7个"},{"k":"D","t":"8个"}],"answer":"D","multi":false,"explanation":"<p>定位表格材料可得2014-2022年我国游戏市场用户数量，定位图形材料可得2014-2022年我国游戏市场销售收入。经比较可知，2015-2021年我国游戏市场销售收入和用户数量每年均递增，2022年我国游戏市场销售收入和用户数量均下降，所以2015-2022年我国游戏市场销售收入和用户数量变动趋势每年都相同，共有8个年份。<br>故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"资料分析"},"idx":125,"pid":"p4999a05dc1"},{"qid":"15121349","no":18,"type":"增长","module":"资料分析","stem":"<p>2022年我国游戏市场销售收入比2014年增长：</p>","material":"<p><img src=\"assets/img/timu/18d7726c16b25fd.png\" class=\"fig\" style=\"width:700px;height:323px;\"></p><p><img src=\"assets/img/timu/18d7726cf6d007b.png\" class=\"fig\" style=\"width:615px;height:375px;\"></p>","materialNo":4,"options":[{"k":"A","t":"1.3倍"},{"k":"B","t":"1.8倍"},{"k":"C","t":"2.3倍"},{"k":"D","t":"2.8倍"}],"answer":"A","multi":false,"explanation":"<p>根据题干“2022年······比2014年增长”，结合选项为倍数，可判定本题为一般增长率问题。定位图形材料可得，2022年和2014年我国游戏市场销售收入分别为2659亿元和1145亿元。根据公式：增长率<img src=\"assets/img/gongshi/formula-9ad7a88fa1bfefd7.png\" class=\"tex\">，则2022年我国游戏市场销售收入比2014年增长<img src=\"assets/img/gongshi/formula-fadc9bc35c7b7fb2.png\" class=\"tex\">，即增长1.38倍，与A项最接近。</p><p>故正确答案为A。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"资料分析"},"idx":126,"pid":"p4999a05dc1"},{"qid":"15121365","no":19,"type":"增长","module":"资料分析","stem":"<p>若2023-2025年我国游戏市场销售收入每年按2020-2022年的年均增速增长，则2025年我国游戏市场销售收入将达到：</p>","material":"<p><img src=\"assets/img/timu/18d7726c16b25fd.png\" class=\"fig\" style=\"width:700px;height:323px;\"></p><p><img src=\"assets/img/timu/18d7726cf6d007b.png\" class=\"fig\" style=\"width:615px;height:375px;\"></p>","materialNo":4,"options":[{"k":"A","t":"2648亿元"},{"k":"B","t":"2834亿元"},{"k":"C","t":"3062亿元"},{"k":"D","t":"3286亿元"}],"answer":"C","multi":false,"explanation":"<p>根据题干“若2023-2025年······每年按2020-2022年的年均增速增长，则2025年我国游戏市场销售收入将达到”，可判定本题为现期计算问题。定位图形材料可得，2022年和2019年我国游戏市场销售收入分别为2659和2309亿元，设2020-2022年的年均增速为r，则<img src=\"assets/img/gongshi/formula-ed35b7696f46f6c4.png\" class=\"tex\">，因此<img src=\"assets/img/gongshi/formula-aedd7b996ac71ba9.png\" class=\"tex\">。若2023-2025年与2020-2022年保持相同的年均增速，则2025年我国游戏市场销售收入<img src=\"assets/img/gongshi/formula-4ff8984cd261291f.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-06e71cfbec90ca39.png\" class=\"tex\">亿元，与C项最接近。</p><p>故正确答案为C。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"资料分析"},"idx":127,"pid":"p4999a05dc1"},{"qid":"15121378","no":20,"type":"增长","module":"资料分析","stem":"<p>2022年我国游戏市场销售收入增长率与2021年相差：</p>","material":"<p><img src=\"assets/img/timu/18d7726c16b25fd.png\" class=\"fig\" style=\"width:700px;height:323px;\"></p><p><img src=\"assets/img/timu/18d7726cf6d007b.png\" class=\"fig\" style=\"width:615px;height:375px;\"></p>","materialNo":4,"options":[{"k":"A","t":"3.9个百分点"},{"k":"B","t":"8.4个百分点"},{"k":"C","t":"12.7个百分点"},{"k":"D","t":"16.7个百分点"}],"answer":"D","multi":false,"explanation":"<p>根据题干“2022年······增长率与2021年相差”，结合选项为“百分点”，可判定本题为一般增长率问题。定位图形材料可得，2022-2020年我国游戏市场销售收入分别为2659、2965、2787亿元。根据公式：增长率<img src=\"assets/img/gongshi/formula-9ad7a88fa1bfefd7.png\" class=\"tex\">，则2022年我国游戏市场销售收入增长率<img src=\"assets/img/gongshi/formula-172c560d17ae5c5d.png\" class=\"tex\">，2021年增长率<img src=\"assets/img/gongshi/formula-d4b63aeaa62a1955.png\" class=\"tex\">。故2022年我国游戏市场销售收入增长率与2021年相差6.4%-（-10.2%）=16.6%，即16.6个百分点，与D项最接近。</p><p>故正确答案为D。</p>","from":{"file":"2024年江苏省公务员录用考试《行测》题（C类）（网友回忆版）.md","module":"资料分析"},"idx":128,"pid":"p4999a05dc1"}]};
